  (gen_random_uuid(), (SELECT id FROM app.universities WHERE code = '238032'), 'Climb Higher Scholarship - Level 1 (Nonresident)', 'undergraduate', 18000.00, 'First-time incoming nonresident freshman with GPA 3.8+ AND SAT 1360+ / ACT 30+. Renewable 4 years ($72,000 total) with 2.75+ GPA and 30 credits/yr.', '2027-02-01', '{"provider": "West Virginia University", "type": "merit", "renewable": true, "coverage_type": "annual_award", "min_gpa4": 3.8, "source_basis": "Group A research file (CDS 2024-25); not verified against school aid page", "verified": false, "is_active": true}'::jsonb, 'https://dataoffice.wvu.edu/files/d/d0809710-b583-4b08-8214-e297d97326d5/cds-2024-2025-wvu-final.pdf'),
  (gen_random_uuid(), (SELECT id FROM app.universities WHERE code = '238032'), 'Climb Higher Scholarship - Level 3 (Nonresident)', 'undergraduate', 13000.00, 'First-time incoming nonresident freshman with GPA 3.50 - 3.79 (test-optional). Renewable 4 years ($52,000 total) with 2.75+ GPA and 30 credits/yr.', '2027-02-01', '{"provider": "West Virginia University", "type": "merit", "renewable": true, "coverage_type": "annual_award", "min_gpa4": 3.5, "source_basis": "Group A research file (CDS 2024-25); not verified against school aid page", "verified": false, "is_active": true}'::jsonb, 'https://dataoffice.wvu.edu/files/d/d0809710-b583-4b08-8214-e297d97326d5/cds-2024-2025-wvu-final.pdf'),
  (gen_random_uuid(), (SELECT id FROM app.universities WHERE code = '227216'), 'UNT Excellence Scholarship (Top Tier)', 'undergraduate', 12000.00, 'First-time freshman merit award based on high school class rank and unweighted GPA. Qualifies international students for Texas State In-State Tuition Waiver. Renewable 4 years ($48,000 total) with 3.0+ GPA and 24 credit hours/yr.', '2027-03-01', '{"provider": "University of North Texas", "type": "merit", "renewable": true, "coverage_type": "annual_award", "min_gpa4": 3.5, "source_basis": "Group A research file (CDS 2024-25); not verified against school aid page", "verified": false, "is_active": true}'::jsonb, 'https://institutionalresearch.unt.edu/cds_univnorthtx_final2024-2025.pdf'),
  (gen_random_uuid(), (SELECT id FROM app.universities WHERE code = '227216'), 'UNT Achievement Scholarship', 'undergraduate', 1000.00, 'Competitive merit award for admitted freshmen. Importantly grants eligibility for the Texas State Non-Resident Tuition Waiver (saving ~$12,300/yr in out-of-state tuition fees). Renewable 4 years with 3.0+ GPA.', '2027-03-01', '{"provider": "University of North Texas", "type": "merit", "renewable": true, "coverage_type": "annual_award", "min_gpa4": 3, "source_basis": "Group A research file (CDS 2024-25); not verified against school aid page", "verified": false, "is_active": true}'::jsonb, 'https://institutionalresearch.unt.edu/cds_univnorthtx_final2024-2025.pdf'),
  (gen_random_uuid(), (SELECT id FROM app.universities WHERE code = '182290'), 'UNR Presidential Scholarship (Non-Resident)', 'undergraduate', 10000.00, 'Top-tier merit award for high-achieving non-resident and international freshmen with high school GPA 3.80-4.00. Renewable 4 years ($40,000 total) with 3.50+ cumulative GPA.', '2027-02-01', '{"provider": "University of Nevada, Reno", "type": "merit", "renewable": true, "coverage_type": "annual_award", "min_gpa4": 3.8, "source_basis": "Group A research file (CDS 2024-25); not verified against school aid page", "verified": false, "is_active": true}'::jsonb, 'https://dataden.unr.edu/Resources/CDS/CDS_2024-2025.pdf'),
  (gen_random_uuid(), (SELECT id FROM app.universities WHERE code = '182290'), 'UNR International Student Scholarship', 'undergraduate', 5000.00, 'Automatic merit award for incoming international freshmen with full admission and minimum cumulative GPA 3.0. Range $3,000-$5,000/yr ($12,000-$20,000 total). Renewable annually.', '2027-02-01', '{"provider": "University of Nevada, Reno", "type": "merit", "renewable": true, "coverage_type": "annual_award", "min_gpa4": 3, "source_basis": "Group A research file (CDS 2024-25); not verified against school aid page", "verified": false, "is_active": true}'::jsonb, 'https://dataden.unr.edu/Resources/CDS/CDS_2024-2025.pdf'),
  (gen_random_uuid(), (SELECT id FROM app.universities WHERE code = '219471'), 'Coyote Beginnings Scholarship (International)', 'undergraduate', 4000.00, 'Automatically awarded at admission to international first-time freshmen based on high school GPA. Value up to $4,000/yr ($16,000/4yr). Renewable 4 years with good standing.', '2027-06-01', '{"provider": "University of South Dakota", "type": "merit", "renewable": true, "coverage_type": "annual_award", "min_gpa4": 3, "source_basis": "Group A research file (CDS 2024-25); not verified against school aid page", "verified": false, "is_active": true}'::jsonb, 'https://www.usd.edu/-/media/Project/USD/DotEdu/About/Departments-Offices-and-Resources/Institutional-Research-Planning-and-Assessment/USD-Common-Data-Set.pdf'),
  (gen_random_uuid(), (SELECT id FROM app.universities WHERE code = '219471'), 'Coyote Beginnings Grant (Test Score Add-On)', 'undergraduate', 2500.00, 'Stackable grant awarded to international freshmen submitting qualifying standardized test scores (SAT/ACT). Value $1,500-$2,500/yr ($6,000-$10,000/4yr). Combined with Coyote Beginnings Scholarship covers over half tuition.', '2027-06-01', '{"provider": "University of South Dakota", "type": "merit", "coverage_type": "annual_award", "min_gpa4": 3, "source_basis": "Group A research file (CDS 2024-25); not verified against school aid page", "verified": false, "is_active": true}'::jsonb, 'https://www.usd.edu/-/media/Project/USD/DotEdu/About/Departments-Offices-and-Resources/Institutional-Research-Planning-and-Assessment/USD-Common-Data-Set.pdf'),
  (gen_random_uuid(), (SELECT id FROM app.universities WHERE code = '229027'), 'UTSA Distinguished Presidential Scholarship', 'undergraduate', 6000.00, 'First-time incoming freshman merit scholarship for top 25% class rank / GPA. Award of $1,000+ per year qualifies international students for Texas Non-Resident Tuition Waiver. Renewable 4 years ($24,000 total) with 2.5+ GPA and 30 credits/yr.', '2027-01-15', '{"provider": "University of Texas at San Antonio", "type": "merit", "renewable": true, "coverage_type": "annual_award", "min_gpa4": 3.5, "source_basis": "Group A research file (CDS 2024-25); not verified against school aid page", "verified": false, "is_active": true}'::jsonb, 'https://www.utsa.edu/ir/docs/resources/commonDataSet/CDS_2024-2025.xlsx'),
  (gen_random_uuid(), (SELECT id FROM app.universities WHERE code = '229027'), 'UTSA Distinguished Achievement Award', 'undergraduate', 2000.00, 'Automatically awarded freshman merit scholarship. Award of $1,000+ grants eligibility for Texas In-State Tuition Waiver (saving ~$13,500/yr). Renewable 4 years with 2.5+ GPA and 30 credits/yr.', '2027-01-15', '{"provider": "University of Texas at San Antonio", "type": "merit", "renewable": true, "coverage_type": "annual_award", "min_gpa4": 3, "source_basis": "Group A research file (CDS 2024-25); not verified against school aid page", "verified": false, "is_active": true}'::jsonb, 'https://www.utsa.edu/ir/docs/resources/commonDataSet/CDS_2024-2025.xlsx'),
  (gen_random_uuid(), (SELECT id FROM app.universities WHERE code = '102094'), 'Global Freshman Scholars Award (Tier 1)', 'undergraduate', 10000.00, 'First-time incoming international freshmen on F-1 visa. Requires GPA 3.5+ and SAT 1420+ (or ACT 32+). Renewable for 4 years ($40,000 total) with 3.0 college GPA.', '2027-02-15', '{"provider": "University of South Alabama", "type": "merit", "renewable": true, "coverage_type": "annual_award", "min_gpa4": 3.5, "source_basis": "Group A research file (CDS 2024-25); not verified against school aid page", "verified": false, "is_active": true}'::jsonb, 'https://www.southalabama.edu/departments/institutionalresearch/resources/usa-cds-2024-2025.pdf'),
  (gen_random_uuid(), (SELECT id FROM app.universities WHERE code = '102094'), 'Global Freshman Scholars Award (Tier 2/3)', 'undergraduate', 6000.00, 'Requires GPA 3.0+ and SAT 1260-1350 (or ACT 27-31). Awarded automatically upon admission. Renewable for 4 years ($24,000 total).', '2027-02-15', '{"provider": "University of South Alabama", "type": "merit", "renewable": true, "coverage_type": "annual_award", "min_gpa4": 3, "source_basis": "Group A research file (CDS 2024-25); not verified against school aid page", "verified": false, "is_active": true}'::jsonb, 'https://www.southalabama.edu/departments/institutionalresearch/resources/usa-cds-2024-2025.pdf'),
  (gen_random_uuid(), (SELECT id FROM app.universities WHERE code = '200332'), 'International Student Scholarship (Tier 1)', 'undergraduate', 3000.00, 'Incoming international undergraduates with US equivalent cGPA 3.50-4.00. $1,500/semester up to 8 semesters ($12,000 total). Automatic consideration upon admission.', '2027-07-01', '{"provider": "North Dakota State University", "type": "merit", "coverage_type": "annual_award", "min_gpa4": 3.5, "source_basis": "Group A research file (CDS 2024-25); not verified against school aid page", "verified": false, "is_active": true}'::jsonb, 'https://www.ndsu.edu/sites/default/files/fileadmin/oira/Common_Data_Set/NDSU_CDS_2024-2025.xlsx'),
  (gen_random_uuid(), (SELECT id FROM app.universities WHERE code = '200332'), 'International Student Scholarship (Tier 2)', 'undergraduate', 2000.00, 'Incoming international undergraduates with US equivalent cGPA 3.00-3.49. $1,000/semester up to 8 semesters ($8,000 total). Automatic review upon admission.', '2027-07-01', '{"provider": "North Dakota State University", "type": "merit", "coverage_type": "annual_award", "min_gpa4": 3, "source_basis": "Group A research file (CDS 2024-25); not verified against school aid page", "verified": false, "is_active": true}'::jsonb, 'https://www.ndsu.edu/sites/default/files/fileadmin/oira/Common_Data_Set/NDSU_CDS_2024-2025.xlsx'),
  (gen_random_uuid(), (SELECT id FROM app.universities WHERE code = '228459'), 'President''s Honor Scholarship & In-State Waiver', 'undergraduate', 10000.00, 'Top tier freshman merit award ($10,000/yr). Non-resident/international recipients qualifying for $1,000+ receive the Texas In-State Tuition Waiver, saving an additional ~$12,300/yr (Total value ~$22,300/yr). Renewable for 4 years.', '2026-12-15', '{"provider": "Texas State University", "type": "merit", "renewable": true, "coverage_type": "annual_award", "min_gpa4": 3.8, "source_basis": "Group A research file (CDS 2024-25); not verified against school aid page", "verified": false, "is_active": true}'::jsonb, 'https://dair.txst.edu/reports/cds.html'),
  (gen_random_uuid(), (SELECT id FROM app.universities WHERE code = '228459'), 'Texas State Achievement Scholarship & Waiver', 'undergraduate', 6000.00, 'Freshman merit award of $6,000/yr. Triggers Texas In-State Tuition Waiver for nonresidents, saving ~$12,300/yr on out-of-state tuition. Renewable with 3.25 GPA and 30 credits/yr.', '2026-12-15', '{"provider": "Texas State University", "type": "merit", "renewable": true, "coverage_type": "annual_award", "min_gpa4": 3.5, "source_basis": "Group A research file (CDS 2024-25); not verified against school aid page", "verified": false, "is_active": true}'::jsonb, 'https://dair.txst.edu/reports/cds.html'),
  (gen_random_uuid(), (SELECT id FROM app.universities WHERE code = '136172'), 'First Coast Out-of-State Waiver Scholarship', 'undergraduate', 14000.00, 'Incoming non-resident/international freshman students with GPA 3.9+ and SAT 1300+ / ACT 28+. Automatic review upon admission. Covers up to $14,000/yr of out-of-state tuition fees.', '2027-01-15', '{"provider": "University of North Florida", "type": "merit", "coverage_type": "annual_award", "min_gpa4": 3.9, "source_basis": "Group A research file (CDS 2024-25); not verified against school aid page", "verified": false, "is_active": true}'::jsonb, 'https://www.unf.edu/ir/common-data-set/2024.html'),
  (gen_random_uuid(), (SELECT id FROM app.universities WHERE code = '136172'), 'Atlantic Out-of-State Waiver Scholarship', 'undergraduate', 10000.00, 'Nonresident/international freshmen with GPA 3.7+ and SAT 1230+ / ACT 26+. Automatic tuition waiver award of ~$10,000/yr for up to 4 years.', '2027-01-15', '{"provider": "University of North Florida", "type": "merit", "coverage_type": "annual_award", "min_gpa4": 3.7, "source_basis": "Group A research file (CDS 2024-25); not verified against school aid page", "verified": false, "is_active": true}'::jsonb, 'https://www.unf.edu/ir/common-data-set/2024.html'),
  (gen_random_uuid(), (SELECT id FROM app.universities WHERE code = '433660'), 'Blue & Green Scholars Award (Nonresident)', 'undergraduate', 15000.00, 'Top tier non-resident freshman merit award ($15,000/yr). Requires GPA 3.9+ and SAT 1320+ (or ACT 28+). Priority application deadline November 1. Renewable for 4 years ($60,000 total).', '2026-11-01', '{"provider": "Florida Gulf Coast University", "type": "merit", "renewable": true, "coverage_type": "annual_award", "min_gpa4": 3.9, "source_basis": "Group A research file (CDS 2024-25); not verified against school aid page", "verified": false, "is_active": true}'::jsonb, 'https://www.fgcu.edu/planning/institutionalresearch/datareports'),
  (gen_random_uuid(), (SELECT id FROM app.universities WHERE code = '433660'), 'Blue & Green Director''s Award (Nonresident)', 'undergraduate', 10000.00, 'Non-resident freshman award of $10,000/yr for GPA 3.5+ and SAT 1220+ (or ACT 25+). Renewable for 4 years ($40,000 total) with 3.0 cumulative college GPA.', '2026-11-01', '{"provider": "Florida Gulf Coast University", "type": "merit", "renewable": true, "coverage_type": "annual_award", "min_gpa4": 3.5, "source_basis": "Group A research file (CDS 2024-25); not verified against school aid page", "verified": false, "is_active": true}'::jsonb, 'https://www.fgcu.edu/planning/institutionalresearch/datareports')
ON CONFLICT (university_id, name) DO UPDATE SET
    study_level = EXCLUDED.study_level,
    amount_usd = EXCLUDED.amount_usd,
    description = EXCLUDED.description,
