-- 5. Table: app.knowledge_documents (201 rows)
-- Sources: 127 rows from USAS_Du_Lieu_Tu_Van (1).xlsx (05_Du_Lieu_AI 'Đã kiểm chứng')
--          74 rows from du_lieu_tu_van_lam_sach (1).xlsx (Dữ liệu tư vấn làm sạch)
-- Idempotent mechanism: INSERT ... SELECT ... WHERE NOT EXISTS (no extra index created)
-- ==============================================================================
INSERT INTO app.knowledge_documents (id, title, doc_type, status, content, source_url, retrieved_at)
SELECT gen_random_uuid(), v.title, v.doc_type, v.status, v.content, v.source_url, v.retrieved_at::date
FROM (VALUES
  ('Cần điều kiện gì để du học đại học Mỹ?', 'Điều kiện đầu vào', 'verified', 'EducationUSA nêu hồ sơ đại học thường gồm bằng/học bạ THPT (kèm bản dịch tiếng Anh), điểm thi chuẩn hóa khi trường yêu cầu, thư giới thiệu và bài luận. Nếu tiếng Anh không phải tiếng mẹ đẻ, hầu hết trường yêu cầu chứng chỉ tiếng Anh như TOEFL, IELTS. Yêu cầu cụ thể (kể cả mức GPA) do từng trường quy định; EducationUSA không đưa ngưỡng chung.', 'https://educationusa.state.gov/your-5-steps-us-study/complete-your-application/undergraduate
https://educationusa.state.gov/your-5-steps-us-study/research-your-options/undergraduate/prepare-us-standardized-tests', '2026-10-04'),
  ('SAT có bắt buộc không?', 'Thi cử', 'verified', 'Một số trường Mỹ áp dụng chính sách test-optional, tức không yêu cầu điểm SAT/ACT, nhưng nhiều trường vẫn yêu cầu. Học sinh có thể tự nguyện nộp điểm nếu thấy giúp hồ sơ mạnh hơn. Chính sách khác nhau theo trường và theo năm nên cần kiểm tra trang tuyển sinh của từng trường (tính đến 10/2026).', 'https://educationusa.state.gov/your-5-steps-us-study/research-your-options/undergraduate/prepare-us-standardized-tests
https://www.commonapp.org/apply/first-year-students', '2026-10-04'),
  ('Tiếng Anh chưa đủ thì làm sao?', 'Tiếng Anh', 'verified', 'Một số trường cho phép nhập học có điều kiện (conditional admission) với hồ sơ học lực tốt nhưng tiếng Anh cần cải thiện; có thể phải học thêm tiếng Anh hoặc nộp thêm điểm. Ngoài ra có chương trình bridge/pathway vừa nâng tiếng Anh vừa tích lũy tín chỉ. Đây không phải cam kết được nhận vào chương trình chính; mỗi chương trình có thủ tục và hạn riêng.', 'https://educationusa.state.gov/your-5-steps-us-study/complete-your-application/intensive-english-programs', '2026-10-04'),
  ('Nên vào thẳng đại học hay học cao đẳng cộng đồng 2+2?', 'Lộ trình', 'verified', 'Mô hình 2+2 là con đường chính thống: học hai năm cao đẳng cộng đồng rồi hai năm đại học và nhận cùng bằng cử nhân như học đủ bốn năm tại trường đó. Cao đẳng cộng đồng thường rẻ hơn, lớp nhỏ và hỗ trợ sinh viên quốc tế, quy trình tuyển sinh có thể linh hoạt hơn. Chi tiết chuyển tiếp tùy từng trường nên cần xác định trường đại học mục tiêu sớm. Quy định nội bộ của Bộ Ngoại giao Mỹ (FAM) nêu kế hoạch học cao đẳng cộng đồng rồi chuyển tiếp là phổ biến và không có khác biệt pháp lý giữa cao đẳng cộng đồng và đại học 4 năm về quyền cấp I-20; kết quả phỏng vấn do viên chức lãnh sự quyết định theo từng hồ sơ.', 'https://educationusa.state.gov/your-5-steps-us-study/research-your-options/community-college
https://fam.state.gov/fam/09FAM/09FAM040205.html', '2026-10-04'),
  ('Đang lớp 11, muốn đi sớm thì có cách nào?', 'Lộ trình', 'verified', 'Một số cao đẳng cộng đồng (ví dụ ở bang Washington như Bellevue College) có chương trình International High School Completion cho phép học sinh F-1 lấy cùng lúc bằng THPT bang Washington và bằng Associate chuyển tiếp. Ví dụ điều kiện của Bellevue: từ 16 tuổi, tương đương hoàn thành lớp 10 Mỹ, chưa có bằng THPT; thời gian khoảng 2 năm tùy trình độ tiếng Anh. Điều kiện tuổi và chương trình khác nhau theo trường: Northern Virginia CC yêu cầu F-1 đủ 18 tuổi. Cần hỏi trực tiếp từng trường.', 'https://www.bellevuecollege.edu/international/programs/
https://www.nvcc.edu/admissions/apply/international/index.html', '2026-10-04'),
  ('Chọn trường dựa vào đâu?', 'Chọn trường', 'verified', 'EducationUSA khuyên chọn trường phù hợp với bản thân về học thuật, tài chính và cá nhân (ngành, chi phí, vị trí, môi trường), không dựa vào xếp hạng chính thức vì Mỹ không có hệ thống xếp hạng chính thức. Nên bắt đầu tìm hiểu trước 12–18 tháng. Nguồn không nêu số trường nên nộp.', 'https://educationusa.state.gov/your-5-steps-us-study/research-your-options/undergraduate', '2026-10-04'),
  ('Cần chuẩn bị hồ sơ trước bao lâu?', 'Thời gian', 'verified', 'EducationUSA khuyên bắt đầu tìm hiểu ít nhất 12–18 tháng trước năm học muốn nhập học. Hạn nộp đại học thường từ tháng 11 đến tháng 1 đối với kỳ bắt đầu tháng 9 năm sau. Cao đẳng cộng đồng thường xét hồ sơ rolling hoặc có nhiều hạn trong năm. Hạn chính xác tùy từng trường (tính đến 10/2026).', 'https://educationusa.state.gov/your-5-steps-us-study/research-your-options/undergraduate
https://educationusa.state.gov/your-5-steps-us-study/complete-your-application/undergraduate
https://educationusa.state.gov/your-5-steps-us-study/complete-your-application/community-college', '2026-10-04'),
  ('ED, EA, Regular khác nhau thế nào?', 'Thời gian', 'verified', 'Early Decision (ED) mang tính ràng buộc: nếu đậu phải theo học; Regular Decision (RD) không ràng buộc. Early Action (EA) nộp sớm và thường không ràng buộc (trang định nghĩa của Common App không tải được nên chưa trích trực tiếp). Ví dụ Brown (chỉ minh họa): ED hạn 01/11, RD hạn 05/01. Hạn cụ thể do từng trường quy định; Common App cho biết phụ huynh chỉ cần nộp biểu mẫu nếu nộp theo hạn ED.', 'https://www.commonapp.org/apply/first-year-students
https://admission.brown.edu/first-year', '2026-10-04'),
  ('Có những loại học bổng nào?', 'Học bổng', 'verified', 'Học bổng cho sinh viên quốc tế ở Mỹ chủ yếu do từng trường cấp, gồm học bổng theo thành tích (merit) và hỗ trợ tài chính theo nhu cầu (need-based, phần chênh lệch giữa chi phí và khả năng chi trả của gia đình). EducationUSA lưu ý đa số học bổng chỉ trang trải một phần chi phí và có thể không dành cho sinh viên năm nhất quốc tế. Cao đẳng cộng đồng có hỗ trợ tài chính cho sinh viên quốc tế nhưng ít phổ biến hơn đại học 4 năm. Việc phỏng vấn để cấp học bổng và các loại học bổng chính phủ tùy từng trường/chương trình.', 'https://educationusa.state.gov/your-5-steps-us-study/finance-your-studies/undergraduate
https://educationusa.state.gov/your-5-steps-us-study/finance-your-studies/community-college', '2026-10-04'),
  ('Học thạc sĩ có dễ xin học bổng không?', 'Học bổng', 'verified', 'Học bổng và hỗ trợ tài chính ở bậc sau đại học phụ thuộc từng trường và từng khoa. EducationUSA lưu ý phần lớn học bổng chỉ chi trả một phần chi phí và có thể không dành cho sinh viên quốc tế năm đầu. Trợ giảng (teaching assistant) hoặc trợ lý nghiên cứu (research assistant) có thể đổi lấy miễn học phí và/hoặc tiền hỗ trợ sinh hoạt, nhưng EducationUSA nói điều này ''rất phổ biến ở bậc tiến sĩ'', nên với thạc sĩ cơ hội thường ít chắc chắn hơn và tùy chương trình. Các loại hỗ trợ chính gồm fellowship, teaching assistantship, research assistantship và administrative assistantship.', 'https://educationusa.state.gov/your-5-steps-us-study/finance-your-studies/graduate', '2026-10-04'),
  ('Du học đại học Mỹ tốn bao nhiêu một năm?', 'Chi phí', 'verified', 'Chi phí du học đại học Mỹ khác nhau rất nhiều theo trường nên không có một con số chung. EducationUSA chỉ nêu cấu phần gồm học phí, lệ phí và sinh hoạt phí, nói rõ chi phí thực tế khác nhau theo từng trường và học phí thường tăng khoảng 6–10% mỗi năm. Ví dụ ước tính cho sinh viên quốc tế (chỉ để minh họa, tính đến 10/2026): Texas State University (công lập, đại học, 2025–26) khoảng 40.400 USD; IU Indianapolis (công lập, đại học, 2026–27) khoảng 56.258 USD; MIT (tư thục, đại học, 2026–27) khoảng 92.760 USD (chưa trừ hỗ trợ tài chính); San José City College (cao đẳng cộng đồng, 2026–27) khoảng 27.510 USD. Cần xem trang ''cost of attendance'' của từng trường.', 'https://educationusa.state.gov/your-5-steps-us-study/finance-your-studies/undergraduate
https://www.international.txst.edu/future-or-new-f-1-students/i-20-request/estimated-cost-of-attendance-2026-2027/estimated-cost-of-attendance.html
https://indy.iu.edu/cost-aid/cost-of-attendance/international-cost-attendance.html
https://sfs.mit.edu/undergraduate-students/the-cost-of-attendance/annual-student-budget/
https://sjcc.edu/students/international-students/apply/tuition-and-fees.aspx', '2026-10-04'),
  ('40.000 USD/năm có đủ học thạc sĩ không?', 'Chi phí', 'verified', 'Không có mức chung cho thạc sĩ: mức 40.000 USD/năm có thể đủ với chương trình này nhưng không đủ với chương trình khác, tùy trường, ngành và số tín chỉ. Ví dụ Texas State University ước tính tổng khoảng 31.600 USD cho sinh viên thạc sĩ (không cư trú, 6 tín chỉ/kỳ, 2025–26, gồm học phí 11.200 và sinh hoạt 20.400), còn IU Indianapolis ghi chi phí không gồm học phí cho năm đầu (9 tháng, 2026–27) khoảng 18.441 USD và học phí thạc sĩ tính riêng theo chương trình. EducationUSA lưu ý học bổng thường chỉ trả một phần và trợ giảng/trợ nghiên cứu (miễn học phí/stipend) ''rất phổ biến ở bậc tiến sĩ''. Khi xin visa, lãnh sự yêu cầu chứng minh đủ tiền cho năm học đầu tiên.', 'https://www.international.txst.edu/future-or-new-f-1-students/i-20-request/estimated-cost-of-attendance-2026-2027/estimated-cost-of-attendance.html
https://indy.iu.edu/cost-aid/cost-of-attendance/international-cost-attendance.html
https://educationusa.state.gov/your-5-steps-us-study/finance-your-studies/graduate
https://fam.state.gov/fam/09FAM/09FAM040205.html', '2026-10-04'),
  ('Hồ sơ nộp trường đại học gồm gì?', 'Hồ sơ', 'verified', 'Hồ sơ đại học thường gồm bằng/học bạ THPT có bản dịch tiếng Anh, điểm thi chuẩn hóa nếu cần, thư giới thiệu và bài luận. Common App cũng cho biết mỗi trường tự chọn yêu cầu về thư giới thiệu và bài luận. Giấy tờ tài chính và hộ chiếu tùy trường và thường cần ở giai đoạn I-20 và visa.', 'https://educationusa.state.gov/your-5-steps-us-study/complete-your-application/undergraduate
https://www.commonapp.org/apply/first-year-students', '2026-10-04'),
  ('Hồ sơ thạc sĩ gồm gì?', 'Hồ sơ', 'verified', 'Theo EducationUSA, hồ sơ cao học thường có biểu mẫu thông tin cá nhân, bài luận cá nhân (personal statement), bảng điểm đại học và thư giới thiệu từ giảng viên, quản lý hoặc người từng làm việc cùng. Ngoài ra nhiều chương trình yêu cầu điểm thi chuẩn hóa như GRE hoặc GMAT, và nếu tiếng Anh không phải tiếng mẹ đẻ thì cần chứng chỉ tiếng Anh. Yêu cầu cụ thể (kể cả CV, portfolio, dự án) khác nhau giữa các trường và từng khoa, nên phải xem trang tuyển sinh sau đại học của chương trình.', 'https://educationusa.state.gov/complete-your-us-application-graduate
https://educationusa.state.gov/your-5-steps-us-study/research-your-options/graduate/prepare-us-standardized-tests', '2026-10-04'),
  ('Học thạc sĩ khác ngành đại học được không?', 'Hồ sơ', 'verified', 'EducationUSA cho biết với đa số chương trình sau đại học, bằng cử nhân đúng chuyên ngành không bắt buộc, nhưng một số chương trình yêu cầu học phần tiên quyết (prerequisite). Ví dụ ngành y cần nhiều môn khoa học dù bằng cử nhân là ngành khác. Vì vậy học khác ngành là có thể, còn việc có phải học bù (bridge/prerequisites) hay không tùy từng chương trình; cần xem yêu cầu đầu vào trên trang của khoa.', 'https://educationusa.state.gov/your-5-steps-us-study/research-your-options/graduate/what-graduate-student', '2026-10-04'),
  ('I-20 là gì, lấy thế nào?', 'I-20', 'verified', 'I-20 (Certificate of Eligibility for Nonimmigrant Student Status) do trường được SEVP chứng nhận cấp sau khi nhận hồ sơ nhập học và nhập thông tin của bạn vào hệ thống SEVIS. Bạn phải xuất trình I-20 (có chữ ký của bạn và của trường) khi phỏng vấn visa. Visa F-1 gắn với trường ghi trên I-20, nên mỗi lần xin visa dùng I-20 của trường bạn sẽ theo học. Các bước trung gian như thư mời kèm học bổng, tiền đặt cọc, giấy tờ tài chính trường yêu cầu là quy định riêng của từng trường, hãy hỏi phòng tuyển sinh hoặc DSO của trường.', 'https://adoption.state.gov/content/travel/en/us-visas/study/student-visa.html
https://www.ecfr.gov/current/title-8/part-214/section-214.2
https://educationusa.state.gov/your-5-steps-us-study/apply-your-student-visa/undergraduate', '2026-10-04'),
  ('Chứng minh tài chính cần gì?', 'Tài chính', 'verified', 'Theo quy định, sinh viên F-1 phải có bằng chứng tài chính tương ứng số tiền ghi trên I-20 (học phí, sinh hoạt phí). Viên chức lãnh sự có thể yêu cầu thêm bằng chứng về việc bạn sẽ chi trả học phí, sinh hoạt và đi lại như thế nào. ĐSQ Mỹ tại Việt Nam lưu ý giấy tờ tài chính không bắt buộc và nhiều viên chức không xem kỹ vì thông tin đã có trong đơn DS-160. Danh sách loại giấy tờ cụ thể (sổ tiết kiệm, giấy phép kinh doanh, bất động sản, xe...) không được liệt kê chính thức. Nguồn tiền cần có thật và khớp với lời khai; giấy tờ giả có thể dẫn đến cấm nhập cảnh vĩnh viễn.', 'https://adoption.state.gov/content/travel/en/us-visas/study/student-visa.html
https://www.ecfr.gov/current/title-8/part-214/section-214.2
https://vn.usembassy.gov/frequently-asked-questions-nonimmigrant-visas/', '2026-10-04'),
  ('Quy trình xin visa F-1 thế nào?', 'Visa', 'verified', 'Trình tự theo hướng dẫn chính thức: trường cấp I-20 và đăng ký SEVIS, đóng phí SEVIS I-901 (phải đóng trước khi visa được cấp), điền DS-160 và in trang xác nhận, đóng phí hồ sơ visa (MRV) và đặt lịch phỏng vấn tại ĐSQ Hà Nội hoặc TLSQ TP.HCM qua cổng đặt lịch của ĐSQ (usvisascheduling.com). Visa F-1 cho sinh viên mới có thể được cấp tối đa 365 ngày trước ngày bắt đầu khóa học, nhưng chỉ được nhập cảnh Mỹ tối đa 30 ngày trước ngày khai giảng. Thời gian chờ lịch phỏng vấn thay đổi theo địa điểm, mùa và loại visa nên nên nộp sớm. Thứ tự các bước có thể khác nhau chút ít giữa các ĐSQ.', 'https://adoption.state.gov/content/travel/en/us-visas/study/student-visa.html
https://www.ecfr.gov/current/title-8/part-214/section-214.13
https://vn.usembassy.gov/visas/
https://vn.usembassy.gov/nonimmigrant-visas/
https://adoption.state.gov/content/travel/en/us-visas/visa-information-resources/wait-times.html', '2026-10-04'),
  ('Phí xin visa F-1 là bao nhiêu?', 'Visa', 'verified', 'Phí SEVIS I-901 cho F-1 là 350 USD (8 CFR 214.13). Phí hồ sơ visa (MRV) cho visa F là 185 USD, không hoàn lại. Visa Integrity Fee 250 USD: luật HR-1 (2025) quy định thu khi cấp visa không định cư, nhưng thông báo chính thức tháng 7/2025 nói phí này cần phối hợp liên cơ quan và sẽ triển khai sau; trên trang phí visa của Bộ Ngoại giao Mỹ (truy cập 10/2026) chưa thấy dòng phí này. Vì vậy chưa xác nhận được là đang thu, cần kiểm tra lại trên trang phí của Bộ Ngoại giao Mỹ trước khi báo cho học sinh. Mức phí có thể thay đổi; các số trên là mức tính đến 10/2026.', 'https://www.ecfr.gov/current/title-8/part-214/section-214.13
https://www.ecfr.gov/current/title-22/part-22/section-22.1
https://adoption.state.gov/content/travel/en/us-visas/visa-information-resources/fees/fees-visa-services.html
https://adoption.state.gov/content/travel/en/us-visas/study/student-visa.html
https://www.federalregister.gov/documents/2025/07/22/2025-13738/uscis-immigration-fees-required-by-hr-1-reconciliation-bill', '2026-10-04'),
  ('Phỏng vấn visa hỏi gì, cần chứng minh gì?', 'Visa', 'verified', 'Viên chức lãnh sự phỏng vấn để xác định bạn có đủ điều kiện visa sinh viên; theo luật (INA 214(b)) người nộp đơn bị coi là có ý định định cư cho đến khi chứng minh được ngược lại, bằng các ràng buộc với Việt Nam (gia đình, việc làm, tài sản; với người trẻ có thể xét học lực, việc làm của cha mẹ, kế hoạch dài hạn). Có thể được hỏi về học lực, ý định về nước sau khi học và cách chi trả toàn bộ chi phí. EducationUSA khuyên giải thích rõ vì sao học ở Mỹ, cách chi trả và kế hoạch sau khi học vì buổi phỏng vấn rất ngắn. Nên trả lời trung thực, ngắn gọn; không có đáp án chuẩn cho mọi trường hợp. Việc ''luyện bằng câu chuyện thật, không học thuộc'' là lời khuyên thực tế, không phải quy định chính thức.', 'https://vn.usembassy.gov/frequently-asked-questions-nonimmigrant-visas/
https://adoption.state.gov/content/travel/en/us-visas/visa-information-resources/visa-denials.html
https://adoption.state.gov/content/travel/en/us-visas/study/student-visa.html
https://educationusa.state.gov/your-5-steps-us-study/apply-your-student-visa', '2026-10-04'),
  ('Được sang Mỹ sớm nhất khi nào?', 'Nhập cảnh', 'verified', 'Theo quy định liên bang (8 CFR 214.2(f)), sinh viên F-1 có thể được nhập cảnh sớm nhất 30 ngày trước ngày báo danh/ngày bắt đầu chương trình ghi trên I-20; mốc này cũng được giữ trong quy tắc D/S mới (đang bị tạm hoãn). Khi nhập cảnh cần có I-20 do trường được SEVP chứng nhận cấp và bằng chứng tài chính tương ứng với số tiền trên I-20. Hộ chiếu, visa F-1 và biên lai phí SEVIS I-901 cũng là giấy tờ thông thường phải mang theo (theo hướng dẫn của Study in the States; trang này bị chặn nên chưa đọc trực tiếp). Thư mời nhập học không phải giấy tờ bắt buộc theo quy định; sĩ quan CBP quyết định cuối cùng khi nhập cảnh.', 'https://www.ecfr.gov/api/versioner/v1/full/2026-08-11/title-8.xml?part=214&section=214.2', '2026-10-04'),
  ('Sang Mỹ rồi cần làm gì đầu tiên?', 'Nhập cảnh', 'verified', 'Quy định liên bang không đặt mốc ''10 ngày'' để sinh viên mới báo danh; trường (DSO) báo cho SEVIS việc sinh viên đã ghi danh hay không đến (no-show) mỗi kỳ, chậm nhất 30 ngày sau hạn đăng ký lớp, nên sinh viên cần liên hệ DSO và đăng ký lớp đúng hạn trường quy định. Mốc 10 ngày trong quy định là hạn báo địa chỉ cư trú hoặc đổi tên mới cho DSO. Sinh viên chuyển trường phải liên hệ DSO trường mới trong vòng 15 ngày kể từ ngày bắt đầu chương trình. Tuần định hướng, đóng học phí và thời hạn báo danh cụ thể do từng trường quy định, nên cần hỏi DSO.', 'https://www.ecfr.gov/api/versioner/v1/full/2026-08-11/title-8.xml?part=214&section=214.2
https://www.ecfr.gov/api/versioner/v1/full/2026-08-11/title-8.xml?part=214&section=214.3', '2026-10-04'),
  ('Du học sinh F-1 được đi làm không?', 'Việc làm', 'verified', 'Việc làm trong khuôn viên không quá 20 giờ/tuần khi trường đang học, được làm toàn thời gian khi nghỉ học hoặc nghỉ hè. Làm ngoài trường cần được cấp phép; CPT (thực tập gắn với chương trình học) thường yêu cầu đã học đủ một năm học đầy đủ, nhưng có ngoại lệ cho một số chương trình sau đại học bắt buộc thực tập ngay. OPT cho tối đa 12 tháng ở mỗi bậc học; sinh viên có bằng thuộc danh sách ngành STEM của DHS có thể xin thêm 24 tháng, với điều kiện nhà tuyển dụng tham gia E-Verify và hoàn thành kế hoạch đào tạo I-983. Mọi hình thức làm việc ngoài việc làm trong trường đều cần DSO xác nhận/ủy quyền trước khi bắt đầu.', 'https://www.ecfr.gov/api/versioner/v1/full/2026-08-11/title-8.xml?part=214&section=214.2', '2026-10-04'),
  ('Ở ký túc xá hay tự thuê?', 'Chỗ ở', 'verified', 'Quy định nhà ở phụ thuộc từng trường. Một số trường bắt buộc sinh viên quốc tế năm nhất ở ký túc xá, ví dụ University of Missouri–St. Louis (sinh viên quốc tế mới đến Mỹ), Youngstown State University (ở cả năm học, có thể xin miễn trừ theo điều kiện) và Oregon State University (sinh viên năm nhất toàn thời gian). Nhiều cao đẳng cộng đồng không có ký túc xá, ví dụ Tacoma Community College có chương trình homestay và hỗ trợ tìm căn hộ nhưng hợp đồng thuê nhà cần từ đủ 18 tuổi. Với học sinh dưới 18 tuổi, quy định riêng (tuổi tối thiểu, homestay bắt buộc, đăng ký sớm) khác nhau theo trường nên cần hỏi DSO/phòng nhà ở của trường.', 'https://www.umsl.edu/global/admissions/admitted/housing.html
https://ysu.edu/housing-and-residence-life/housing-international-students
https://uhds.oregonstate.edu/housing-options/international-student-housing-and-dining
https://www.tacomacc.edu/costs-admission/admission-process/international/offcampus', '2026-10-04'),
  ('Ngoại khóa và bài luận quan trọng thế nào?', 'Ngoại khóa, bài luận', 'verified', 'EducationUSA mô tả bài luận là cơ hội viết về sở thích, mục tiêu dài hạn và điểm mạnh, và là một trong những phần quan trọng nhất của hồ sơ. Mức độ coi trọng ngoại khóa và cách trường đánh giá khác nhau theo từng trường.', 'https://educationusa.state.gov/your-5-steps-us-study/complete-your-application/undergraduate', '2026-10-04'),
  ('Đã bị từ chối visa, lần phỏng vấn sau cần thay đổi gì, có đậu được không?', 'Visa', 'verified', 'Từ chối theo 214(b) không có thủ tục kháng cáo, nhưng bạn có thể nộp lại bất kỳ lúc nào nếu có thông tin mới hoặc hoàn cảnh thay đổi đáng kể; phải làm đơn DS-160 mới, đóng lại phí visa và đặt lịch phỏng vấn mới, do viên chức khác xét. ĐSQ khuyên người bị từ chối nhiều hơn một lần trong 6 tháng gần đây không nên nộp lại nếu hoàn cảnh chưa thay đổi đáng kể vì kết quả khó khác đi. Không thấy quy định giới hạn số lần nộp. Phí SEVIS đã đóng không phải đóng lại nếu nộp lại cùng loại visa trong 12 tháng kể từ lần từ chối. Ảnh hưởng đến visa du lịch đang có và việc hoàn tiền cọc của trường: không có thông tin chính thức; tiền cọc tùy chính sách từng trường (hỏi DSO hoặc trường).', 'https://adoption.state.gov/content/travel/en/us-visas/visa-information-resources/visa-denials.html
https://vn.usembassy.gov/frequently-asked-questions-nonimmigrant-visas/
https://adoption.state.gov/content/travel/en/us-visas/study/student-visa.html
https://www.ecfr.gov/current/title-8/part-214/section-214.13', '2026-10-04'),
  ('Tiếng Anh yếu, chưa có chứng chỉ thì phỏng vấn visa được không? Phỏng vấn bằng tiếng Việt được không?', 'Visa', 'verified', 'Chứng chỉ tiếng Anh không nằm trong danh sách giấy tờ bắt buộc để phỏng vấn (chỉ cần hộ chiếu, biên lai phí, trang xác nhận DS-160 và I-20); tuy nhiên viên chức có thể yêu cầu điểm thi chuẩn hóa mà trường Mỹ đòi hỏi. Phỏng vấn tại ĐSQ/TLSQ có thể thực hiện bằng tiếng Việt hoặc tiếng Anh tùy bạn chọn. Nếu I-20 ghi bạn đã đủ trình độ tiếng Anh, hãy chuẩn bị thể hiện trình độ đó tại buổi phỏng vấn. Trình độ cần thiết để theo học do trường quyết định.', 'https://vn.usembassy.gov/frequently-asked-questions-nonimmigrant-visas/
https://adoption.state.gov/content/travel/en/us-visas/study/student-visa.html
https://vn.usembassy.gov/nonimmigrant-visas/', '2026-10-04'),
  ('GPA thấp, từng rớt môn có ảnh hưởng hồ sơ và phỏng vấn visa không? Nên nói GPA nào?', 'Hồ sơ', 'verified', 'GPA do từng trường xét khi tuyển sinh; viên chức visa không được yêu cầu một mức GPA hay điểm thi chuẩn hóa cụ thể, và thường không đánh giá lại trình độ của người đã có I-20. Tuy nhiên viên chức phải chú ý trường hợp học bạ bị làm giả/sửa hoặc trường nhận hồ sơ dựa trên khóa học trước đó không tương đương. Vì vậy cần khai đúng điểm trên học bạ thật; việc GPA thấp ảnh hưởng tới nhận vào trường tùy từng trường.', 'https://fam.state.gov/fam/09FAM/09FAM040205.html', '2026-10-04'),
  ('Có người thân ở Mỹ hoặc đang có hồ sơ bảo lãnh định cư thì có ảnh hưởng visa du học không, có phải khai không?', 'Visa', 'verified', 'ĐSQ Mỹ tại Việt Nam khuyên khai đầy đủ, trung thực về người thân ở Mỹ, hồ sơ bảo lãnh định cư đang nộp và việc từng bị từ chối visa. Nếu viên chức phát hiện che giấu hoặc khai sai, đơn sẽ bị từ chối và có thể bị cấm nhập cảnh vĩnh viễn. Có người thân hay hồ sơ bảo lãnh không tự động dẫn đến từ chối, nhưng viên chức sẽ xem xét kỹ ý định tạm trú theo điều 214(b). Việc ''chọn trường khác bang với người thân'' chỉ là lời khuyên của cộng đồng, không có cơ sở chính thức.', 'https://vn.usembassy.gov/frequently-asked-questions-nonimmigrant-visas/
https://adoption.state.gov/content/travel/en/us-visas/visa-information-resources/visa-denials.html', '2026-10-04'),
  ('Đi phỏng vấn visa cần mang giấy tờ gì; học sinh nhỏ tuổi có cần bố mẹ đi cùng; thủ tục tại ĐSQ thế nào?', 'Visa', 'verified', 'Giấy tờ bắt buộc: hộ chiếu, trang xác nhận DS-160, biên lai phí visa, ảnh (nếu tải ảnh lỗi) và với sinh viên là Form I-20 đã ký; ngày sinh trên hộ chiếu phải khớp giấy khai sinh hoặc CCCD, mã vạch DS-160 phải khớp mã vạch trên lịch hẹn. Học bạ, điểm thi, giấy tờ tài chính chỉ mang khi viên chức cần làm rõ, ĐSQ không khuyến khích mang nhiều giấy tờ. Trẻ dưới 17 tuổi phải có cha/mẹ hoặc người giám hộ hợp pháp đi cùng (mang giấy khai sinh của trẻ và CCCD/hộ chiếu của cha mẹ). Không được mang điện thoại và thiết bị điện tử vào ĐSQ/TLSQ, không mang túi lớn; người thứ ba khác không được vào phòng phỏng vấn. Yêu cầu ''bản sao phải công chứng'' không thấy trên nguồn chính thức.', 'https://vn.usembassy.gov/frequently-asked-questions-nonimmigrant-visas/
https://vn.usembassy.gov/nonimmigrant-visas/
https://vn.usembassy.gov/visas/important-visa-information/
https://adoption.state.gov/content/travel/en/us-visas/study/student-visa.html', '2026-10-04'),
  ('Đang học ở Mỹ, về Việt Nam có phải phỏng vấn gia hạn visa không, có rủi ro gì?', 'Visa', 'verified', 'Bạn cần visa F-1 còn hạn khi nhập cảnh Mỹ; nếu visa hết hạn trong lúc về Việt Nam, bạn phải xin visa mới tại ĐSQ/TLSQ với quy trình giống lần đầu. Từ 01/10/2025 hầu hết người xin visa không định cư đều phải phỏng vấn trực tiếp; danh mục được miễn phỏng vấn chỉ gồm một số loại ngoại giao/chính thức, B-1/B-2 gia hạn trong 12 tháng và H-2A, không có F-1. Sinh viên đang học (continuing student) có thể được cấp visa bất cứ lúc nào miễn còn theo học tại trường SEVP và có trong SEVIS. Viên chức có thể hỏi về học lực, tiến độ học; GPA thấp hay đổi trường có thể cần giải thích. Từng trường hợp do viên chức quyết định.', 'https://adoption.state.gov/content/travel/en/us-visas/study/student-visa.html
https://adoption.state.gov/content/travel/en/News/visas-news/interview-waiver-update-sept-18-2025.html
https://vn.usembassy.gov/frequently-asked-questions-nonimmigrant-visas/', '2026-10-04'),
  ('Chương trình trao đổi (visa J-1) khác du học F-1 thế nào, chuyển sang F-1 được không?', 'Lộ trình', 'verified', 'J-1 là diện trao đổi (Exchange Visitor) do đơn vị bảo trợ được Bộ Ngoại giao chỉ định cấp DS-2019, gồm nhiều nhóm như học sinh trung học, thực tập sinh...; F-1 là diện du học do trường cấp I-20. Chương trình J-1 học sinh trung học dành cho tuổi từ 15 đến 18 năm 6 tháng, kéo dài một đến hai học kỳ, ở với gia đình bản xứ hoặc trường nội trú, và người từng học ở Mỹ với F-1 hoặc J-1 không đủ điều kiện. Quy định liên bang không cấm tuyệt đối đổi từ J-1 sang F-1: chỉ người thuộc diện phải về nước 2 năm theo mục 212(e) mà chưa được miễn mới không được đổi diện (trừ sang A hoặc G); người còn lại có thể xin đổi diện qua USCIS hoặc xin visa F-1 mới ở nước ngoài, kết quả do USCIS/lãnh sự quyết định. Cần hỏi đơn vị bảo trợ J-1 và trường mới để biết trường hợp cụ thể.', 'https://j1visa.state.gov/basics/
https://www.ecfr.gov/api/versioner/v1/full/2026-08-11/title-22.xml?part=62&section=62.25
https://www.ecfr.gov/api/versioner/v1/full/2026-08-11/title-8.xml?part=248&section=248.2
https://fam.state.gov/fam/09FAM/09FAM030213.html', '2026-10-04'),
  ('Nên học ngành gì, ngành này ở Mỹ có cơ hội việc làm không?', 'Chọn ngành', 'verified', 'Cục Thống kê Lao động Mỹ (BLS) công bố dự báo việc làm theo nghề. Tính đến 10/2026, BLS dự báo việc làm của điều dưỡng đã đăng ký (registered nurses) tăng 6% giai đoạn 2025-2035 và nhóm lập trình viên/kiểm thử phần mềm tăng 10%, nhanh hơn mức trung bình. Đây là dự báo cho thị trường lao động Mỹ nói chung, không đảm bảo cơ hội việc làm hay visa làm việc cho sinh viên quốc tế. Việc nên học ngành nào là quyết định cá nhân; AI chỉ nên gợi ý nguồn tra cứu BLS.', 'https://www.bls.gov/ooh/healthcare/registered-nurses.htm
https://www.bls.gov/ooh/computer-and-information-technology/software-developers.htm', '2026-10-04'),
  ('Muốn du học Mỹ thì bắt đầu từ đâu, cần chuẩn bị gì (theo lớp đang học)?', 'Bắt đầu', 'verified', 'EducationUSA chia quá trình thành 5 bước: tìm hiểu lựa chọn, tìm nguồn tài chính, hoàn thiện hồ sơ, xin visa, chuẩn bị khởi hành, và khuyên bắt đầu sớm (ít nhất 12–18 tháng trước khi nhập học). Học sinh nên xác định nhu cầu về ngành, tài chính, địa điểm rồi chọn trường. Thời điểm cụ thể theo từng lớp là gợi ý, tùy từng em.', 'https://educationusa.state.gov/your-5-steps-us-study
https://educationusa.state.gov/your-5-steps-us-study/research-your-options/undergraduate', '2026-10-04'),
  ('Du học THPT Mỹ cần điều kiện gì (tiếng Anh, SSAT, chi phí, học bổng)?', 'Lộ trình', 'verified', 'Điều kiện THPT khác nhau theo trường. Ví dụ Phillips Academy Andover (nội trú tư thục) yêu cầu một trong SSAT/ISEE (Upper Level), PSAT, SAT hoặc ACT, và với học sinh học ở trường không dạy bằng tiếng Anh thì phải có TOEFL iBT, IELTS hoặc Duolingo (mức tham khảo của học sinh trúng tuyển: TOEFL 100, IELTS 7.5, Duolingo 135), có phỏng vấn. Choate Rosemary Hall không bắt buộc điểm chuẩn hóa nhưng đề nghị điểm tiếng Anh tối thiểu TOEFL 100 / IELTS 7 / Duolingo 130. Học phí nội trú 2026–27: Choate 73.530 USD (+1.000 USD phí công nghệ), Andover 79.800 USD; cả hai đều nêu hỗ trợ tài chính theo nhu cầu (Andover need-blind, 47% học sinh nhận hỗ trợ). Trường công chỉ nhận F-1 tối đa 12 tháng.', 'https://www.andover.edu/admission/apply
https://www.choate.edu/admission/frequently-asked-questions
https://www.choate.edu/admission/tuition-and-financial-aid
https://www.andover.edu/admission/tuition-financial-aid
https://www.admission.org/assessments/ssat/about-the-ssat', '2026-10-04'),
  ('Đang học ĐH ở Việt Nam hoặc nước khác, chuyển sang ĐH Mỹ được không, có chuyển tín chỉ không?', 'Lộ trình', 'verified', 'Sinh viên đang học đại học ở nước ngoài có thể chuyển sang trường Mỹ, nhưng có thể mất một số tín chỉ và cần thêm thời gian để hoàn thành bằng. Quy trình nộp hồ sơ: phải đáp ứng yêu cầu như sinh viên năm nhất cộng thêm hồ sơ bổ sung mà trường chuyển đến yêu cầu. Từng trường tự xét chuyển tín chỉ và có thể yêu cầu dịch vụ đánh giá bằng cấp, nên cần hỏi phòng tuyển sinh của trường.', 'https://educationusa.state.gov/experience-studying-usa/us-educational-system/frequently-asked-questions-faqs?id=1&iq=126&language=1', '2026-10-04'),
  ('Săn học bổng toàn phần có thực tế không, có cần chứng minh tài chính không?', 'Học bổng', 'verified', 'EducationUSA cho biết đa số học bổng chỉ trang trải một phần chi phí học tập và sinh hoạt, và sinh viên quốc tế cần cạnh tranh trong nhóm ứng viên rất đông. Về visa, viên chức phải thấy bằng chứng đủ tiền cho năm học đầu tiên và nguồn tiền đáng tin cho các năm sau; học bổng được tính là một nguồn tài chính. Vì vậy phần chi phí học bổng không chi trả vẫn phải chứng minh. Học bổng toàn phần hiếm hay không là tùy trường, không có số liệu chung chính thức.', 'https://educationusa.state.gov/your-5-steps-us-study/finance-your-studies/undergraduate
https://fam.state.gov/fam/09FAM/09FAM040205.html', '2026-10-04'),
  ('Chuyển tiền sang Mỹ và đóng học phí thế nào, có hạn mức không?', 'Tài chính', 'verified', 'Theo Thông tư 20/2022/TT-NHNN của Ngân hàng Nhà nước (hiệu lực từ 15/02/2023), công dân Việt Nam được mua, chuyển hoặc mang ngoại tệ ra nước ngoài cho mục đích học tập thông qua ngân hàng được phép, từ ngoại tệ tự có hoặc ngoại tệ mua của ngân hàng. Mức chuyển được căn cứ vào các chi phí ghi trong thông báo của phía nước ngoài (như học phí, sinh hoạt phí); nếu không có thông báo về sinh hoạt phí thì ngân hàng được phép quyết định mức chuyển thêm. Việc chuyển/mang tiền có thể do người học, người đại diện hợp pháp hoặc thân nhân thực hiện theo hướng dẫn của ngân hàng. Danh mục giấy tờ cụ thể (ví dụ I-20, giấy tờ quan hệ) do từng ngân hàng yêu cầu, thông tư không liệt kê chi tiết; cần hỏi ngân hàng. Thông tin tính đến 10/2026 theo văn bản gốc, nên kiểm tra văn bản sửa đổi nếu có.', 'https://congbao.chinhphu.vn/van-ban/thong-tu-so-20-2022-tt-nhnn-38444.htm
https://congbaocdn.chinhphu.vn/CongBaoCP/VanBan/2022/12/38444/42802-1-202313-1420-2022-tt-nhnn.pdf', '2026-10-04'),
  ('Đang học ở Mỹ có chuyển trường, đổi bang được không, sau bao lâu?', 'Đang học ở Mỹ', 'verified', 'Theo quy định đang có hiệu lực, sinh viên F-1 đang giữ đúng tình trạng có thể chuyển sang trường khác được SEVP chứng nhận bằng cách báo DSO trường hiện tại, DSO cập nhật SEVIS và trường mới cấp I-20; quy định này không bắt buộc phải học đủ một năm mới được chuyển, và đổi bang không phải điều kiện riêng. Sinh viên phải bắt đầu học ở trường mới trong vòng 5 tháng. Một quy tắc mới của DHS (công bố 17/7/2026) có điều khoản hạn chế chuyển trường/đổi ngành trong năm học đầu với bậc dưới sau đại học, nhưng toàn bộ quy tắc này đang bị tòa liên bang tạm hoãn hiệu lực từ 14/9/2026 (tính đến 10/2026). Luôn hỏi DSO hiện tại trước khi chuyển.', 'https://www.ecfr.gov/api/versioner/v1/full/2026-08-11/title-8.xml?part=214&section=214.2
https://www.ecfr.gov/api/versioner/v1/full/2026-10-01/title-8.xml?part=214&section=214.2
https://www.courtlistener.com/docket/74661796/presidents-alliance-on-higher-education-and-immigration-v-united-states/', '2026-10-04'),
  ('Quy định mới về thời hạn lưu trú (D/S) của du học sinh ảnh hưởng thế nào?', 'Đang học ở Mỹ', 'verified', 'DHS công bố quy tắc cuối cùng (không còn là đề xuất) ngày 17/7/2026 (91 FR 44976) thay ''thời hạn lưu trú theo chương trình'' (D/S) bằng thời hạn nhập cảnh cố định cho diện F, J và I, ban đầu có hiệu lực 15/9/2026; người học có thể phải xin gia hạn lưu trú (EOS) với USCIS nếu cần thêm thời gian. Ngày 14/9/2026, tòa án liên bang quận Massachusetts (vụ Presidents'' Alliance v. DHS, 1:26-cv-13799) ra lệnh hoãn hiệu lực quy tắc; chính phủ nộp kháng cáo ngày 30/9/2026 và tòa tổ chức phiên làm việc ngày 2/10/2026 (tính đến 04/10/2026). Vì tình hình có thể thay đổi nhanh, người học cần theo dõi thông báo của SEVP/Study in the States và hỏi DSO.', 'https://www.federalregister.gov/api/v1/documents/2026-14439.json
https://www.courtlistener.com/docket/74661796/presidents-alliance-on-higher-education-and-immigration-v-united-states/
https://www.ecfr.gov/api/versioner/v1/full/2026-10-01/title-8.xml?part=214&section=214.2', '2026-10-04'),
  ('Gặp vấn đề về I-20, SEVIS, số tín chỉ, lớp online thì làm gì để giữ tình trạng F-1?', 'Đang học ở Mỹ', 'verified', 'Để giữ tình trạng F-1, sinh viên phải học đủ chương trình toàn phần (ví dụ bậc đại học tối thiểu 12 tín chỉ/kỳ ở trường tính theo học kỳ, trừ khi cần ít hơn để hoàn thành chương trình). Giảm tải chỉ hợp lệ khi DSO cho phép trước và cập nhật SEVIS; tự ý học dưới mức đủ sẽ bị coi là mất tình trạng. Với lớp online, mỗi kỳ chỉ được tính tối đa tương đương một lớp hoặc ba tín chỉ vào chương trình toàn phần. Khi gặp vấn đề về I-20, SEVIS hoặc tín chỉ, nên liên hệ DSO sớm; nếu đã mất tình trạng, có thể xin phục hồi (reinstatement) với USCIS thường trong vòng 5 tháng, nhưng USCIS quyết định và không có kháng nghị.', 'https://www.ecfr.gov/api/versioner/v1/full/2026-08-11/title-8.xml?part=214&section=214.2', '2026-10-04'),
  ('Cần tiêm chủng, khám sức khỏe gì trước khi sang Mỹ?', 'Trước khi bay', 'verified', 'Chính phủ liên bang không yêu cầu tiêm chủng như điều kiện cấp visa F-1: các tiêu chí tiêm chủng của CDC dành cho đợt khám di trú của người xin visa định cư, còn người xin visa không định cư thường không bị yêu cầu. Yêu cầu tiêm chủng đối với sinh viên do từng trường và từng bang đặt ra (ví dụ nhiều trường yêu cầu nộp bằng chứng tiêm chủng như MMR trước hoặc ngay khi nhập học). Cách nộp và có cần dịch sang tiếng Anh hay không cũng do trường quy định; một trường ví dụ (University of Florida ELI) yêu cầu điền mẫu chính thức bằng tiếng Anh. Sinh viên nên xem trang yêu cầu tiêm chủng của chính trường mình và hỏi văn phòng y tế sinh viên.', 'https://www.cdc.gov/immigrant-refugee-health/hcp/panel-physicians/vaccination.html
https://eli.ufl.edu/information/visitors-information/immunization-and-insurance-requirements/', '2026-10-04'),
  ('Hành lý, đồ mang theo khi bay sang Mỹ cần lưu ý gì?', 'Trước khi bay', 'verified', 'Du khách vào Mỹ phải khai báo mọi sản phẩm nông nghiệp và động vật hoang dã với CBP; nếu khai báo đầy đủ thì không bị phạt, ngay cả khi vật phẩm bị từ chối nhập. Thịt, gia cầm và hải sản bị hạn chế nhập khẩu, nên tốt nhất không mang thực phẩm có thịt và nên giữ hóa đơn, bao bì gốc của các sản phẩm nông nghiệp. Trọng lượng hành lý xách tay (khoảng 7 kg) và kích thước do từng hãng bay quy định nên cần xem trang của hãng. Chưa tìm được nguồn chính thức về điện áp thiết bị nên chưa khẳng định.', 'https://www.aphis.usda.gov/traveling-with-ag-products/another-country', '2026-10-04'),
  ('Du học sinh gặp khó khăn tâm lý thì tìm hỗ trợ ở đâu?', 'Đang học ở Mỹ', 'verified', 'Nếu cảm thấy quá áp lực, sinh viên nên liên hệ trung tâm tư vấn/sức khỏe tâm thần của trường mình, thường miễn phí hoặc có phí thấp cho sinh viên, và có thể báo DSO nếu việc học bị ảnh hưởng. Ở Mỹ có Đường dây 988 Suicide & Crisis Lifeline: gọi hoặc nhắn tin 988, hoạt động 24/7/365, miễn phí và bảo mật; trường hợp nguy hiểm tức thời nên gọi 911. Nếu tình trạng sức khỏe ảnh hưởng đến việc học, DSO có thể cho phép giảm tải học vì lý do y tế (cần giấy xác nhận của bác sĩ/chuyên gia tâm lý có giấy phép, tối đa tổng cộng 12 tháng ở mỗi bậc học) và giữ nguyên tình trạng F-1. Nội dung này chỉ là hướng dẫn chung, không phải tư vấn y tế.', 'https://988lifeline.org/
https://www.ecfr.gov/api/versioner/v1/full/2026-08-11/title-8.xml?part=214&section=214.2', '2026-10-04'),
  ('Chưa có bằng THPT (hoặc đang thi GED) có du học Mỹ được không?', 'Điều kiện đầu vào', 'verified', 'GED là kỳ thi của GED Testing Service và có thể thi ở ngoài nước Mỹ, chỉ bằng tiếng Anh; người từ 18 tuổi thi không hạn chế, 16-17 tuổi cần đơn xin miễn tuổi. Người không phải công dân vẫn được thi nếu đáp ứng điều kiện, cần hộ chiếu khi thi ngoài nước công dân. Việc trường đại học/cao đẳng có chấp nhận GED thay bằng THPT và điều kiện nhận F-1 do từng trường quyết định (ví dụ NVCC yêu cầu chứng nhận tương đương THPT Mỹ), cần hỏi trường.', 'https://www.ged.com/en/policies/other.html
https://www.nvcc.edu/admissions/apply/international/index.html', '2026-10-04'),
  ('Đang sống ở nước khác (Nhật, Hàn, Canada…) thì nộp hồ sơ du học Mỹ có khác không?', 'Lộ trình', 'verified', 'Theo FAM, người xin visa thường nộp ở khu vực lãnh sự nơi mình cư trú, và lãnh sự quán phải nhận hồ sơ của người cư trú trong khu vực của mình; người chỉ đang có mặt (không cư trú) thì quyết định thuộc quyền của lãnh sự và dự kiến hiếm khi từ chối. Tiêu chí xét F-1 (I-20, tài chính, ý định về nước, chuẩn bị học) không đổi theo nơi nộp. Cần kiểm tra lịch phỏng vấn và yêu cầu của lãnh sự quán cụ thể nơi đang sống.', 'https://fam.state.gov/fam/09FAM/09FAM040302.html
https://fam.state.gov/fam/09FAM/09FAM040205.html', '2026-10-04'),
  ('Muốn sang Mỹ để đi làm, kiếm tiền thì du học có phải là cách?', 'Mục đích du học', 'verified', 'Visa F-1 cấp để học toàn thời gian, không phải để đi làm kiếm tiền. Sinh viên phải chứng minh có đủ tài chính theo số tiền trên I-20. Làm việc bị giới hạn: việc làm trong khuôn viên tối đa 20 giờ/tuần khi trường đang học; làm ngoài khuôn viên chỉ sau khi đã ở tình trạng F-1 đủ một năm học, có học lực tốt và được cho phép, tối đa 20 giờ/tuần khi đang học. Làm việc trái phép là vi phạm tình trạng và ảnh hưởng đến việc gia hạn. Không nên coi du học là cách chắc chắn để kiếm tiền; thu nhập khi đi làm không thay thế nguồn tài chính phải chứng minh khi xin visa.', 'https://www.ecfr.gov/current/title-8/part-214/section-214.2
https://adoption.state.gov/content/travel/en/us-visas/study/student-visa.html', '2026-10-04'),
  ('DS-160 là gì, điền thế nào và có sửa được sau khi nộp không?', 'Visa', 'verified', 'DS-160 là đơn xin visa không định cư trực tuyến. Bạn cần điền xong, nộp và in trang xác nhận có mã vạch để mang theo khi phỏng vấn; ảnh được tải lên khi điền đơn. Sau khi nộp không thể sửa, nếu sai phải điền DS-160 mới rồi cập nhật mã vạch mới vào lịch hẹn ít nhất 3 ngày làm việc trước ngày hẹn. Nếu chưa nộp, bản nháp có mã đơn được lưu 30 ngày. Mã vạch DS-160 phải khớp mã vạch trên giấy hẹn, nếu không bạn có thể không được vào phỏng vấn. Chữ ký điện tử trên đơn là cam kết bạn chịu trách nhiệm về nội dung dù có người khác điền hộ.', 'https://vn.usembassy.gov/frequently-asked-questions-nonimmigrant-visas/
https://vn.usembassy.gov/nonimmigrant-visas/
https://adoption.state.gov/content/travel/en/us-visas/study/student-visa.html', '2026-10-04'),
  ('Đặt lịch phỏng vấn visa F-1 ở Việt Nam thế nào, chọn Hà Nội hay TP.HCM, xem thời gian chờ ở đâu?', 'Visa', 'verified', 'Lần đầu xin visa bạn phải phỏng vấn tại ĐSQ Mỹ ở Hà Nội hoặc TLSQ Mỹ ở TP.HCM; khi đặt lịch bạn chọn một trong hai nơi, thời gian chờ có thể khác nhau. ĐSQ chỉ tiếp người có lịch hẹn; lịch hẹn chỉ dùng cho chính người đặt, không chuyển nhượng. Phí visa không hoàn lại và có thể đặt lịch trong vòng một năm sau khi đóng phí. Thời gian chờ thay đổi theo địa điểm, mùa và loại visa; xem bảng thời gian chờ chính thức của Bộ Ngoại giao Mỹ (tính đến 10/2026 cần xem số liệu hiện hành). Nên nộp sớm vì thời gian chờ chỉ là ước tính.', 'https://vn.usembassy.gov/nonimmigrant-visas/
https://vn.usembassy.gov/frequently-asked-questions-nonimmigrant-visas/
https://vn.usembassy.gov/visas/
https://adoption.state.gov/content/travel/en/us-visas/visa-information-resources/wait-times.html', '2026-10-04'),
  ('Có xin được lịch phỏng vấn gấp (expedite) khi sắp nhập học không?', 'Visa', 'verified', 'Nếu không còn lịch trước ngày cần bay, bạn có thể yêu cầu lịch gấp tại ĐSQ. Trước khi yêu cầu cần điền DS-160, đóng phí và đặt lịch sớm nhất có sẵn trong hệ thống, đồng thời phải có giấy tờ chứng minh nhu cầu. Bộ Ngoại giao nêu ngày bắt đầu học là một trong các tình huống khẩn có thể được xem xét. Việc chấp thuận do ĐSQ quyết định, không bảo đảm.', 'https://adoption.state.gov/content/travel/en/us-visas/visa-information-resources/wait-times.html
https://vn.usembassy.gov/frequently-asked-questions-nonimmigrant-visas/', '2026-10-04'),
  ('Gia hạn visa F-1 có được miễn phỏng vấn không?', 'Visa', 'verified', 'Theo cập nhật của Bộ Ngoại giao Mỹ có hiệu lực từ 01/10/2025, hầu hết người xin visa không định cư đều phải phỏng vấn trực tiếp. Danh mục được miễn chỉ gồm một số loại ngoại giao/chính thức, B-1/B-2 gia hạn trong 12 tháng, và H-2A trong 12 tháng, không có F-1. Viên chức vẫn có thể yêu cầu phỏng vấn trong mọi trường hợp. Trang riêng về miễn phỏng vấn trên website ĐSQ Việt Nam còn ghi thông tin cũ (đến hết 2023), nên cần dựa vào thông báo mới của Bộ Ngoại giao (tính đến 10/2026).', 'https://adoption.state.gov/content/travel/en/News/visas-news/interview-waiver-update-sept-18-2025.html
https://vn.usembassy.gov/nonimmigrant-visas/', '2026-10-04'),
  ('221(g) là gì, bị xử lý hành chính (administrative processing) thì phải làm gì?', 'Visa', 'verified', 'Từ chối theo mục 221(g) nghĩa là viên chức chưa có đủ thông tin để kết luận bạn đủ điều kiện, do hồ sơ thiếu giấy tờ hoặc cần xử lý hành chính thêm. Bạn sẽ nhận thư nêu rõ cần bổ sung gì. Nếu được yêu cầu bổ sung, hãy nộp sớm; có một năm kể từ ngày bị từ chối để nộp, nếu quá hạn phải xin lại và đóng phí mới. Với xử lý hành chính, thời gian tùy từng trường hợp; nên chờ ít nhất 180 ngày kể từ phỏng vấn hoặc kể từ khi nộp giấy tờ bổ sung mới hỏi thăm tình trạng (trừ trường hợp khẩn cấp). Nộp bổ sung đúng hạn thì thường không cần nộp đơn mới.', 'https://adoption.state.gov/content/travel/en/us-visas/visa-information-resources/visa-denials.html
https://adoption.state.gov/content/travel/en/us-visas/visa-information-resources/administrative-processing-information.html
https://vn.usembassy.gov/nonimmigrant-visas/', '2026-10-04'),
  ('Học sinh dưới 17 tuổi đi phỏng vấn visa cần ai đi cùng và mang gì?', 'Visa', 'verified', 'Người nộp đơn dưới 17 tuổi phải có cha/mẹ hoặc người giám hộ hợp pháp đi cùng. Cha/mẹ mang giấy khai sinh của trẻ và CCCD hoặc hộ chiếu của mình; người giám hộ mang giấy tờ giám hộ do cơ quan nhà nước cấp và CCCD/hộ chiếu. Người từ 70 tuổi trở lên hoặc cần hỗ trợ đặc biệt, hoặc người không nói tiếng Anh/Việt (kèm phiên dịch) cũng có thể có thêm một người đi cùng. Những người thứ ba khác không được vào phòng phỏng vấn; nếu có người liên quan, họ có thể viết thư gửi kèm.', 'https://vn.usembassy.gov/frequently-asked-questions-nonimmigrant-visas/
https://vn.usembassy.gov/nonimmigrant-visas/', '2026-10-04'),
  ('Đóng phí SEVIS I-901 ở đâu, như thế nào và khi nào?', 'Visa', 'verified', 'Phí SEVIS I-901 nộp trực tiếp cho Bộ An ninh Nội địa Mỹ tại trang chính thức fmjfee.com; bạn cần Form I-20 mới nhất để điền, và nên kiểm tra họ tên, ngày sinh, mã trường trên I-20 trước khi đóng (nếu sai thì liên hệ DSO để sửa). Phải đóng trước khi visa được cấp (nên đóng trước khi phỏng vấn); mức phí F-1 là 350 USD tính đến 10/2026. Có thể đóng online hoặc gửi séc/money order theo mẫu I-901, và trường hoặc người khác có thể đóng hộ. Sau khi đóng, in xác nhận thanh toán từ trang Check I-901 Status để mang theo khi phỏng vấn. Người phụ thuộc F-2 không phải đóng phí riêng.', 'https://www.fmjfee.com/i901fee/help.html
https://www.fmjfee.com/i901fee/home.html
https://www.ecfr.gov/current/title-8/part-214/section-214.13', '2026-10-04'),
  ('Điều 214(b) bị từ chối nghĩa là gì?', 'Visa', 'verified', '214(b) là điều luật theo đó người xin visa không định cư bị coi là có ý định định cư cho đến khi chứng minh được ngược lại. Bị từ chối theo 214(b) nghĩa là bạn chưa chứng minh đủ điều kiện loại visa đã xin và/hoặc chưa chứng minh được ràng buộc mạnh với Việt Nam sẽ khiến bạn về nước sau thời gian học. Ràng buộc có thể là việc làm, nhà cửa, quan hệ gia đình, bạn bè; với người trẻ, viên chức có thể xét học lực, việc làm của cha mẹ và kế hoạch dài hạn. Kết quả áp dụng cho lần nộp đó, không có kháng cáo, nhưng bạn có thể nộp lại khi có thông tin mới hoặc hoàn cảnh thay đổi đáng kể.', 'https://adoption.state.gov/content/travel/en/us-visas/visa-information-resources/visa-denials.html
https://vn.usembassy.gov/frequently-asked-questions-nonimmigrant-visas/', '2026-10-04'),
  ('Tài chính chứng minh có phải khớp với I-20 không, và cần gì?', 'Visa', 'verified', 'Quy định yêu cầu sinh viên F-1 có bằng chứng tài chính về khoản hỗ trợ đúng số tiền ghi trên I-20. Viên chức có thể hỏi bạn sẽ trả học phí, sinh hoạt và đi lại thế nào, và có thể yêu cầu xem giấy tờ. ĐSQ Mỹ tại Việt Nam nói giấy tờ tài chính không bắt buộc và nhiều viên chức không xem kỹ, nhưng bạn phải giải thích rõ ai chi trả và nguồn tiền. Không mua hay nộp giấy tờ giả: khai gian có thể bị cấm nhập cảnh Mỹ vĩnh viễn. Học bổng, thư tài trợ hay hồ sơ người bảo trợ nên khớp với thông tin trên I-20 và DS-160.', 'https://www.ecfr.gov/current/title-8/part-214/section-214.2
https://adoption.state.gov/content/travel/en/us-visas/study/student-visa.html
https://vn.usembassy.gov/frequently-asked-questions-nonimmigrant-visas/', '2026-10-04'),
  ('Có phải để mạng xã hội ở chế độ công khai khi xin visa F-1 không?', 'Visa', 'verified', 'Có. ĐSQ Mỹ tại Việt Nam hướng dẫn mọi người xin visa diện F (cùng M, J và một số loại khác) chỉnh quyền riêng tư của tất cả tài khoản mạng xã hội sang ''công khai'' (public/open) để phục vụ việc thẩm tra danh tính và điều kiện nhập cảnh. Bộ Ngoại giao Mỹ cũng xác nhận việc rà soát hiện diện trực tuyến áp dụng cho sinh viên F-1, M-1, F-2, M-2. Hệ thống không cam kết kết quả, quyết định cấp visa do viên chức lãnh sự.', 'https://vn.usembassy.gov/visas/
https://adoption.state.gov/content/travel/en/News/visas-news/announcement-of-expanded-screening-and-vetting-for-visa-applicants.html', '2026-10-04'),
  ('Quy định mới về thời hạn lưu trú của sinh viên F-1 (bỏ ''duration of status'') là gì?', 'Visa', 'verified', 'Ngày 17/07/2026, Bộ An ninh Nội địa Mỹ công bố quy định cuối cùng chuyển người diện F, J và I từ ''duration of status'' (ở theo thời gian học) sang được nhập cảnh với thời hạn cố định, dự kiến có hiệu lực từ 15/09/2026; tuy nhiên ngày 14/09/2026 tòa án liên bang (D. Mass.) đã ra lệnh tạm hoãn hiệu lực và chính phủ đang kháng cáo, nên hiện vẫn áp dụng quy định cũ (duration of status) tính đến 10/2026. Theo bản quy định, thời hạn ở được tính theo độ dài chương trình, tối đa 4 năm và có thêm 30 ngày ân hạn; muốn ở lâu hơn thì xin gia hạn lưu trú với USCIS hoặc nhập cảnh lại. Người đã nhập cảnh theo duration of status trước thời điểm có hiệu lực được chuyển tiếp tối đa 4 năm. Chi tiết áp dụng cho từng bậc học cần hỏi DSO của trường; tính đến 10/2026 cần xem lại thông báo mới của DHS.', 'https://www.federalregister.gov/documents/2026/07/17/2026-14439/establishing-a-fixed-time-period-of-admission-and-an-extension-of-stay-procedure-for-nonimmigrant
https://www.govinfo.gov/content/pkg/FR-2026-07-17/pdf/2026-14439.pdf', '2026-10-04'),
  ('Visa F-1 cấp trước ngày học bao lâu và được nhập cảnh Mỹ sớm nhất khi nào?', 'Visa', 'verified', 'Visa F-1 cho sinh viên mới có thể được cấp tối đa 365 ngày trước ngày bắt đầu khóa học. Tuy nhiên bạn chỉ được nhập cảnh Mỹ bằng visa sinh viên tối đa 30 ngày trước ngày bắt đầu chương trình; muốn đến sớm hơn phải có loại visa khác (ví dụ visa du lịch). Visa không bảo đảm nhập cảnh: viên chức CBP tại cửa khẩu quyết định cuối cùng. Không nên mua vé máy bay trước khi có visa.', 'https://adoption.state.gov/content/travel/en/us-visas/study/student-visa.html', '2026-10-04'),
  ('Có nên thuê dịch vụ hoặc mua giấy tờ để được visa không?', 'Visa', 'verified', 'Không. ĐSQ Mỹ tại Việt Nam khuyên không trả tiền cho bất kỳ ai tự nhận giúp bạn có visa, và không mua giấy tờ giả vì viên chức được đào tạo để phát hiện giấy tờ giả. Theo luật Mỹ, cung cấp thông tin sai để xin visa có thể bị cấm nhập cảnh vĩnh viễn. Chữ ký điện tử trên đơn là cam kết bạn chịu trách nhiệm pháp lý về nội dung kể cả khi người khác điền hộ. Nếu cần tư vấn hồ sơ, cần phân biệt tư vấn hợp pháp với việc làm giả giấy tờ.', 'https://vn.usembassy.gov/frequently-asked-questions-nonimmigrant-visas/
https://vn.usembassy.gov/nonimmigrant-visas/', '2026-10-04'),
  ('Thời gian ân hạn 60 ngày sau khi học xong là gì?', 'Duy trì tình trạng', 'verified', 'Theo quy định đang có hiệu lực (tính đến 10/2026), sinh viên F-1 hoàn thành chương trình và thực tập (OPT) có thêm 60 ngày để chuẩn bị rời Mỹ hoặc chuyển trường. Nếu được DSO cho phép nghỉ học (withdraw) thì chỉ có 15 ngày. Sinh viên không giữ đủ chương trình toàn phần mà không được DSO duyệt, hoặc mất tình trạng, không được hưởng thời gian này. Quy tắc D/S mới của DHS dự kiến rút xuống 30 ngày nhưng đang bị tòa tạm hoãn; hỏi DSO để biết thời hạn áp dụng cho trường hợp của mình.', 'https://www.ecfr.gov/api/versioner/v1/full/2026-08-11/title-8.xml?part=214&section=214.2
https://www.ecfr.gov/api/versioner/v1/full/2026-10-01/title-8.xml?part=214&section=214.2
https://www.courtlistener.com/docket/74661796/presidents-alliance-on-higher-education-and-immigration-v-united-states/', '2026-10-04'),
  ('Cần chữ ký đi lại (travel signature) trên I-20 khi ra khỏi Mỹ và quay lại không?', 'Đi lại', 'verified', 'Sinh viên F-1 vắng mặt tạm thời từ 5 tháng trở xuống có thể được nhập cảnh lại để học tại trường được SEVP chứng nhận nếu xuất trình I-20 hiện hành do DSO xác nhận (ký) cho tái nhập cảnh, hoặc I-20 mới nếu có thay đổi đáng kể (đổi ngành, chuyển trường, lên bậc cao hơn). Thời hạn hiệu lực của chữ ký và việc cần I-20 mới do DSO hướng dẫn. Đi quá 5 tháng có thể ảnh hưởng tình trạng, nên hỏi DSO trước khi đi. Sinh viên đang OPT cần thêm chữ ký DSO trong vòng 6 tháng cùng EAD còn hạn.', 'https://www.ecfr.gov/api/versioner/v1/full/2026-08-11/title-8.xml?part=214&section=214.2', '2026-10-04'),
  ('Nếu đã mất tình trạng F-1 thì có phục hồi (reinstatement) được không?', 'Duy trì tình trạng', 'verified', 'USCIS có thể xem xét phục hồi tình trạng nếu sinh viên nộp Form I-539 kèm I-20 có khuyến nghị của DSO, và thường phải nộp trong vòng 5 tháng kể từ khi mất tình trạng (trừ hoàn cảnh đặc biệt). Các điều kiện khác gồm không làm việc trái phép, không có vi phạm lặp lại hoặc cố ý, và đang hoặc sắp theo học đủ chương trình toàn phần. Vi phạm phải do hoàn cảnh ngoài kiểm soát của sinh viên, hoặc liên quan đến giảm tải mà DSO có quyền duyệt. USCIS quyết định và không có kháng nghị; sinh viên có thể thay vào đó rời Mỹ và nhập cảnh lại với tình trạng mới. Nên hỏi DSO sớm.', 'https://www.ecfr.gov/api/versioner/v1/full/2026-08-11/title-8.xml?part=214&section=214.2', '2026-10-04'),
  ('Được giảm tải (reduced course load) khi nào và cần làm gì?', 'Duy trì tình trạng', 'verified', 'DSO có thể cho giảm tải do khó khăn học tập ban đầu (ngôn ngữ, phương pháp, xếp sai trình độ), do bệnh/vấn đề sức khỏe có giấy xác nhận chuyên môn, hoặc ở kỳ cuối nếu cần ít môn hơn để tốt nghiệp. Mức giảm tải thường ít nhất 6 tín chỉ (hoặc một nửa số giờ đủ chương trình). Phải có DSO cho phép và cập nhật SEVIS trước khi giảm; tự giảm không xin phép sẽ bị coi là mất tình trạng. Lý do học tập chỉ được duyệt một lần ở mỗi bậc học, lý do y tế tối đa tổng cộng 12 tháng ở mỗi bậc học.', 'https://www.ecfr.gov/api/versioner/v1/full/2026-08-11/title-8.xml?part=214&section=214.2', '2026-10-04'),
  ('Thế nào là học đủ chương trình toàn phần (full course of study) và lớp online được tính bao nhiêu?', 'Duy trì tình trạng', 'verified', 'Bậc đại học thường phải học ít nhất 12 tín chỉ mỗi kỳ ở trường tính theo học kỳ/quý (trừ khi cần ít hơn để hoàn thành chương trình); bậc sau đại học do DSO xác nhận là chương trình toàn phần. Với lớp online hoặc học từ xa, mỗi kỳ chỉ được tính tối đa tương đương một lớp hoặc ba tín chỉ vào mức toàn phần, và chương trình ngôn ngữ thì không tính lớp online. Quy định này có thể được điều chỉnh bằng thông báo chính thức, nên hỏi DSO về chính sách hiện hành của trường (tính đến 10/2026).', 'https://www.ecfr.gov/api/versioner/v1/full/2026-08-11/title-8.xml?part=214&section=214.2', '2026-10-04'),
  ('Sinh viên F-1 làm thêm trong trường được tối đa bao nhiêu giờ?', 'Làm việc', 'verified', 'Việc làm trong khuôn viên (hoặc cơ sở liên kết giáo dục với trường) không được quá 20 giờ/tuần khi trường đang học; sinh viên được làm toàn thời gian khi trường không học hoặc trong kỳ nghỉ hè. Khi mới nhập cảnh để bắt đầu chương trình, sinh viên không được bắt đầu làm việc sớm hơn 30 ngày trước ngày bắt đầu học. Sau khi hoàn thành chương trình, không được làm việc trong trường trừ thực tập được cấp phép (CPT/OPT). Việc làm ngoài trường cần được cấp phép riêng; hỏi DSO trước khi nhận việc.', 'https://www.ecfr.gov/api/versioner/v1/full/2026-08-11/title-8.xml?part=214&section=214.2', '2026-10-04'),
  ('Điều kiện được làm CPT (thực tập gắn với chương trình học) là gì?', 'Làm việc', 'verified', 'CPT là thực tập, hợp tác học-làm hoặc practicum là một phần của chương trình học, do DSO ủy quyền và cập nhật trong SEVIS trước khi bắt đầu làm. Sinh viên thường phải học đủ một năm học đầy đủ ở chế độ toàn phần mới đủ điều kiện, trừ một số chương trình sau đại học bắt buộc thực tập ngay. Làm CPT toàn thời gian từ một năm trở lên làm mất quyền OPT sau tốt nghiệp. Việc có đủ điều kiện hay không do trường và DSO quyết định.', 'https://www.ecfr.gov/api/versioner/v1/full/2026-08-11/title-8.xml?part=214&section=214.2', '2026-10-04'),
  ('Nộp đơn xin OPT khi nào (mốc thời gian)?', 'Làm việc', 'verified', 'Sinh viên phải xin DSO khuyến nghị OPT trong SEVIS rồi nộp Form I-765 cho USCIS. Với OPT sau khi hoàn thành chương trình, có thể nộp sớm nhất 90 ngày trước ngày kết thúc chương trình và chậm nhất 60 ngày sau ngày đó, đồng thời phải nộp trong vòng 30 ngày kể từ khi DSO nhập khuyến nghị vào SEVIS. Ngày bắt đầu OPT không được xin muộn hơn 60 ngày sau ngày kết thúc chương trình, và chỉ được làm việc từ ngày ghi trên EAD. Thời gian xử lý của USCIS thay đổi, tính đến 10/2026 nên theo dõi trang USCIS.', 'https://www.ecfr.gov/api/versioner/v1/full/2026-08-11/title-8.xml?part=214&section=214.2', '2026-10-04'),
  ('Điều kiện gia hạn STEM OPT 24 tháng là gì?', 'Làm việc', 'verified', 'Bằng làm căn cứ phải thuộc ngành trong danh sách STEM Designated Degree Program List của DHS, từ trường được công nhận (accredited) và được SEVP chứng nhận. Nhà tuyển dụng phải tham gia E-Verify, có mã EIN và cùng sinh viên hoàn thành kế hoạch đào tạo Form I-983 nộp cho DSO; công việc phải liên quan trực tiếp đến bằng STEM và ít nhất 20 giờ/tuần. Hồ sơ I-765 nộp tối đa 90 ngày trước khi OPT hết hạn và trong vòng 60 ngày kể từ khi DSO khuyến nghị. Tối đa hai lần gia hạn STEM trong đời, lần sau phải dựa trên bằng ở bậc cao hơn.', 'https://www.ecfr.gov/api/versioner/v1/full/2026-08-11/title-8.xml?part=214&section=214.2', '2026-10-04'),
  ('Thời gian thất nghiệp tối đa khi đang OPT là bao lâu?', 'Làm việc', 'verified', 'Khi đang OPT sau tốt nghiệp, tình trạng F-1 phụ thuộc vào việc làm: tổng số ngày thất nghiệp không được quá 90 ngày trong thời gian OPT thường; nếu có gia hạn STEM 24 tháng, tổng không quá 150 ngày trong toàn bộ thời gian OPT. Sinh viên đang OPT phải báo DSO khi đổi tên, địa chỉ hoặc gián đoạn việc làm, và người có STEM OPT phải báo trong vòng 10 ngày và nộp báo cáo xác nhận mỗi 6 tháng. Hỏi DSO để biết cách tính ngày thất nghiệp.', 'https://www.ecfr.gov/api/versioner/v1/full/2026-08-11/title-8.xml?part=214&section=214.2', '2026-10-04'),
  ('Quy trình chuyển hồ sơ SEVIS khi chuyển trường F-1 diễn ra thế nào?', 'Chuyển trường', 'verified', 'Sinh viên báo cho DSO trường hiện tại biết trường định chuyển đến; DSO cập nhật SEVIS với trường mới và ngày chuyển hồ sơ (release date). Từ ngày đó, trường mới truy cập hồ sơ SEVIS và cấp I-20 mới; sinh viên phải liên hệ DSO trường mới trong vòng 15 ngày kể từ ngày bắt đầu chương trình ghi trên I-20, và việc chuyển hoàn tất khi trường mới xác nhận sinh viên đã nhập học. Sinh viên phải bắt đầu học ở trường mới trong vòng 5 tháng. Sinh viên không học đủ chương trình toàn phần ở trường cũ không chuyển được và phải xin phục hồi hoặc nhập cảnh mới.', 'https://www.ecfr.gov/api/versioner/v1/full/2026-08-11/title-8.xml?part=214&section=214.2', '2026-10-04'),
  ('Khi đổi địa chỉ hoặc tên ở Mỹ cần báo ai và trong bao lâu?', 'Duy trì tình trạng', 'verified', 'Sinh viên F-1 phải báo cho DSO mọi thay đổi tên hợp pháp hoặc địa chỉ trong vòng 10 ngày; báo cho DSO được xem là đã báo DHS. DSO nhập vào SEVIS trong vòng 21 ngày kể từ khi nhận thông báo. Địa chỉ phải là nơi cư trú thực tế, không chỉ là địa chỉ nhận thư. Hỏi DSO cách báo (cổng thông tin hoặc biểu mẫu) của trường.', 'https://www.ecfr.gov/api/versioner/v1/full/2026-08-11/title-8.xml?part=214&section=214.2', '2026-10-04'),
  ('Danh sách ngành STEM của DHS (STEM Designated Degree Program List) nằm ở đâu và dùng thế nào?', 'Làm việc', 'verified', 'Quy định nêu rằng DHS duy trì danh sách đầy đủ các ngành đủ điều kiện STEM OPT (dựa trên phân loại CIP của Bộ Giáo dục) và đăng trên trang web của SEVP (Study in the States). Ngành học trên I-20 phải nằm trong danh sách này tại thời điểm DSO khuyến nghị gia hạn. Danh sách có thể được cập nhật; tính đến 10/2026 nên đối chiếu mã CIP trên I-20 với danh sách mới nhất do DSO cung cấp. Trang SEVP bị chặn khi kiểm tra nên chưa đọc được danh sách.', 'https://www.ecfr.gov/api/versioner/v1/full/2026-08-11/title-8.xml?part=214&section=214.2', '2026-10-04'),
  ('Common App là gì và có phải trường nào cũng dùng?', 'Hồ sơ', 'verified', 'Common App là hệ thống nộp hồ sơ chung cho nhiều trường đại học Mỹ, học sinh điền một bộ hồ sơ và gửi cho nhiều trường. Mỗi trường tự quy định bắt buộc hay không đối với bài luận, thư giới thiệu và điểm thi. Không phải mọi trường đều dùng Common App nên cần xem trang tuyển sinh của từng trường.', 'https://www.commonapp.org/apply/first-year-students', '2026-10-04'),
  ('Có cần nộp SAT/ACT khi học sinh Việt Nam nộp hồ sơ đại học không?', 'Hồ sơ', 'verified', 'Một số trường Mỹ áp dụng test-optional nên không yêu cầu SAT/ACT, nhưng nhiều trường vẫn yêu cầu. Học sinh có thể nộp điểm tự nguyện nếu muốn. Chính sách thay đổi theo trường và theo năm, cần kiểm tra trên trang tuyển sinh của trường (tính đến 10/2026).', 'https://educationusa.state.gov/your-5-steps-us-study/research-your-options/undergraduate/prepare-us-standardized-tests
https://www.commonapp.org/apply/first-year-students', '2026-10-04'),
  ('Gửi điểm TOEFL cho trường như thế nào, hiệu lực bao lâu?', 'Tiếng Anh', 'verified', 'Phí thi TOEFL iBT gồm tối đa 4 báo cáo điểm chính thức miễn phí gửi tới trường bạn chọn trước ngày thi. Gửi thêm báo cáo tốn US$25 mỗi trường. Điểm có hiệu lực 2 năm kể từ ngày thi (tính đến 10/2026, theo ETS).', 'https://www.ets.org/toefl/test-takers/ibt/scores/send-scores.html', '2026-10-04'),
  ('Gửi kết quả IELTS cho trường như thế nào?', 'Tiếng Anh', 'verified', 'Theo IELTS, kết quả có thể gửi bằng đường bưu điện cho tối đa 5 tổ chức miễn phí, hoặc gửi điện tử (IELTS Results Service) cho số tổ chức không giới hạn mà không mất phí. Gửi thông qua cổng đặt thi hoặc trung tâm tổ chức thi. Mỗi trường có thể có quy định riêng về hạn hiệu lực của điểm nên cần xem lại trên trang của trường.', 'https://ielts.org/take-a-test/your-results/getting-and-sharing-your-results', '2026-10-04'),
  ('Cao đẳng cộng đồng (community college) và lộ trình 2+2 là gì?', 'Cao đẳng cộng đồng', 'verified', 'Học 2 năm tại community college rồi chuyển lên đại học 4 năm để lấy bằng cử nhân (2+2). Community college thường có chi phí thấp hơn và quy trình nhập học linh hoạt hơn, nhiều trường xét hồ sơ rolling. Việc chuyển tín chỉ phụ thuộc thỏa thuận giữa hai trường, nên cần hỏi trường về chương trình transfer; không có gì bảo đảm được chuyển.', 'https://educationusa.state.gov/your-5-steps-us-study/research-your-options/community-college
https://educationusa.state.gov/your-5-steps-us-study/complete-your-application/community-college', '2026-10-04'),
  ('Học bạ Việt Nam có cần dịch và đánh giá bằng cấp không?', 'Hồ sơ', 'verified', 'Trường thường yêu cầu học bạ/bằng THPT có chứng thực gửi trực tiếp từ trường của học sinh, kèm bản dịch sang tiếng Anh. Một số trường có thể yêu cầu liên hệ tổ chức đánh giá bằng cấp (credential evaluation), và cách quy đổi GPA do trường quyết định. Học sinh nên xem yêu cầu trên trang tuyển sinh quốc tế của từng trường.', 'https://educationusa.state.gov/your-5-steps-us-study/complete-your-application/undergraduate
https://educationusa.state.gov/experience-studying-usa/us-educational-system/frequently-asked-questions-faqs', '2026-10-04'),
  ('Bằng chứng tài chính cho I-20 F-1 theo quy định là gì?', 'Visa', 'verified', 'Quy định F-1 yêu cầu sinh viên có bằng chứng tài chính cho khoản tiền ghi trên Form I-20. Số tiền cụ thể do trường tính và ghi trên I-20, và loại giấy tờ chấp nhận được hỏi DSO của trường. Quyết định cuối cùng về visa thuộc về viên chức lãnh sự.', 'https://www.ecfr.gov/api/versioner/v1/full/2026-09-01/title-8.xml?part=214&section=214.2', '2026-10-04'),
  ('Học bổng merit và need-based cho sinh viên quốc tế khác nhau thế nào?', 'Học bổng', 'verified', 'Học bổng merit dựa trên thành tích học tập; hỗ trợ need-based dựa trên chênh lệch giữa chi phí học và khả năng chi trả của gia đình. Chính sách do từng trường quy định. EducationUSA lưu ý đa số học bổng chỉ trang trải một phần chi phí và có thể không dành cho sinh viên năm nhất quốc tế. Nên xem trang học bổng của từng trường.', 'https://educationusa.state.gov/your-5-steps-us-study/finance-your-studies/undergraduate', '2026-10-04'),
  ('Need-blind và need-aware nghĩa là gì với sinh viên quốc tế?', 'Học bổng', 'verified', 'Need-blind nghĩa là khả năng chi trả không bị xét khi quyết định nhận; need-aware là có xét. Chính sách do từng trường quyết định. Ví dụ (.edu, chỉ minh họa, cần kiểm tra lại tính đến 10/2026): Princeton cho biết xét tuyển need-blind và đáp ứng toàn bộ nhu cầu của sinh viên quốc tế; Penn là need-aware với ứng viên quốc tế và yêu cầu nộp đơn xin hỗ trợ cùng lúc nộp hồ sơ, không xét lại sau khi nhận.', 'https://admission.princeton.edu/apply/international-students
https://admissions.upenn.edu/affording-penn/international-aid', '2026-10-04'),
  ('CSS Profile là gì và sinh viên quốc tế có cần nộp không?', 'Học bổng', 'verified', 'CSS Profile là hệ thống đơn xin hỗ trợ tài chính của College Board mà nhiều trường dùng để xét hỗ trợ từ quỹ của chính trường. Sinh viên quốc tế khai thu nhập, tài sản, chi phí gia đình bằng đồng tiền nước mình, hệ thống tự quy đổi. Chỉ một số trường dùng CSS Profile (tra danh sách trường tham gia), nên cần xem yêu cầu của từng trường.', 'https://cssprofile.collegeboard.org/international-students
https://highered.collegeboard.org/financial-aid/management/css-profile', '2026-10-04'),
  ('Sau đại học có những nguồn tài trợ nào và nên chuẩn bị khi nào?', 'Học bổng', 'verified', 'Theo EducationUSA, các trường có thể cấp fellowship hoặc trợ giảng/trợ nghiên cứu/hành chính (assistantship), thường miễn học phí và/hoặc có lương. Hạn nộp học bổng có thể sớm tới 18 tháng trước ngày bắt đầu chương trình. Chi tiết tùy từng khoa và trường.', 'https://educationusa.state.gov/your-5-steps-us-study/finance-your-studies/graduate', '2026-10-04'),
  ('Chương trình Fulbright dành cho sinh viên nước ngoài hoạt động thế nào?', 'Học bổng', 'verified', 'Fulbright Foreign Student Program cho phép sinh viên sau đại học, chuyên gia trẻ và nghệ sĩ từ nước ngoài học tập và nghiên cứu tại Mỹ, do Bộ Ngoại giao Mỹ tài trợ và IIE quản lý. Quy trình nộp và tuyển chọn do ủy ban Fulbright song phương hoặc Đại sứ quán Mỹ của từng nước thực hiện, nên điều kiện và hạn nộp khác nhau theo nước. Ứng viên Việt Nam nên xem thông tin do Đại sứ quán Mỹ/Fulbright công bố (trang vn.usembassy.gov không tải được khi kiểm chứng).', 'https://foreign.fulbrightonline.org/about/foreign-student-program', '2026-10-04'),
  ('Có trung tâm tư vấn chính thức EducationUSA ở Việt Nam không?', 'Tư vấn', 'verified', 'Có. EducationUSA có trung tâm tại TP.HCM (Diamond Plaza, 34 Lê Duẩn, Quận 1) và Hà Nội, cung cấp thông tin miễn phí, chính xác, không thiên vị cho học sinh, phụ huynh và các trường. Dịch vụ gồm tư vấn một-một, tư vấn không hẹn trước, buổi thuyết trình nhóm. Giờ làm việc có thể thay đổi, nên kiểm tra trên trang chính thức.', 'https://educationusa.state.gov/centers/educationusa-advising-center-ho-chi-minh-city
https://educationusa.state.gov/centers/pas-hanoi', '2026-10-04'),
  ('Thỏa thuận chuyển tiếp 2+2 giữa cao đẳng cộng đồng và đại học là gì?', 'Lộ trình', 'verified', 'Nhiều cao đẳng cộng đồng và đại học 4 năm có thỏa thuận chuyển tín chỉ và bằng cấp; một số có thỏa thuận đảm bảo nhận (guaranteed admission) khi hoàn thành chương trình chuyển tiếp. Ví dụ (.edu, chỉ minh họa): Virginia Peninsula Community College có thỏa thuận với hơn 30 trường ở Virginia. Điều kiện cụ thể (GPA, môn học) tùy từng thỏa thuận; nên xác nhận với phòng tuyển sinh trường 4 năm.', 'https://educationusa.state.gov/your-5-steps-us-study/research-your-options/community-college
https://www.vpcc.edu/academics/transfer/guaranteed-admission-agreements/', '2026-10-04'),
  ('Visa F-1 có học được trường THPT công lập ở Mỹ không, có giới hạn gì?', 'Trường THPT / Loại visa', 'verified', 'Có, nhưng bị hạn chế. Luật Mỹ cho phép F-1 học trường THPT công lập (lớp 9–12) với tổng thời gian không quá 12 tháng, và học sinh phải hoàn trả cho học khu toàn bộ chi phí bình quân đầu học sinh (full, unsubsidized per capita cost) cho thời gian học. Lãnh sự không cấp visa nếu I-20 ghi thời gian học vượt 12 tháng. Vì vậy du học THPT dài hạn (2–4 năm) thường phải chọn trường tư thục có chứng nhận SEVP. Chi phí cụ thể do từng học khu quy định.', 'https://www.govinfo.gov/content/pkg/USCODE-2023-title8/html/USCODE-2023-title8-chap12-subchapII-partII-sec1184.htm
https://fam.state.gov/fam/09FAM/09FAM040205.html
https://www.ecfr.gov/api/renderer/v1/content/enhanced/current/title-8?part=214&section=214.2', '2026-10-04'),
  ('Học sinh cấp 1–2 (lớp K–8) có dùng visa F-1 để học ở Mỹ được không?', 'Trường THPT / Loại visa', 'verified', 'Không thể học trường công lập từ mẫu giáo đến lớp 8 bằng F-1: Bộ Ngoại giao nêu không có trường/hệ thống trường công tiểu học nào được SEVP cho phép cấp I-20 cho F-1 ở các lớp này. Tuy nhiên học sinh trong độ tuổi đi học (K–12) có thể nhận visa F-1 để học trường tư thục có chứng nhận SEVP. Trường hợp trẻ đi theo cha/mẹ có visa phụ thuộc là trường hợp khác, không dùng F-1.', 'https://fam.state.gov/fam/09FAM/09FAM040205.html
https://www.govinfo.gov/content/pkg/USCODE-2023-title8/html/USCODE-2023-title8-chap12-subchapII-partII-sec1184.htm', '2026-10-04'),
  ('Trường tư thục THPT nào mới được nhận học sinh quốc tế diện F-1 và cấp I-20?', 'Trường THPT / Loại visa', 'verified', 'Học sinh F-1 phải có Form I-20 do trường được Chương trình SEVP chứng nhận cấp. Quy định liên bang nêu rõ trường tư tiểu học/trung học cơ sở hoặc trung học (công hoặc tư) có chứng nhận mới được nhận học sinh F-1 theo chương trình học đủ giờ. Gia đình cần hỏi trường (DSO) xem trường có được SEVP chứng nhận và nhận học sinh quốc tế hay không trước khi nộp hồ sơ.', 'https://www.ecfr.gov/api/renderer/v1/content/enhanced/current/title-8?part=214&section=214.2', '2026-10-04'),
  ('Đang học trường tư bằng F-1, nếu chuyển sang trường công lập thì có sao không?', 'Trường THPT / Loại visa', 'verified', 'Có rủi ro vi phạm tình trạng. Luật Mỹ quy định học sinh F-1 học trường tư mà bỏ để chuyển sang trường tiểu học công, hoặc trường THPT công (nếu không đáp ứng điều kiện 12 tháng và hoàn trả đủ chi phí) bị coi là vi phạm tình trạng và visa F-1 bị vô hiệu. Vì vậy trước khi chuyển trường phải trao đổi với DSO của trường hiện tại.', 'https://www.govinfo.gov/content/pkg/USCODE-2023-title8/html/USCODE-2023-title8-chap12-subchapII-partII-sec1184.htm', '2026-10-04'),
  ('Chương trình trao đổi học sinh THPT J-1 khác F-1 thế nào, điều kiện ra sao?', 'Trường THPT / J-1', 'verified', 'J-1 Secondary School Student là chương trình trao đổi do Bộ Ngoại giao Mỹ chỉ định tổ chức bảo trợ (sponsor); học sinh học một học kỳ hoặc một năm học tại trường THPT công hoặc tư được công nhận, ở với gia đình bản xứ hoặc trường nội trú. Điều kiện: từ 15 đến không quá 18 tuổi 6 tháng tại ngày bắt đầu chương trình (hoặc chưa học quá 11 năm phổ thông), có phẩm chất và năng lực học tập, chưa từng tham gia chương trình trao đổi THPT hoặc học ở Mỹ bằng F-1/J-1. F-1 thì không có các giới hạn tuổi/thời gian đó nhưng phải theo quy định trường công/tư ở trên. Sponsor phải có thư nhận học của trường trước khi cấp DS-2019.', 'https://j1visa.state.gov/programs/secondary-school-student
https://www.ecfr.gov/api/renderer/v1/content/enhanced/current/title-22?part=62&section=62.25', '2026-10-04'),
  ('Gia đình bản xứ (host family) của chương trình J-1 THPT phải đáp ứng những gì?', 'Trường THPT / Homestay', 'verified', 'Sponsor phải sàng lọc host family: phỏng vấn trực tiếp mọi thành viên, kiểm tra lý lịch người lớn trong nhà, cung cấp giường riêng, chỗ để đồ, 3 bữa ăn chất lượng mỗi ngày và phương tiện đến hoạt động của trường. Không xếp học sinh ở với họ hàng, mỗi nhà tối đa 2 học sinh nước ngoài và không cùng quốc gia/ngôn ngữ, học sinh không được đi làm thường xuyên (chỉ việc lặt vặt như trông trẻ). Quy định này áp dụng cho chương trình J-1; homestay của học sinh F-1 do trường hoặc công ty đối tác sắp xếp và có thể có phí.', 'https://www.ecfr.gov/api/renderer/v1/content/enhanced/current/title-22?part=62&section=62.25
https://j1visa.state.gov/programs/secondary-school-student', '2026-10-04'),
  ('Học sinh dưới 18 tuổi học nội trú hoặc trường tư có cần người giám hộ hoặc homestay không?', 'Trường THPT / Giám hộ', 'verified', 'Do từng trường quy định. Ví dụ Berkshire School yêu cầu mọi học sinh nội trú phải chỉ định người giám hộ/người chăm sóc khẩn cấp có thể đến trường trong 24–48 giờ (nhân viên trường không được làm guardian). La Jolla Country Day School (trường ngày) muốn học sinh sống cùng ít nhất một phụ huynh, chỉ cho phép ngoại lệ homestay qua công ty đối tác cho lớp 9–11. Savannah Country Day School có chương trình homestay tự chọn. Gia đình cần hỏi trường về yêu cầu cụ thể.', 'https://www.berkshireschool.org/student-life/international-student-program
https://www.ljcds.org/admission/international-applicants
https://www.savcds.org/admissions/international-applicants/homestay-frequently-asked-questions', '2026-10-04'),
  ('Gửi con cho người thân ở Mỹ làm giám hộ để học trường công miễn phí được không?', 'Trường THPT / Giám hộ', 'verified', 'Không nên. Hướng dẫn của Bộ Ngoại giao nói rõ quyền giám hộ pháp lý không tạo ra mối quan hệ gia đình đủ điều kiện để cư trú tại Mỹ, và thường không được học tập bằng visa B. Nếu học trường công bằng F-1 thì chỉ tối đa 12 tháng và phải trả đủ chi phí bình quân đầu học sinh. Lãnh sự có thể xem đây là dấu hiệu xin visa không đúng mục đích.', 'https://fam.state.gov/fam/09FAM/09FAM040205.html', '2026-10-04'),
  ('SSAT là gì và học sinh quốc tế có bắt buộc thi SSAT để vào trường THPT Mỹ không?', 'Trường THPT / Thi tuyển', 'verified', 'SSAT là kỳ thi tuyển sinh trường tư thục gồm 3 cấp: Elementary (lớp 3–4), Middle (lớp 5–7) và Upper (lớp 8–11), đo kỹ năng đọc, toán, từ vựng kèm bài viết không chấm điểm. Học sinh quốc tế có thể thi giấy hoặc tại trung tâm Prometric; lệ phí quốc tế (tính đến 10/2026) là 339 USD cho lớp 5–11. Có bắt buộc hay không tùy trường: Andover chấp nhận SSAT, ISEE, PSAT, SAT hoặc ACT, còn Choate không bắt buộc điểm chuẩn hóa. Cần xem yêu cầu trên trang tuyển sinh của từng trường.', 'https://www.admission.org/assessments/ssat/about-the-ssat
https://www.andover.edu/admission/apply
https://www.choate.edu/admission/frequently-asked-questions', '2026-10-04'),
  ('Học sinh THPT cần chứng chỉ tiếng Anh nào (TOEFL, IELTS, Duolingo, TOEFL Junior)?', 'Trường THPT / Tiếng Anh', 'verified', 'Tùy trường. Ví dụ Andover yêu cầu TOEFL iBT, IELTS hoặc Duolingo với học sinh học ở trường không dạy bằng tiếng Anh (học sinh trúng tuyển thường từ TOEFL 100, IELTS 7.5, Duolingo 135); Choate đề nghị tối thiểu TOEFL 100, IELTS 7 hoặc Duolingo 130. TOEFL Junior của ETS là bài kiểm tra dành cho học sinh nhỏ tuổi (từ 11 tuổi) chủ yếu để xếp lớp và theo dõi tiến độ; việc trường có chấp nhận điểm TOEFL Junior để xét tuyển hay không phải hỏi trường. Một số trường như La Jolla Country Day School không nhận bài thi tiếng Anh dành cho người học ngoại ngữ.', 'https://www.andover.edu/admission/apply
https://www.choate.edu/admission/frequently-asked-questions
https://www.ets.org/toefl/junior/about.html
https://www.ljcds.org/admission/international-applicants', '2026-10-04'),
  ('Học sinh nhỏ tuổi xin visa du học có phải phỏng vấn không và cần giấy tờ gì?', 'Trường THPT / Visa', 'verified', 'Theo hướng dẫn nội bộ của Bộ Ngoại giao, người nộp đơn từ 14 đến 79 tuổi nói chung phải phỏng vấn trực tiếp, còn người dưới 14 tuổi được miễn yêu cầu phỏng vấn (lãnh sự quán vẫn có thể yêu cầu). Học sinh F-1 phải có Form I-20 từ trường, học sinh J-1 phải có DS-2019 từ sponsor; nếu học trường công thì phải chứng minh đã trả chi phí bình quân đầu học sinh trước khi cấp visa. Quy định có thể thay đổi, cần kiểm tra trang của Đại sứ quán/Tổng lãnh sự quán Mỹ tại Việt Nam trước khi nộp (tính đến 10/2026).', 'https://fam.state.gov/fam/09FAM/09FAM040305.html
https://j1visa.state.gov/participants/how-to-apply/interviews-documents/
https://fam.state.gov/fam/09FAM/09FAM040205.html', '2026-10-04'),
  ('Học phí THPT nội trú ở Mỹ khoảng bao nhiêu, ngoài học phí còn khoản nào khác?', 'Chi phí THPT', 'verified', 'Tùy trường. Ví dụ năm học 2026–27: Choate Rosemary Hall học phí nội trú 73.530 USD và 56.610 USD cho học sinh ngoại trú, cộng 1.000 USD phí công nghệ; Phillips Academy Andover nội trú 79.800 USD. Ngoài ra còn sách vở (Choate ước khoảng 1.000 USD/năm), bảo hiểm y tế bắt buộc, điện thoại có gói dữ liệu Mỹ, đi lại trong kỳ nghỉ; Andover thu phí nộp hồ sơ 125 USD với học sinh quốc tế. Đây chỉ là ví dụ trường tư thục top, trường khác có thể thấp hơn nhiều.', 'https://www.choate.edu/admission/tuition-and-financial-aid
https://www.andover.edu/admission/tuition-financial-aid', '2026-10-04'),
  ('Trường THPT Mỹ có học bổng hoặc hỗ trợ tài chính cho học sinh quốc tế không?', 'Chi phí THPT', 'verified', 'Tùy trường. Phillips Academy Andover nêu xét tuyển need-blind, đáp ứng 100% nhu cầu tài chính được chứng minh bằng grant và 47% học sinh nhận hỗ trợ, đồng thời chào đón hồ sơ hỗ trợ của học sinh quốc tế. Choate nêu đáp ứng 100% nhu cầu tài chính của gia đình nhưng trang tham khảo không nói rõ cho học sinh quốc tế. Nhiều trường khác ít hoặc không có hỗ trợ cho học sinh quốc tế, nên cần hỏi từng trường.', 'https://www.andover.edu/admission/tuition-financial-aid
https://www.andover.edu/admission/apply
https://www.choate.edu/admission/tuition-and-financial-aid', '2026-10-04'),
  ('Số tiền ước tính trên I-20 gồm những khoản nào và liên quan gì đến chứng minh tài chính?', 'Chi phí / I-20', 'verified', 'Số tiền trên I-20 do trường ước tính cho một năm học, thường gồm học phí và lệ phí, nhà ở và ăn uống, sách vở, đi lại, chi tiêu cá nhân và bảo hiểm y tế. Ví dụ Texas State University (2025–26) liệt kê nhà ở và ăn 12.850, sách 760, đi lại 1.620, chi tiêu cá nhân 2.670, bảo hiểm y tế 2.298 USD. Quy định liên bang yêu cầu sinh viên có bằng chứng tài chính tương ứng số tiền ghi trên I-20, và lãnh sự cần thấy đủ tiền cho các chi phí của năm học đầu tiên.', 'https://www.international.txst.edu/future-or-new-f-1-students/i-20-request/estimated-cost-of-attendance-2026-2027/estimated-cost-of-attendance.html
https://www.ecfr.gov/api/renderer/v1/content/enhanced/current/title-8?part=214&section=214.2
https://fam.state.gov/fam/09FAM/09FAM040205.html', '2026-10-04'),
  ('Bảo hiểm y tế có nằm trong chi phí du học không, có bắt buộc không?', 'Chi phí / Bảo hiểm', 'verified', 'Để xin visa F-1 thì không bắt buộc có bảo hiểm y tế hay du lịch của Mỹ, nhưng nhiều trường tự yêu cầu và tính vào chi phí. Ví dụ Choate Rosemary Hall yêu cầu mọi học sinh có bảo hiểm y tế (học sinh quốc tế chưa có bảo hiểm Mỹ phải tham gia gói của trường); San José City College ghi bảo hiểm bắt buộc 1.893 USD (2026–27); IU Indianapolis tính 2.044 USD và Texas State tính 2.298 USD trong ước tính chi phí. Cần xem chính sách bảo hiểm của từng trường.', 'https://fam.state.gov/fam/09FAM/09FAM040205.html
https://www.choate.edu/international-students
https://sjcc.edu/students/international-students/apply/tuition-and-fees.aspx
https://indy.iu.edu/cost-aid/cost-of-attendance/international-cost-attendance.html
https://www.international.txst.edu/future-or-new-f-1-students/i-20-request/estimated-cost-of-attendance-2026-2027/estimated-cost-of-attendance.html', '2026-10-04'),
  ('Bằng thạc sĩ ở Mỹ gồm những loại nào và học mất bao lâu?', 'Chương trình học', 'verified', 'Theo EducationUSA, hai bằng sau đại học chính là thạc sĩ và tiến sĩ. Thạc sĩ có thể thiên về học thuật (MA, MS) hoặc nghề nghiệp (MBA, MFA, MSW, MEd). Chương trình có thể có lựa chọn làm luận văn (thesis) hoặc không luận văn (non-thesis), thường cần một đến ba năm sau bằng cử nhân. Thời lượng và hình thức cụ thể tùy từng trường và chương trình.', 'https://educationusa.state.gov/your-5-steps-us-study/research-your-options/graduate/what-graduate-student', '2026-10-04'),
  ('GRE/GMAT có bắt buộc khi xin học thạc sĩ không?', 'Hồ sơ', 'verified', 'Không có quy định chung: mỗi trường tự đặt yêu cầu tuyển sinh, kể cả việc nhận hay không nhận bài thi chuẩn hóa. Nhiều chương trình sau đại học yêu cầu GRE hoặc GMAT (GMAT thường dùng cho MBA), nhưng yêu cầu khác nhau giữa các trường. Cần xem trang tuyển sinh của chính chương trình. EducationUSA khuyên thi trước ngày bắt đầu học khoảng 12 đến 18 tháng.', 'https://educationusa.state.gov/your-5-steps-us-study/research-your-options/graduate/prepare-us-standardized-tests', '2026-10-04'),
  ('Thư giới thiệu và bài luận (SOP) trong hồ sơ thạc sĩ cần viết thế nào?', 'Hồ sơ', 'verified', 'EducationUSA mô tả bài luận cá nhân là cơ hội để hội đồng tuyển sinh hiểu bạn là ai; nên rõ ràng, súc tích, thuyết phục và nêu điểm mạnh phù hợp với chương trình. Thư giới thiệu nên do giảng viên cũ, quản lý hoặc người từng làm việc cùng viết, đánh giá sâu về năng lực học sau đại học của bạn. Không nên thổi phồng kinh nghiệm hay biện minh. Định dạng và yêu cầu cụ thể tùy từng trường.', 'https://educationusa.state.gov/complete-your-us-application-graduate', '2026-10-04'),
  ('Học thạc sĩ có thể xin miễn học phí qua trợ giảng/trợ lý nghiên cứu không?', 'Học bổng', 'verified', 'Một số trường có vị trí trợ giảng (teaching assistant) hoặc trợ lý nghiên cứu (research assistant) đổi lấy miễn học phí và/hoặc tiền hỗ trợ sinh hoạt. EducationUSA nói điều này rất phổ biến ở bậc tiến sĩ, nên với thạc sĩ không nên mặc định sẽ có. Cần hỏi trực tiếp khoa/chương trình về loại hỗ trợ, trách nhiệm công việc và mức hỗ trợ trước khi nhận.', 'https://educationusa.state.gov/your-5-steps-us-study/finance-your-studies/graduate', '2026-10-04'),
  ('Cần lập kế hoạch tài chính cho thạc sĩ sớm đến mức nào?', 'Tài chính', 'verified', 'EducationUSA khuyên bắt đầu lập kế hoạch tài chính sớm nhất có thể, tính cả học phí, lệ phí và sinh hoạt phí, và dự trù học phí tăng khoảng 6-10% mỗi năm. Hạn nộp học bổng có thể sớm tới 18 tháng trước ngày khai giảng. Phần lớn học bổng chỉ chi trả một phần chi phí. Chi phí thực tế tùy từng trường (tính đến 10/2026).', 'https://educationusa.state.gov/your-5-steps-us-study/finance-your-studies/graduate', '2026-10-04'),
  ('Nên bắt đầu tìm trường thạc sĩ khi nào?', 'Lộ trình', 'verified', 'EducationUSA khuyên bắt đầu tìm hiểu ít nhất 12 đến 18 tháng trước năm học dự định nhập học. Hơn 1.000 trường ở Mỹ có chương trình sau đại học, nên cần thời gian nghiên cứu. Có thể dùng trung tâm tư vấn EducationUSA, website trường và hội thảo giáo dục.', 'https://educationusa.state.gov/your-5-steps-us-study/research-your-options/graduate', '2026-10-04'),
  ('Sinh viên thạc sĩ F-1 làm trợ giảng/trợ lý trong trường có bị giới hạn giờ không?', 'Làm thêm', 'verified', 'Việc làm trong trường (on-campus) của sinh viên F-1 không được vượt quá 20 giờ mỗi tuần khi đang học, và có thể làm toàn thời gian khi nghỉ học/nghỉ hè. Quy định liên bang cũng nói việc làm theo điều khoản học bổng, fellowship hoặc assistantship được coi là một phần của chương trình học. Điều kiện cụ thể của vị trí cần hỏi DSO và khoa.', 'https://www.ecfr.gov/api/versioner/v1/full/2026-09-01/title-8.xml?part=214&section=214.2', '2026-10-04'),
  ('Học thạc sĩ ngành STEM có được gia hạn OPT không?', 'Sau tốt nghiệp', 'verified', 'Quy định liên bang cho phép sinh viên có bằng cử nhân, thạc sĩ hoặc tiến sĩ thuộc ngành STEM nằm trong danh sách ngành STEM do DHS công bố xin gia hạn OPT thêm 24 tháng, sau thời gian OPT sau tốt nghiệp. Trường phải được công nhận (accredited) và DSO đề nghị trong SEVIS. Ngành của bạn có thuộc danh sách STEM hay không cần kiểm tra với DSO.', 'https://www.ecfr.gov/api/versioner/v1/full/2026-09-01/title-8.xml?part=214&section=214.2', '2026-10-04'),
  ('Sinh viên thạc sĩ cần chứng minh tài chính thế nào khi nhập cảnh?', 'Visa', 'verified', 'Khi vào Mỹ với tư cách F-1, sinh viên phải có bằng chứng tài liệu về khả năng tài chính đúng với số tiền ghi trên Form I-20. Số tiền này do trường ghi trên I-20. Nếu có học bổng hoặc assistantship, cách trường ghi nhận khoản hỗ trợ trên I-20 tùy từng trường nên cần hỏi DSO. Viên chức lãnh sự có thể hỏi thêm khi phỏng vấn.', 'https://www.ecfr.gov/api/versioner/v1/full/2026-09-01/title-8.xml?part=214&section=214.2', '2026-10-04'),
  ('MBA và thạc sĩ khoa học (MS) khác nhau thế nào về bài thi đầu vào?', 'Hồ sơ', 'verified', 'EducationUSA mô tả GRE là bài thi đo tư duy ngôn ngữ, định lượng và viết phân tích để đánh giá mức sẵn sàng học sau đại học, còn GMAT là bài thi dành cho ứng viên MBA. Tuy nhiên mỗi trường tự quyết định nhận bài thi nào. Cần xác nhận trên trang của chương trình.', 'https://educationusa.state.gov/your-5-steps-us-study/research-your-options/graduate/prepare-us-standardized-tests', '2026-10-04'),
  ('Tiến sĩ ở Mỹ có những yêu cầu gì?', 'Chương trình học', 'verified', 'Theo EducationUSA, bằng tiến sĩ chuẩn bị người học cho vị trí giảng viên đại học, nghiên cứu viên hoặc nghề cần kỹ năng nghiên cứu chuyên sâu. Ứng viên phải vượt qua kỳ thi tổng hợp (comprehensive exam) và hoàn thành nghiên cứu gốc dẫn tới luận án (dissertation). Ngoài PhD còn có tiến sĩ chuyên nghiệp như EdD, DBA. Quy trình chi tiết tùy khoa.', 'https://educationusa.state.gov/your-5-steps-us-study/research-your-options/graduate/what-graduate-student', '2026-10-04'),
  ('Học tiến sĩ ở Mỹ có được miễn học phí và có tiền hỗ trợ không?', 'Học bổng', 'verified', 'Nhiều chương trình có trợ giảng hoặc trợ lý nghiên cứu để đổi lấy miễn học phí và/hoặc tiền hỗ trợ sinh hoạt (stipend). EducationUSA nói điều này rất phổ biến ở bậc tiến sĩ. Các loại hỗ trợ chính gồm fellowship, teaching assistantship, research assistantship và administrative assistantship. Không phải chương trình nào cũng bảo đảm, nên cần xác nhận mức hỗ trợ và trách nhiệm công việc với khoa.', 'https://educationusa.state.gov/your-5-steps-us-study/finance-your-studies/graduate', '2026-10-04'),
  ('Có nên liên hệ giáo sư trước khi nộp hồ sơ tiến sĩ không?', 'Học bổng', 'verified', 'EducationUSA khuyên liên hệ giảng viên trong khoa quan tâm vì họ có vai trò quan trọng trong việc xác định và chọn người nhận tài trợ của khoa. Khi chọn chương trình cũng nên xem giảng viên nào có hướng nghiên cứu trùng với mối quan tâm của bạn. Cách liên hệ và việc giảng viên có nhận email của ứng viên hay không tùy từng khoa.', 'https://educationusa.state.gov/your-5-steps-us-study/finance-your-studies/graduate
https://educationusa.state.gov/your-5-steps-us-study/research-your-options/graduate/define-your-priorities', '2026-10-04'),
  ('Nghiên cứu sinh F-1 làm trợ giảng/trợ lý nghiên cứu được tối đa bao nhiêu giờ?', 'Làm thêm', 'verified', 'Việc làm trong trường của sinh viên F-1 không được vượt quá 20 giờ mỗi tuần khi đang học; được làm toàn thời gian khi nghỉ hè hoặc nghỉ học. Việc làm tại cơ sở ngoài trường có liên kết giáo dục vẫn có thể là on-campus nếu gắn với dự án nghiên cứu được tài trợ theo hợp đồng ở bậc sau đại học. Đây là quy định liên bang; số giờ cụ thể của vị trí assistantship tùy trường.', 'https://www.ecfr.gov/api/versioner/v1/full/2026-09-01/title-8.xml?part=214&section=214.2', '2026-10-04'),
  ('Thời gian học tiến sĩ ở Mỹ thường kéo dài bao lâu?', 'Thống kê', 'verified', 'Số liệu NSF/NCSES (Survey of Earned Doctorates) cho thấy thời gian trung vị từ lúc vào cao học đến khi nhận bằng khác nhau theo ngành: gần 9 năm ở khoa học sức khỏe và khoa học xã hội, 10 năm ở nhóm ngoài S&E (số liệu 2022). Con số tính từ lúc vào cao học nên có thể gồm cả thời gian học thạc sĩ và gián đoạn. Thời gian thực tế tùy chương trình và hướng nghiên cứu; không nên khẳng định cố định 5-6 năm.', 'https://ncses.nsf.gov/pubs/nsf24300/report/path-to-the-doctorate', '2026-10-04'),
  ('Nghiên cứu sinh tiến sĩ ở Mỹ thường được tài trợ bằng nguồn nào?', 'Thống kê', 'verified', 'Theo NCSES (số liệu 2022), nguồn tài trợ chính của người nhận bằng tiến sĩ là research assistantship hoặc traineeship (35,0%), fellowship/học bổng/dissertation grant (24,6%) và teaching assistantship (21,7%). Khoảng 14,6% dùng nguồn tự túc. Tỷ lệ khác nhau theo ngành: ngành kỹ thuật và khoa học máy tính phổ biến research assistantship, còn toán và thống kê phổ biến teaching assistantship hơn.', 'https://ncses.nsf.gov/pubs/nsf24300/report/path-to-the-doctorate', '2026-10-04'),
  ('Sinh viên quốc tế chiếm bao nhiêu trong số người nhận bằng tiến sĩ ở Mỹ?', 'Thống kê', 'verified', 'NCSES cho biết năm 2024, người giữ visa tạm thời nhận phần lớn bằng tiến sĩ ở một số ngành: khoa học máy tính và thông tin (61%), kỹ thuật (54%), toán và thống kê (51%). Đây là thống kê chung, không cho biết khả năng trúng tuyển của từng cá nhân.', 'https://ncses.nsf.gov/surveys/earned-doctorates/2024', '2026-10-04'),
  ('Có thể nộp thẳng tiến sĩ sau cử nhân không, hay phải có thạc sĩ?', 'Hồ sơ', 'verified', 'EducationUSA định nghĩa sinh viên sau đại học là người đã có bằng cử nhân, và nói với đa số chương trình không bắt buộc bằng cử nhân đúng chuyên ngành, dù một số yêu cầu học phần tiên quyết. Trang này không nêu rõ có bắt buộc thạc sĩ để vào tiến sĩ hay không, nên điều kiện (nộp thẳng từ cử nhân hay cần thạc sĩ) phải xem trên trang của từng chương trình.', 'https://educationusa.state.gov/your-5-steps-us-study/research-your-options/graduate/what-graduate-student', '2026-10-04'),
  ('Nghiên cứu sinh tiến sĩ dùng visa F-1 hay J-1?', 'Visa', 'verified', 'Theo EducationUSA, F là visa du học tại trường được công nhận (accredited), còn J là visa trao đổi cho người tham gia chương trình trao đổi, gồm cả học đại học. Giấy tờ nhận được tùy đơn vị bảo trợ: Form I-20 cho F-1, DS-2019 cho J-1. Loại nào áp dụng cho bạn tùy trường và nguồn tài trợ; hãy hỏi DSO hoặc đơn vị tài trợ.', 'https://educationusa.state.gov/your-5-steps-us-study/apply-your-student-visa/graduate', '2026-10-04'),
  ('Học tiến sĩ ngành STEM có thể xin OPT thêm không?', 'Sau tốt nghiệp', 'verified', 'Quy định liên bang cho phép gia hạn OPT STEM 24 tháng cho người có bằng tiến sĩ ngành STEM thuộc danh sách DHS. Tối đa hai lần gia hạn STEM OPT trong đời, và lần sau phải dựa trên bằng ở bậc cao hơn bằng đã dùng cho lần gia hạn đầu. Ngành có thuộc danh sách STEM hay không cần hỏi DSO.', 'https://www.ecfr.gov/api/versioner/v1/full/2026-09-01/title-8.xml?part=214&section=214.2', '2026-10-04'),
  ('Nghiên cứu sinh có trợ cấp từ trường thì chứng minh tài chính thế nào?', 'Visa', 'verified', 'Khi vào Mỹ với tư cách F-1 phải có tài liệu chứng minh khả năng tài chính đúng số tiền ghi trên Form I-20. Với nghiên cứu sinh được trường hỗ trợ (miễn học phí, stipend), cách trường ghi khoản đó vào I-20 và loại giấy cần nộp tùy trường và viên chức lãnh sự. Nên hiểu rõ mức hỗ trợ và trách nhiệm trước khi nhận và hỏi DSO trước khi xin visa.', 'https://www.ecfr.gov/api/versioner/v1/full/2026-09-01/title-8.xml?part=214&section=214.2
https://educationusa.state.gov/your-5-steps-us-study/finance-your-studies/graduate', '2026-10-04'),
  ('Học sinh F-1 được học trường trung học công lập ở Mỹ trong bao lâu?', 'Chương trình học', 'verified', 'Học sinh F-1 chỉ được học trường trung học công lập lớp 9-12 đã được SEVP chứng nhận, tối đa 12 tháng cộng dồn tại mọi trường công. Phải trả đủ chi phí giáo dục chưa trợ cấp trước khi xin visa. Không được học trường công từ mẫu giáo đến lớp 8. Hết 12 tháng có thể chuyển sang trường tư đã được SEVP chứng nhận; không được chuyển sang trường công khác khi đã hết 12 tháng.', 'https://studyinthestates.dhs.gov/schools/get-started/grade-9-to-grade-12-public-schools', '2026-10-08'),
  ('Học sinh F-1 học trường tư thục có bị giới hạn thời gian không?', 'Chương trình học', 'verified', 'Không bị giới hạn thời gian. F-1 được học trường tư từ mẫu giáo đến lớp 12, khác với trường công chỉ mở cho lớp 9-12 và tối đa 12 tháng.', 'https://studyinthestates.dhs.gov/guide/f-1/f-1-kindergarten-through-grade-12', '2026-10-08'),
  ('Học sinh F-1 được nhập cảnh Mỹ sớm nhất bao lâu trước ngày nhập học?', 'Visa', 'verified', 'Không được vào Mỹ sớm hơn 30 ngày trước ngày bắt đầu chương trình ghi trên Form I-20.', 'https://travel.state.gov/content/travel/en/us-visas/study/student-visa.html', '2026-10-08'),
  ('Sau khi trường THPT cấp I-20, hồ sơ visa F-1 gồm những gì?', 'Visa', 'verified', 'Gồm Form I-20 từ trường đã được SEVP chứng nhận, biên lai phí SEVIS I-901, đơn DS-160, phí xin visa, hộ chiếu và hồ sơ tài chính. Visa không bảo đảm được nhập cảnh; hải quan Mỹ quyết định tại cửa khẩu.', 'https://travel.state.gov/content/travel/en/us-visas/study/student-visa.html', '2026-10-08'),
  ('Tiêu chí đánh giá điều kiện đầu vào của học sinh khi du học Mỹ gồm những yếu tố nào?', 'faq_tu_van', 'draft', 'Khi xét tuyển du học Mỹ, các trường đại học không áp dụng một mức sàn GPA chung (như 7.0/10) mà đánh giá hồ sơ theo quy trình toàn diện (Holistic Review). Hai yếu tố cốt lõi bao gồm: (1) Năng lực học thuật: Thể hiện qua học bạ THPT, độ khó của môn học, chứng chỉ tiếng Anh (TOEFL/IELTS) và điểm thi chuẩn hóa (SAT/ACT) nếu trường yêu cầu; (2) Năng lực tài chính: Gia đình cần chứng minh khả năng chi trả tối thiểu cho năm học đầu tiên theo chi phí ước tính trên mẫu I-20. Thí sinh nên tra cứu trực tiếp yêu cầu cụ thể trên trang tuyển sinh của từng trường mục tiêu. (Nguồn kiểm chứng: EducationUSA - U.S. Department of State).', 'https://educationusa.state.gov', '2026-09-27'),
  ('Yêu cầu chứng chỉ tiếng Anh (IELTS) tối thiểu cho bậc Cao đẳng và Đại học là bao nhiêu?', 'faq_tu_van', 'draft', 'Mỗi cơ sở giáo dục tại Mỹ tự quy định chuẩn năng lực tiếng Anh đầu vào: Cao đẳng cộng đồng thường yêu cầu mức điểm tương đương IELTS 5.0 - 5.5 (hoặc Duolingo 85-95); Đại học 4 năm thường yêu cầu tối thiểu IELTS 6.0 - 6.5 (hoặc Duolingo 105-115). Để cạnh tranh học bổng thành tích cao (Merit Scholarship), ứng viên thường cần đạt từ IELTS 7.0 trở lên. Các trường chấp nhận đa dạng bài thi gồm TOEFL iBT, IELTS, Duolingo English Test hoặc PTE. (Nguồn kiểm chứng: EducationUSA - Standardized Testing Guide).', 'https://educationusa.state.gov', '2026-09-27'),
  ('Du học Mỹ sớm từ bậc THPT (lớp 9 hoặc 10) mang lại những lợi thế gì cho lộ trình vào Đại học?', 'faq_tu_van', 'draft', 'Du học THPT tại Mỹ mang lại các lợi thế học thuật rõ rệt: Cơ hội tích lũy tín chỉ đại học sớm qua các môn AP (Advanced Placement) hoặc Dual Credit, rèn luyện kỹ năng viết luận học thuật và nhận thư giới thiệu trực tiếp từ giáo viên Mỹ. Tuy nhiên, về mặt pháp lý, học sinh diện visa F-1 chỉ được học trường THPT công lập tối đa 12 tháng và phải trả đủ chi phí không trợ cấp (theo 8 U.S.C. 1184m); nếu muốn học dài hạn để tốt nghiệp tại Mỹ thì bắt buộc phải theo học trường tư thục được SEVP chứng nhận. (Nguồn kiểm chứng: SEVP & 8 U.S.C. 1184m).', 'https://educationusa.state.gov', '2026-09-27'),
  ('Sau khi hoàn thành THPT tại Việt Nam thì có những lựa chọn lộ trình nào để học đại học tại Mỹ?', 'faq_tu_van', 'draft', 'Sau khi tốt nghiệp THPT tại Việt Nam, học sinh có 2 lộ trình cử nhân chính thức: (1) Học thẳng 4 năm tại một trường Đại học (Four-year College/University) để lấy bằng Cử nhân (Bachelor''s Degree); (2) Lộ trình chuyển tiếp 2+2: Học 2 năm đầu tại trường Cao đẳng cộng đồng (Community College) để lấy bằng Cao đẳng (Associate Degree), sau đó chuyển tiếp 2 năm cuối lên một trường Đại học để hoàn thành bằng Cử nhân. Cả hai lộ trình khi tốt nghiệp đều nhận cùng một tấm bằng cử nhân của trường đại học chuyển đến. (Nguồn kiểm chứng: EducationUSA - Community College & 2+2 Pathway).', 'https://educationusa.state.gov', '2026-09-27'),
  ('Chi phí dự trù cho lộ trình Đại học 4 năm và Cao đẳng cộng đồng 2+2 là bao nhiêu một năm?', 'faq_tu_van', 'draft', 'Chi phí du học Mỹ thay đổi đáng kể tùy theo loại hình trường và địa điểm bang: (1) Bậc Cao đẳng cộng đồng (Community College): Học phí khoảng $8.000 - $13.000/năm, tổng chi phí gồm ăn ở dao động từ $20.000 - $28.000/năm; (2) Bậc Đại học 4 năm công lập: Học phí dao động $20.000 - $35.000/năm, tổng chi phí từ $35.000 - $55.000/năm; (3) Đại học tư thục: Tổng chi phí thường từ $60.000 - $90.000+/năm. Gia đình cần tra cứu chỉ số Cost of Attendance (COA) chính thức trên website của từng trường cụ thể. (Nguồn kiểm chứng: College Board Trends in College Pricing & EducationUSA).', 'https://educationusa.state.gov', '2026-09-27'),
  ('Khi chọn trường cho kỳ nhập học Mùa Xuân (Spring), sinh viên cần kiểm tra điều kiện gì?', 'faq_tu_van', 'draft', 'Khi nộp hồ sơ vào kỳ Mùa Xuân (Spring - tháng 1), sinh viên bắt buộc phải kiểm tra: (1) Ngành học dự kiến có mở tuyển sinh cho sinh viên quốc tế vào kỳ Spring không (nhiều ngành cạnh tranh chỉ mở duy nhất kỳ Fall); (2) Các suất học bổng thành tích và hỗ trợ tài chính có áp dụng cho kỳ Spring không; (3) Thời hạn nộp hồ sơ (thường chốt rất sớm, từ tháng 9 đến tháng 10 năm trước). (Nguồn kiểm chứng: Common App & EducationUSA Application Deadlines).', 'https://educationusa.state.gov', '2026-09-27'),
  ('Hạn chót (Deadline) nộp hồ sơ của sinh viên quốc tế có giống nhau giữa các trường không?', 'faq_tu_van', 'draft', 'Không có một hạn chót nộp hồ sơ chung cho tất cả các trường đại học tại Mỹ. Mỗi trường có các mốc tuyển sinh hoàn toàn độc lập và hạn chót cho sinh viên quốc tế thường đóng sớm hơn sinh viên bản địa từ 4 đến 8 tuần để kịp hoàn thành thủ tục tài chính, cấp I-20 và xin visa. Thí sinh cần lập bảng theo dõi hạn chót cụ thể cho từng trường mục tiêu. (Nguồn kiểm chứng: EducationUSA - Steps to Apply).', 'https://educationusa.state.gov', '2026-09-27'),
  ('Điểm thi chuẩn hóa SAT/ACT có bắt buộc khi xét tuyển và xin học bổng không?', 'faq_tu_van', 'draft', 'Hiện nay phần lớn các đại học tại Mỹ áp dụng chính sách xét tuyển linh hoạt: (1) Test-Optional: Không bắt buộc nộp điểm SAT/ACT, không bị trừ điểm nếu không nộp; (2) Test-Required: Bắt buộc phải có điểm SAT/ACT (tiêu biểu như MIT, Dartmouth, University of Florida). Tuy nhiên, đối với việc xét học bổng thành tích (Merit Scholarship) hoặc các ngành kỹ thuật/khoa học máy tính cạnh tranh cao, điểm SAT tốt (1400+) luôn là một lợi thế học thuật rất lớn. (Nguồn kiểm chứng: National Center for Fair & Open Testing - FairTest & EducationUSA).', 'https://educationusa.state.gov', '2026-09-27'),
  ('Mức học bổng năng lực (Merit-based) tại các trường Đại học Mỹ thường dao động bao nhiêu?', 'faq_tu_van', 'draft', 'Học bổng năng lực (Merit-based) của đại học Mỹ thường được tính theo định mức số tiền cụ thể hàng năm ($/năm) chứ không cam kết cố định theo tỷ lệ phần trăm (30% hay 70%). Mức phổ biến tại các trường công lập dao động từ $4.000 đến $20.000/năm. Để tối đa hóa cơ hội nhận học bổng, thí sinh phải nộp hồ sơ trước hạn ưu tiên xét học bổng (Priority Deadline, thường là ngày 01/11 hoặc 01/12) và đáp ứng các tiêu chuẩn về GPA, chứng chỉ tiếng Anh, bài luận và điểm SAT. (Nguồn kiểm chứng: EducationUSA - Finance Your Studies).', 'https://educationusa.state.gov', '2026-09-27'),
  ('Bài luận cá nhân (Personal Statement) và bài luận phụ (Supplemental Essays) có yêu cầu gì?', 'faq_tu_van', 'draft', 'Bộ hồ sơ đại học Mỹ thường yêu cầu 2 nhóm bài luận: (1) Bài luận chính (Personal Statement): Giới hạn 650 từ trên cổng Common App, giúp hội đồng tuyển sinh hiểu về tính cách, giá trị sống, tư duy và khả năng vượt khó của ứng viên qua một câu chuyện cá nhân chân thực; (2) Bài luận phụ (Supplemental Essays): Do từng trường tự ra đề bài riêng (thường từ 150 - 400 từ), tập trung trả lời câu hỏi vì sao bạn chọn trường, chọn ngành và bạn sẽ đóng góp được gì cho cộng đồng của trường. (Nguồn kiểm chứng: Common Application Writing Guide & NACAC).', 'https://educationusa.state.gov', '2026-09-27'),
  ('Hoạt động ngoại khóa có vai trò gì trong bộ hồ sơ du học Mỹ?', 'faq_tu_van', 'draft', 'Trong quy trình xét tuyển toàn diện (Holistic Admissions) của đại học Mỹ, hoạt động ngoại khóa đóng vai trò minh chứng cho tính cách, niềm đam mê và kỹ năng lãnh đạo ngoài điểm số. Hội đồng tuyển sinh không tìm kiếm thí sinh tham gia quá nhiều hoạt động bề nổi mà đánh giá cao sự gắn bó bền bỉ, tính chủ động khởi xướng và tác động thực chất mà hoạt động đó mang lại cho cộng đồng. (Nguồn kiểm chứng: EducationUSA Undergraduate Guide & Harvard College Admissions Principles).', 'https://educationusa.state.gov', '2026-09-27'),
  ('Thời gian và lộ trình chuẩn bị hồ sơ du học Mỹ trước kỳ nhập học nên bắt đầu khi nào?', 'faq_tu_van', 'draft', 'Theo lộ trình chuẩn của EducationUSA, học sinh nên bắt đầu chuẩn bị từ 12 đến 18 tháng trước kỳ nhập học mục tiêu: (1) Lớp 10 - đầu lớp 11: Ôn luyện chứng chỉ tiếng Anh (IELTS/TOEFL) và chuẩn bị SAT, xây dựng hoạt động ngoại khóa; (2) Học kỳ 2 lớp 11: Lọc danh sách trường và bắt đầu viết bài luận cá nhân; (3) Đầu lớp 12: Hoàn thiện hồ sơ, xin thư giới thiệu và nộp đơn các vòng sớm (Early) trước tháng 11; (4) Tháng 1 - 4: Nhận kết quả, đặt cọc lấy I-20 và chuẩn bị phỏng vấn visa. (Nguồn kiểm chứng: EducationUSA - 5 Steps to U.S. Study Timeline).', 'https://educationusa.state.gov', '2026-09-27'),
  ('Thư giới thiệu (Letter of Recommendation - LOR) nên xin từ ai và cần chuẩn bị gì?', 'faq_tu_van', 'draft', 'Hồ sơ đại học Mỹ thường yêu cầu từ 1 đến 2 thư giới thiệu của giáo viên bộ môn học thuật (Toán, Khoa học, Xã hội hoặc Ngữ văn) đã dạy bạn trong lớp 11 hoặc 12, cùng 1 bản đánh giá từ Cố vấn học tập (Counselor Recommendation). Người viết thư phải là người trực tiếp giảng dạy và hiểu rõ năng lực, thái độ học tập cũng như sự đóng góp của bạn trong lớp; thư cần tập trung vào các ví dụ cụ thể thay vì lời khen chung chung. (Nguồn kiểm chứng: Common App Recommendation Guidelines).', 'https://educationusa.state.gov', '2026-09-27'),
  ('Hồ sơ chứng minh tài chính cần những giấy tờ gì để trường cấp I-20 và nộp phỏng vấn visa?', 'faq_tu_van', 'draft', 'Quy trình chứng minh tài chính gồm 2 bước: (1) Giai đoạn cấp I-20: Nộp Bản cam kết hỗ trợ tài chính (Affidavit of Support) và Giấy xác nhận số dư tài khoản ngân hàng/sổ tiết kiệm có giá trị tối thiểu bằng tổng chi phí ước tính năm đầu của trường; (2) Giai đoạn phỏng vấn visa F-1: Chuẩn bị hồ sơ chứng minh nguồn gốc tài chính minh bạch gồm sổ tiết kiệm, sao kê lương, hợp đồng lao động, giấy phép đăng ký kinh doanh và giấy tờ sở hữu tài sản để chứng minh gia đình có đủ khả năng tài chính nuôi dưỡng việc học lâu dài. (Nguồn kiểm chứng: 8 CFR 214.2(f) & U.S. Embassy Vietnam Financial Guidance).', 'https://educationusa.state.gov', '2026-09-27'),
  ('Quy trình xin visa du học Mỹ F-1 gồm những bước chính nào?', 'faq_tu_van', 'draft', 'Quy trình 5 bước xin visa du học F-1 chuẩn xác: (1) Nhận mẫu I-20 chính thức có chữ ký của đại diện trường (DSO); (2) Đóng phí SEVIS I-901 trị giá $350 trực tuyến qua trang chính phủ fmjfee.com; (3) Điền tờ khai điện tử DS-160 và lưu mã xác nhận; (4) Đóng phí phỏng vấn thị thực (MRV fee) trị giá $185 và đặt lịch hẹn tại Hà Nội hoặc TP.HCM qua cổng usvisascheduling.com; (5) Tham dự buổi phỏng vấn trực tiếp tại Đại sứ quán hoặc Lãnh sự quán Hoa Kỳ. (Nguồn kiểm chứng: travel.state.gov - Student Visa).', 'https://educationusa.state.gov', '2026-09-27'),
  ('Khi phỏng vấn visa F-1, sinh viên cần tập trung trả lời những nội dung cốt lõi nào?', 'faq_tu_van', 'draft', 'Khi phỏng vấn visa F-1, ứng viên cần trả lời ngắn gọn, tự tin, trung thực vào 4 trọng tâm chính: (1) Mục tiêu học thuật: Tại sao chọn đúng trường và ngành này mà không học ở Việt Nam; (2) Năng lực tài chính: Ai là người chi trả, thu nhập từ đâu và chứng minh khả năng chi trả bền vững; (3) Kế hoạch học tập cụ thể tại Mỹ; (4) Ràng buộc trở về: Kế hoạch nghề nghiệp rõ ràng tại Việt Nam sau khi tốt nghiệp để giải tỏa giả định định cư theo điều khoản 214(b) Đạo luật Di trú INA. Tuyệt đối không học thuộc lòng bài mẫu. (Nguồn kiểm chứng: 9 FAM 402.5 & U.S. Department of State Visa Refusals).', 'https://educationusa.state.gov', '2026-09-27'),
  ('Du học sinh diện F-1 được nhập cảnh vào Mỹ sớm nhất trước bao nhiêu ngày?', 'faq_tu_van', 'draft', 'Theo luật định liên bang (8 CFR 214.2(f)(5)), sinh viên quốc tế diện visa F-1 lần đầu đến Mỹ chỉ được phép nhập cảnh sớm nhất 30 ngày trước ngày bắt đầu chương trình học ghi trên mẫu I-20 (Program Start Date / Earliest Admission Date). Nếu cố tình bay đến Mỹ trước mốc 30 ngày này, sĩ quan Hải quan và Biên phòng Hoa Kỳ (CBP) sẽ từ chối nhập cảnh tại sân bay. (Nguồn kiểm chứng: 8 CFR 214.2(f)(5) & U.S. Customs and Border Protection - CBP).', 'https://educationusa.state.gov', '2026-09-27'),
  ('Ba câu hỏi ưu tiên theo thứ tự để tự đánh giá và đưa một trường vào danh sách chọn là gì?', 'faq_tu_van', 'draft', 'Quy trình 3 bước tự đánh giá độ tương thích của trường (School Fit) gồm: (1) Phù hợp chuyên ngành: Trường có thế mạnh đào tạo ngành bạn muốn học và chương trình giảng dạy có đúng định hướng nghiên cứu/thực hành của bạn không; (2) Phù hợp tài chính: Tổng chi phí (học phí + ăn ở) sau khi trừ đi học bổng ước tính có nằm trong ngân sách chi trả của gia đình không; (3) Khả năng trúng tuyển: Năng lực học tập (GPA, tiếng Anh, SAT) có nằm trong phổ điểm trung bình của sinh viên năm trước không. Thỏa mãn cả 3 yếu tố mới đưa vào danh sách ứng tuyển. (Nguồn kiểm chứng: EducationUSA - Define Your Priorities).', 'https://educationusa.state.gov', '2026-09-27'),
  ('Đi học thẳng Đại học 4 năm hay Cao đẳng cộng đồng (CC/ESL) thuận lợi hơn khi phỏng vấn visa?', 'faq_tu_van', 'draft', 'Về mặt pháp lý, Sổ tay Ngoại giao của Bộ Ngoại giao Hoa Kỳ (9 FAM 402.5-5) nêu rõ: Không có sự phân biệt pháp lý giữa cơ sở giáo dục 4 năm, trường cao đẳng cộng đồng hay trung tâm đào tạo tiếng Anh trong việc cấp visa F-1. Điều quyết định không phải là bậc học trên I-20 mà là khả năng giải trình logic của học sinh: Kế hoạch học tập có phù hợp với năng lực hiện tại không và lý do chọn Cao đẳng cộng đồng (ví dụ tiết kiệm chi phí, lớp học quy mô nhỏ) có thuyết phục và minh bạch không. (Nguồn kiểm chứng: 9 FAM 402.5-5(E) U.S. Department of State).', 'https://educationusa.state.gov', '2026-09-27'),
  ('Nếu tiếng Anh chưa đủ chuẩn nộp trường thì có những giải pháp nào?', 'faq_tu_van', 'draft', 'Nếu trình độ tiếng Anh chưa đạt chuẩn đầu vào, bạn có 2 giải pháp chính thức: (1) Ứng tuyển diện Nhập học có điều kiện (Conditional Admission) hoặc chương trình Pathway/ESL tại trường Mỹ: Bạn sẽ học khóa tiếng Anh chuyên sâu trước khi vào học chính khóa (tuy nhiên chi phí học tiếng tại Mỹ thường khá cao); (2) Lùi kỳ nhập học để tập trung ôn luyện và thi lại chứng chỉ (IELTS/TOEFL/Duolingo) tại Việt Nam nhằm tiết kiệm chi phí và tăng sức cạnh tranh cho hồ sơ visa. (Nguồn kiểm chứng: EducationUSA - Intensive English Programs).', 'https://educationusa.state.gov', '2026-09-27'),
  ('Nguyên tắc viết bài luận cá nhân Personal Statement là gì?', 'faq_tu_van', 'draft', 'Nguyên tắc cốt lõi của bài luận Personal Statement: Đây không phải là bản tóm tắt lại học bạ hay CV. Đại học Mỹ muốn thấy ''giọng nói'' (voice) riêng biệt của bạn: Cách bạn tư duy, góc nhìn đối với các thách thức trong cuộc sống, tính tự nhận thức (self-awareness) và giá trị đạo đức mà bạn theo đuổi. Một câu chuyện đời thường nhưng chân thực, sâu sắc và phản ánh đúng con người thật luôn có sức thuyết phục cao hơn việc liệt kê thành tích hào nhoáng. (Nguồn kiểm chứng: Common App Essay Criteria & Harvard Admissions).', 'https://educationusa.state.gov', '2026-09-27'),
  ('Nếu điểm GPA trung bình không cao thì chiến lược bù đắp hồ sơ là gì?', 'faq_tu_van', 'draft', 'Nếu điểm GPA chưa thực sự nổi bật, bạn có thể áp dụng chiến lược bù đắp đa chiều: (1) Cải thiện điểm thi chuẩn hóa (SAT/ACT) để chứng minh năng lực học thuật tiềm năng; (2) Tận dụng bài luận cá nhân và thư giới thiệu để giải thích bối cảnh, lý do khách quan và làm nổi bật xu hướng điểm tiến bộ qua các kỳ sau; (3) Thể hiện sự nổi bật vượt trội trong hoạt động ngoại khóa, nghiên cứu khoa học hoặc dự án chuyên môn thực tế gắn liền với ngành học đăng ký. (Nguồn kiểm chứng: NACAC Holistic Admissions Guide).', 'https://educationusa.state.gov', '2026-09-27'),
  ('Quy tắc quan trọng về số lượng mẫu I-20 khi đưa ra quyết định xin visa là gì?', 'faq_tu_van', 'draft', 'Theo luật di trú Mỹ (8 CFR 214.2(f)(1)), bạn có thể nhận thư mời và mẫu I-20 từ nhiều trường, nhưng khi đăng ký phỏng vấn visa và nhập cảnh, bạn chỉ được phép chọn duy nhất 1 trường và dùng đúng 1 mẫu I-20 đó. Thông tin trường trên visa F-1, mã số SEVIS ID trên đơn DS-160 và I-20 xuất trình tại cửa khẩu phải hoàn toàn trùng khớp. Tuyệt đối không khai báo hoặc xuất trình nhiều mẫu I-20 cùng lúc vì sẽ gây mâu thuẫn thông tin di trú. (Nguồn kiểm chứng: 8 CFR 214.2(f)(1) & U.S. Immigration and Customs Enforcement - ICE).', 'https://educationusa.state.gov', '2026-09-27'),
  ('Sổ tiết kiệm chứng minh tài chính nộp visa nên mở trước bao lâu để tránh bị nghi ngờ?', 'faq_tu_van', 'draft', 'Quy định của Bộ Ngoại giao Hoa Kỳ không áp đặt kỳ hạn bắt buộc sổ tiết kiệm phải gửi trước bao nhiêu tháng. Yêu cầu pháp lý cốt lõi là chứng minh bạn có sẵn nguồn tài chính hợp pháp đủ chi trả toàn bộ chi phí năm đầu theo mẫu I-20. Mặc dù việc gửi sổ trước từ 3-6 tháng là một kinh nghiệm tốt giúp hồ sơ ổn định hơn, nhưng điều quan trọng nhất vẫn là tính minh bạch: Bạn phải có đầy đủ giấy tờ chứng minh nguồn gốc tích lũy thực tế (thu nhập công việc, kinh doanh, bán tài sản) của số tiền đó. (Nguồn kiểm chứng: travel.state.gov & U.S. Embassy Vietnam FAQs).', 'https://educationusa.state.gov', '2026-09-27'),
  ('Khi điền đơn điện tử DS-160 cần lưu ý điều gì về tính trung thực?', 'faq_tu_van', 'draft', 'Đơn DS-160 là một văn bản pháp lý chính thức có giá trị tuyên thệ. Người nộp đơn phải khai báo trung thực tuyệt đối tất cả các thông tin, đặc biệt là lịch sử từng bị từ chối visa Mỹ/quốc gia khác, hồ sơ bảo lãnh định cư đang chờ hoặc người thân tại Mỹ. Theo luật di trú Hoa Kỳ (INA 212(a)(6)(C)), việc khai man hoặc làm giả giấy tờ sẽ dẫn đến việc bị từ chối visa ngay lập tức và có thể bị áp mức phạt cấm nhập cảnh vĩnh viễn vào Hoa Kỳ. (Nguồn kiểm chứng: INA Section 212(a)(6)(C) & U.S. Department of State Fraud Prevention).', 'https://educationusa.state.gov', '2026-09-27'),
  ('Khoản phí ''Visa Integrity Fee'' 250 USD đã bắt đầu thu đối với visa du học F-1 chưa?', 'faq_tu_van', 'draft', 'Tính đến tháng 10/2026, cơ quan di trú Mỹ vẫn chưa chính thức áp dụng khoản phí ''Visa Integrity Fee'' đối với visa sinh viên F-1. Thí sinh chỉ cần hoàn thành 2 khoản lệ phí bắt buộc theo quy định hiện hành: (1) Phí SEVIS I-901 trị giá $350 nộp cho Bộ An ninh Nội địa Mỹ; (2) Phí xử lý đơn xin thị thực không định cư (MRV fee) trị giá $185 nộp cho Lãnh sự quán Hoa Kỳ. (Nguồn kiểm chứng: travel.state.gov - Fees for Visa Services & 8 CFR 214.13).', 'https://educationusa.state.gov', '2026-09-27'),
  ('Ba trụ cột đánh giá của viên chức Lãnh sự theo điều khoản INA 214(b) là gì?', 'faq_tu_van', 'draft', 'Theo điều khoản 214(b) Đạo luật Di trú Hoa Kỳ (INA), mọi đương đơn xin visa không định cư đều bị mặc định xem là có ý định định cư trừ khi chứng minh thỏa mãn 3 trụ cột: (1) Mục đích học tập chân thật: Bạn có kế hoạch học tập thực chất, hiểu rõ chương trình học và lý do chọn trường; (2) Năng lực tài chính đầy đủ: Gia đình có đủ khả năng chi trả toàn bộ học phí và sinh hoạt phí mà không cần làm việc bất hợp pháp; (3) Ràng buộc tại quê nhà (Ties to home country): Bạn có những mối liên kết chặt chẽ về gia đình, tài sản, cơ hội nghề nghiệp tương lai tại Việt Nam khiến bạn bắt buộc phải quay về sau khi hoàn thành khóa học. (Nguồn kiểm chứng: INA Section 214(b) & U.S. Department of State).', 'https://educationusa.state.gov', '2026-09-27'),
  ('Danh mục giấy tờ bắt buộc phải để trong hành lý xách tay khi bay sang Mỹ?', 'faq_tu_van', 'draft', 'Khi bay sang Mỹ, sinh viên bắt buộc phải mang các giấy tờ sau trong hành lý xách tay (tuyệt đối không gửi vali ký gửi): (1) Hộ chiếu gốc còn hạn ít nhất 6 tháng có dán visa F-1 hợp lệ; (2) Mẫu I-20 bản gốc đã ký tên; (3) Biên lai xác nhận đã thanh toán phí SEVIS I-901; (4) Thư mời nhập học (Letter of Acceptance) và tài liệu chứng minh tài chính; (5) Thông tin liên hệ khẩn cấp của cán bộ phụ trách sinh viên quốc tế (DSO) của trường. (Nguồn kiểm chứng: U.S. Customs and Border Protection - Travel to U.S.).', 'https://educationusa.state.gov', '2026-09-27'),
  ('Nghĩa vụ pháp lý của du học sinh ngay sau khi đặt chân đến trường tại Mỹ là gì?', 'faq_tu_van', 'draft', 'Trong vòng 30 ngày kể từ ngày bắt đầu chương trình ghi trên I-20, du học sinh F-1 có nghĩa vụ pháp lý phải đến trình diện (check-in) với văn phòng sinh viên quốc tế (DSO) của trường và đăng ký đủ số tín chỉ học toàn thời gian (tối thiểu 12 tín chỉ/kỳ đối với bậc đại học). DSO sẽ báo cáo lên cơ sở dữ liệu SEVIS để chuyển trạng thái hồ sơ của bạn sang ''Active''. Nếu không trình diện đúng hạn, hồ sơ SEVIS sẽ bị chuyển sang trạng thái ''Terminated'' do No-Show và bạn sẽ bị mất tư cách lưu trú hợp pháp. (Nguồn kiểm chứng: 8 CFR 214.3(g) & Study in the States - Maintaining Status).', 'https://educationusa.state.gov', '2026-09-27'),
  ('Học sinh lớp 11 muốn sang Mỹ học ngay năm sau thì có những lộ trình khả thi nào?', 'faq_tu_van', 'draft', 'Đối với học sinh học xong lớp 10 hoặc 11 (đủ từ 16 tuổi) muốn sang Mỹ học ngay, có 2 lộ trình: (1) Học tiếp THPT tại một trường tư thục Mỹ để lấy bằng tốt nghiệp High School Diploma rồi ứng tuyển đại học; (2) Tham gia chương trình High School Completion (chương trình kép) tại các trường Cao đẳng cộng đồng (tiêu biểu ở bang Washington): Học sinh vừa tích lũy tín chỉ tốt nghiệp THPT vừa lấy bằng Associate Degree trong khoảng 2 năm, sau đó chuyển tiếp thẳng lên năm thứ 3 đại học 4 năm để lấy bằng cử nhân. (Nguồn kiểm chứng: Washington State Board for Community and Technical Colleges & EducationUSA).', 'https://educationusa.state.gov', '2026-09-28'),
  ('Học sinh không có chứng chỉ SAT thì có thể xét tuyển Đại học và xin học bổng Mỹ không?', 'faq_tu_van', 'draft', 'Hoàn toàn có thể. Hàng trăm trường đại học Mỹ duy trì chính sách Test-Optional: Học sinh không nộp SAT/ACT vẫn được xét tuyển bình thường và đủ điều kiện nhận các gói học bổng năng lực (Merit Scholarship) tự động dựa trên điểm trung bình học bạ (GPA từ 3.0/4.0 trở lên) kết hợp chứng chỉ tiếng Anh (IELTS/Duolingo) và bài luận cá nhân. (Nguồn kiểm chứng: FairTest & EducationUSA).', 'https://educationusa.state.gov', '2026-09-28'),
  ('Bậc Cao đẳng cộng đồng tại Mỹ có nhiều học bổng cho sinh viên quốc tế không?', 'faq_tu_van', 'draft', 'Các trường Cao đẳng cộng đồng (Community College) tại Mỹ rất ít học bổng lớn cho sinh viên quốc tế, nếu có thì thường chỉ là các suất trợ cấp nhập học nhỏ trị giá từ $500 đến $2.000 (cấp một lần). Lý do là mức học phí tại Cao đẳng cộng đồng vốn đã được chính quyền bang trợ giá ở mức rất thấp (khoảng $9.000 - $13.000/năm), chỉ bằng một phần ba so với học phí đại học 4 năm. (Nguồn kiểm chứng: EducationUSA - Community College Financial Aid).', 'https://educationusa.state.gov', '2026-09-28'),
  ('Tiền đặt cọc giữ chỗ (deposit) để trường cấp I-20 có được hoàn lại nếu trượt visa không?', 'faq_tu_van', 'draft', 'Chính sách hoàn tiền đặt cọc giữ chỗ (Enrollment Deposit) do từng trường quy định cụ thể: Đa số các đại học Mỹ đều cho phép hoàn trả toàn bộ hoặc phần lớn tiền đặt cọc học phí nếu sinh viên bị từ chối cấp visa F-1 và gửi kèm bản scan thư từ chối (Form 214b Refusal Letter) trước ngày bắt đầu khóa học. Tuy nhiên, một số khoản phí hành chính (phí xét đơn, phí chuyển phát thư I-20) thường là không hoàn lại. (Nguồn kiểm chứng: National Association for College Admission Counseling - NACAC Guidelines).', 'https://educationusa.state.gov', '2026-09-28'),
  ('Phí SEVIS 350 USD có thời hạn sử dụng trong bao lâu nếu học sinh bị trượt visa hoặc đổi lịch?', 'faq_tu_van', 'draft', 'Theo quy định của Bộ An ninh Nội địa Hoa Kỳ (8 CFR 214.13(g)), khoản phí SEVIS I-901 trị giá $350 có hiệu lực sử dụng trong vòng 12 tháng kể từ ngày nộp. Nếu bạn bị từ chối visa lần đầu và nộp đơn phỏng vấn lại trong vòng 1 năm cho cùng một chương trình học (hoặc chuyển sang I-20 trường khác nhưng cùng mã SEVIS), bạn hoàn toàn không phải đóng lại khoản phí $350 này. (Nguồn kiểm chứng: 8 CFR 214.13 & fmjfee.com Official Guidelines).', 'https://educationusa.state.gov', '2026-09-28'),
  ('Quy định về việc ở ký túc xá đối với sinh viên năm nhất tại các trường đại học Mỹ thế nào?', 'faq_tu_van', 'draft', 'Tại nhiều đại học 4 năm ở Mỹ, nhà trường áp dụng chính sách bắt buộc sinh viên năm nhất phải ở ký túc xá trong khuôn viên trường (First-Year On-Campus Housing Requirement) nhằm hỗ trợ tân sinh viên hòa nhập môi trường và đảm bảo an ninh. Các trường hợp được miễn thường phải đáp ứng điều kiện khắt khe (ví dụ sống cùng bố mẹ trong bán kính gần hoặc trên 21 tuổi). Sinh viên quốc tế cần chủ động nộp đơn đăng ký nhà ở và gói ăn (Meal Plan) sớm ngay khi nhận được I-20. (Nguồn kiểm chứng: Association of College and University Housing Officers - ACUHO-I & University Housing Policies).', 'https://educationusa.state.gov', '2026-09-28'),
  ('Mức phí dịch vụ tư vấn của New World Study Abroad là bao nhiêu và gồm những việc gì?', 'faq_tu_van', 'draft', 'Hệ thống AI là nền tảng hỗ trợ ra quyết định du học độc lập, cung cấp thông tin tra cứu học thuật, học phí và hướng dẫn quy trình visa hoàn toàn miễn phí. AI không kinh doanh dịch vụ tư vấn, không thu phí dịch vụ và không đại diện bán gói làm hồ sơ cho bất kỳ công ty du học thương mại nào. Nếu người dùng cần dịch vụ hỗ trợ nộp hồ sơ, sửa luận trực tiếp 1-1 hoặc luyện phỏng vấn thực tế từ bên ngoài, hệ thống sẽ gợi ý danh sách các đơn vị uy tín có giấy phép để người dùng tự do tham khảo và so sánh. (Nguồn kiểm chứng: USAS System Core Policy & Bộ Giáo dục và Đào tạo).', 'https://educationusa.state.gov', '2026-09-28'),
  ('Hồ sơ học thuật cơ bản để nộp xét tuyển đại học Mỹ gồm những giấy tờ gì?', 'faq_tu_van', 'draft', 'Một bộ hồ sơ học thuật chuẩn nộp vào đại học Mỹ bao gồm: (1) Bảng điểm/Học bạ chính thức 3 năm gần nhất kèm bản dịch thuật tiếng Anh có công chứng; (2) Chứng chỉ năng lực tiếng Anh hợp lệ (IELTS, TOEFL iBT hoặc Duolingo); (3) Điểm thi chuẩn hóa SAT/ACT (nếu trường yêu cầu); (4) Bài luận cá nhân (Personal Statement) và bài luận phụ; (5) Từ 1 đến 2 thư giới thiệu của giáo viên; (6) Bản sao hộ chiếu còn hạn và hồ sơ chứng nhận hoạt động/thành tích ngoại khóa. (Nguồn kiểm chứng: EducationUSA - Complete Your Application).', 'https://educationusa.state.gov', '2026-09-28'),
  ('Muốn xin học bổng đại học Mỹ thì mức điểm IELTS 6.0 đã đủ sức cạnh tranh chưa?', 'faq_tu_van', 'draft', 'Điểm IELTS 6.0 đáp ứng đủ chuẩn nhập học tối thiểu của nhiều đại học Mỹ, nhưng ở khía cạnh cạnh tranh học bổng thì chưa phải là mức điểm nổi bật. Các suất học bổng thành tích (Merit Scholarship) thường ưu tiên hồ sơ có tiếng Anh từ IELTS 6.5 đến 7.5+ kết hợp với điểm GPA từ 8.5/10 và các bài luận xuất sắc. Nếu có đủ thời gian, bạn nên ôn luyện thêm để nâng band điểm lên tối thiểu 6.5. (Nguồn kiểm chứng: EducationUSA Scholarships Analysis).', 'https://educationusa.state.gov', '2026-09-28'),
  ('Trung tâm PEC có ưu tiên trường liên kết hay làm được cả trường ngoài danh sách?', 'faq_tu_van', 'draft', 'Hệ thống AI Decision Support hoạt động dựa trên nguyên tắc trung lập và khách quan tuyệt đối: Không nhận hoa hồng tuyển sinh và không ưu tiên bất kỳ mạng lưới trường liên kết nào. Thuật toán gợi ý trường của AI phân tích toàn diện trên hơn 4.000 trường đại học tại Mỹ dựa trên đúng 3 tiêu chí cốt lõi của người dùng: Sự phù hợp ngành học, khả năng chi trả tài chính và năng lực học tập thực tế. (Nguồn kiểm chứng: USAS Core Principles & EducationUSA Unbiased Advising Standards).', 'https://educationusa.state.gov', '2026-09-28'),
  ('Kết quả phỏng vấn visa du học Mỹ được thông báo khi nào và bằng cách nào?', 'faq_tu_van', 'draft', 'Kết quả phỏng vấn visa du học Mỹ được thông báo trực tiếp ngay tại quầy khi buổi đối thoại kết thúc: (1) Nếu được chấp thuận: Viên chức lãnh sự sẽ giữ lại hộ chiếu của bạn để in dán visa và gửi về địa chỉ bạn đăng ký qua đường bưu điện trong vòng 2 đến 5 ngày làm việc; (2) Nếu bị từ chối: Viên chức sẽ trả lại hộ chiếu ngay lập tức kèm theo một văn bản giải thích lý do từ chối (phổ biến nhất là Thư từ chối theo điều khoản 214(b) hoặc phiếu yêu cầu bổ sung thông tin hành chính 221(g)). (Nguồn kiểm chứng: travel.state.gov & U.S. Embassy and Consulate in Vietnam).', 'https://educationusa.state.gov', '2026-09-28'),
  ('Chi phí dịch vụ làm hồ sơ tại PEC là bao nhiêu và có chính sách hoàn tiền không?', 'faq_tu_van', 'draft', 'Mức phí dịch vụ của các trung tâm tư vấn du học bên ngoài là thỏa thuận thương mại dân sự riêng giữa khách hàng và doanh nghiệp. Khi làm việc với bất kỳ trung tâm tư vấn nào, người học cần lưu ý: (1) Hợp đồng phải ghi rõ chi tiết từng hạng mục công việc (nộp mấy trường, có sửa luận không, hỗ trợ bao nhiêu buổi phỏng vấn); (2) Đọc kỹ điều khoản hoàn tiền (refund policy) nếu không đậu visa; (3) Lưu ý rằng các khoản phí nộp cho chính phủ Mỹ (phí SEVIS $350, phí visa $185) và phí nộp đơn cho trường đại học là hoàn toàn không thể hoàn lại. (Nguồn kiểm chứng: Cục Quản lý Cạnh tranh & Bảo vệ Người tiêu dùng).', 'https://educationusa.state.gov', '2026-09-28'),
  ('Học sinh lớp 12 có GPA 8.0 và IELTS 6.0 nên chọn nộp thẳng Đại học hay đi Cao đẳng?', 'faq_tu_van', 'draft', 'Với học lực GPA 8.0/10 và IELTS 6.0, bạn hoàn toàn đủ điều kiện nộp thẳng vào nhiều trường đại học 4 năm xếp hạng tầm trung tại Mỹ, đồng thời cũng hoàn toàn đủ điều kiện học chương trình Cao đẳng cộng đồng chuyển tiếp 2+2. Việc chọn hướng đi nào phụ thuộc vào ưu tiên của bạn: Nếu gia đình có ngân sách đảm bảo (trên $35.000/năm), học thẳng 4 năm giúp ổn định môi trường học tập; nếu ưu tiên tiết kiệm 40-50% chi phí trong 2 năm đầu, lộ trình 2+2 là giải pháp rất kinh tế. Viên chức lãnh sự xét visa dựa trên tính hợp lý của kế hoạch học tập cá nhân, không có quy định ưu tiên ĐH 4 năm hơn Cao đẳng cộng đồng. (Nguồn kiểm chứng: 9 FAM 402.5 & EducationUSA).', 'https://educationusa.state.gov', '2026-09-29'),
  ('Học sinh đang học lớp 12 thì nộp học bạ những năm nào để kịp kỳ nhập học Mùa Thu năm sau?', 'faq_tu_van', 'draft', 'Học sinh đang học lớp 12 không cần đợi học xong mới nộp đơn mà sẽ sử dụng bảng điểm chính thức của lớp 10, lớp 11 và điểm học kỳ 1 lớp 12 (kèm chứng chỉ tiếng Anh) để nộp hồ sơ ngay trong mùa tuyển sinh mùa thu (từ tháng 10 đến tháng 1). Các trường đại học Mỹ sẽ xét tuyển và cấp Thư chấp nhận có điều kiện (Conditional Admission); bạn chỉ cần bổ sung bảng điểm tốt nghiệp lớp 12 hoàn chỉnh vào mùa hè trước khi chính thức nhập học. (Nguồn kiểm chứng: Common App Admissions Calendar & NACAC).', 'https://educationusa.state.gov', '2026-09-29'),
  ('Mức GPA và IELTS bao nhiêu được coi là điểm chuẩn đầu vào cho học bổng tại Mission Edu?', 'faq_tu_van', 'draft', 'Không có một ngưỡng điểm chuẩn học bổng thống nhất áp dụng cho toàn bộ các trường đại học Mỹ. Mức GPA 8.5/10 và IELTS 6.5+ là khung điểm tham khảo tốt, giúp hồ sơ của bạn lọt vào nhóm cạnh tranh học bổng tự động tại nhiều đại học công lập. Tuy nhiên, giá trị học bổng nhận được còn phụ thuộc vào ngân sách cấp học bổng của trường, bài luận cá nhân, điểm thi chuẩn hóa SAT (nếu có) và việc bạn có nộp đơn trước ngày Priority Deadline của trường hay không. (Nguồn kiểm chứng: EducationUSA - Financing Undergraduate Studies).', 'https://educationusa.state.gov', '2026-09-29'),
  ('Số dư sổ tiết kiệm chứng minh tài chính du học Mỹ được Mission Edu khuyến nghị là bao nhiêu?', 'faq_tu_van', 'draft', 'Luật di trú Mỹ (8 CFR 214.2(f)) không quy định con số tiền mặt cố định 1,5 tỷ hay 2 tỷ đồng. Số tiền tối thiểu bắt buộc bạn phải chứng minh chính bằng đúng con số ''Total Estimated Expenses for First Year'' được in trên mẫu I-20 của ngôi trường bạn theo học (đã bao gồm học phí, bảo hiểm và chi phí sinh hoạt). Nếu chi phí trên I-20 là $35.000 thì số dư sổ tiết kiệm cần tối thiểu từ 850 - 900 triệu VNĐ; nếu trường có chi phí $60.000 thì cần từ 1,5 tỷ VNĐ trở lên. Quan trọng nhất là nguồn gốc số tiền phải rõ ràng và có giấy tờ thu nhập hợp pháp đối ứng. (Nguồn kiểm chứng: 8 CFR 214.2(f) & U.S. Embassy Vietnam FAQs).', 'https://educationusa.state.gov', '2026-09-29'),
  ('Chi phí dịch vụ làm hồ sơ tại Mission Edu dao động trong khoảng nào?', 'faq_tu_van', 'draft', 'Biểu phí từ $800 đến $2.000 là mức giá tham khảo riêng của trung tâm tư vấn Mission Edu cho dịch vụ làm hồ sơ và ủy thác nộp đơn. Hệ thống AI Decision Support cung cấp kiến thức và phân tích trường hoàn toàn miễn phí. Đối với các phụ huynh và học sinh muốn thuê dịch vụ bên ngoài, cần yêu cầu trung tâm cung cấp hợp đồng rõ ràng, liệt kê chi tiết các khoản chi phí không hoàn lại và cam kết bảo mật thông tin cá nhân. (Nguồn kiểm chứng: USAS Core Guidelines).', 'https://educationusa.state.gov', '2026-09-29'),
  ('Sinh viên CNTT / Kỹ thuật phần mềm (CS/SE) chuyển sang học Thạc sĩ AI có cần học bổ trợ không?', 'faq_tu_van', 'draft', 'Sinh viên tốt nghiệp bằng Cử nhân ngành Kỹ thuật phần mềm (SE) hoặc Khoa học máy tính (CS) khi ứng tuyển Thạc sĩ Trí tuệ nhân tạo (AI/Machine Learning) tại Mỹ thường không phải học các môn tiên quyết (Bridge/Prerequisites), vì hai ngành này cùng chung khối kiến thức nền tảng về Toán giải tích, Đại số tuyến tính, Cấu trúc dữ liệu và Lập trình. Các môn học bù chỉ bắt buộc đối với ứng viên chuyển ngành từ khối Kinh tế, Kinh doanh hoặc Khoa học xã hội sang khối kỹ thuật. (Nguồn kiểm chứng: ACM/IEEE Computer Science Curricula & Graduate Admissions Guidelines).', 'https://educationusa.state.gov', '2026-09-29'),
  ('Kỳ nhập học tháng 9 (Fall) và tháng 2 (Spring) ở bậc Thạc sĩ khác biệt thế nào về thời gian chuẩn bị?', 'faq_tu_van', 'draft', 'Sự khác biệt giữa 2 kỳ nhập học bậc Thạc sĩ tại Mỹ: (1) Kỳ Mùa Thu (Fall - tháng 8/9): Là kỳ nhập học chính, mở tất cả các chuyên ngành và có nhiều cơ hội xét trợ cấp tài chính (Trợ giảng - TA, Trợ lý nghiên cứu - RA). Hạn chót nộp đơn thường từ tháng 12 đến tháng 2, yêu cầu phải hoàn thành bài thi GRE và IELTS/TOEFL trước tháng 12; (2) Kỳ Mùa Xuân (Spring - tháng 1): Chỉ tiêu tuyển sinh ít hơn, hạn nộp hồ sơ từ tháng 8 đến tháng 10. Nếu chưa kịp thi chứng chỉ chuẩn hóa trước tháng 12, việc dời sang kỳ Spring là chiến lược hợp lý để hoàn thiện hồ sơ chất lượng hơn. (Nguồn kiểm chứng: EducationUSA - Graduate Studies Timeline).', 'https://educationusa.state.gov', '2026-09-29'),
  ('Tiêu chí chọn trường cho bậc Thạc sĩ nên ưu tiên yếu tố nào đầu tiên?', 'faq_tu_van', 'draft', 'Khi chọn trường bậc Thạc sĩ tại Mỹ, thứ tự ưu tiên hợp lý là: (1) Ngân sách tài chính thực tế: Xác định mức học phí và chi phí sinh hoạt có nằm trong khả năng chi trả của bản thân/gia đình hay không; (2) Sự phù hợp về chuyên môn học thuật: Đội ngũ giáo sư, các phòng thí nghiệm (Labs), cơ hội tham gia các dự án nghiên cứu có tài trợ (Funded Projects); (3) Cơ hội nghề nghiệp: Vị trí địa lý của trường có gần các trung tâm công nghệ, mạng lưới cựu sinh viên và chính sách hỗ trợ thực tập CPT/OPT của trường. Không nên chỉ nhìn vào thứ hạng chung (overall ranking) nếu mức học phí vượt quá năng lực tài chính. (Nguồn kiểm chứng: EducationUSA - Researching Graduate Options).', 'https://educationusa.state.gov', '2026-09-29'),
  ('Bố mẹ làm nghề tự do thì chứng minh tài chính bậc Thạc sĩ như thế nào cho đơn giản và thuyết phục?', 'faq_tu_van', 'draft', 'Khi người bảo trợ tài chính làm nghề tự do (kinh doanh cá thể, đầu tư, tự doanh), hồ sơ chứng minh tài chính visa F-1 cần thực hiện theo các bước: (1) Sổ tiết kiệm đứng tên người bảo trợ hoặc chính ứng viên với số dư đủ chi trả cho năm học đầu tiên theo mẫu I-20; (2) Bản giải trình nguồn gốc thu nhập (Financial Explanation Letter) trình bày chi tiết các nguồn thu nhập ổn định hàng tháng kèm tài liệu minh chứng (sao kê tài khoản ngân hàng thể hiện giao dịch dòng tiền thường xuyên, giấy đăng ký kinh doanh, hợp đồng cho thuê nhà, giấy tờ quyền sử dụng đất hoặc đăng ký ô tô). Tính chân thực và nhất quán của dòng tiền là yếu tố thuyết phục nhất đối với viên chức lãnh sự. (Nguồn kiểm chứng: 9 FAM 402.5 & U.S. Embassy Vietnam FAQs).', 'https://educationusa.state.gov', '2026-09-29'),
  ('Điểm khác biệt quan trọng của CV học thuật (Academic CV) nộp Thạc sĩ Mỹ là gì?', 'faq_tu_van', 'draft', 'Điểm khác biệt cốt lõi của CV học thuật (Academic CV) nộp Thạc sĩ Mỹ: Thay vì chỉ liệt kê kỹ năng hoặc kinh nghiệm công việc thông thường, CV sau đại học phải làm nổi bật: (1) Các dự án kỹ thuật (Technical Projects) và nghiên cứu khoa học: Nêu rõ bài toán cần giải quyết, công nghệ/công cụ sử dụng, phương pháp tiếp cận và kết quả định lượng đạt được; (2) Kinh nghiệm nghiên cứu thực tế (Research Experience) tại các lab trường đại học; (3) Các bài báo khoa học, giải thưởng học thuật hoặc các dự án mã nguồn mở đã đóng góp. (Nguồn kiểm chứng: MIT Career Design Center & Stanford Graduate Admissions Resume Guide).', 'https://educationusa.state.gov', '2026-09-29'),
  ('Quy định làm thêm on-campus, thực tập CPT và làm việc sau tốt nghiệp OPT cho du học sinh Thạc sĩ STEM?', 'faq_tu_van', 'draft', 'Quy định pháp lý về việc làm cho du học sinh F-1 bậc Thạc sĩ: (1) Làm việc trong trường (On-campus): Được phép làm việc tối đa 20 giờ/tuần trong thời gian học và tối đa 40 giờ/tuần trong các kỳ nghỉ (theo 8 CFR 214.2(f)(9)); (2) Thực tập ngoại khóa (CPT): Phải học toàn thời gian ít nhất 1 năm học đầy đủ (2 học kỳ) mới đủ điều kiện tham gia thực tập đúng chuyên ngành ngoài trường; (3) Thực tập sau tốt nghiệp (OPT): Được làm việc 12 tháng tại Mỹ; nếu tốt nghiệp bằng Thạc sĩ thuộc danh mục nhóm ngành STEM do DHS chỉ định, sinh viên được nộp đơn xin gia hạn thêm 24 tháng (tổng thời gian làm việc hợp pháp là 36 tháng hay 3 năm). (Nguồn kiểm chứng: 8 CFR 214.2(f)(10)-(11) & U.S. Citizenship and Immigration Services - USCIS).', 'https://educationusa.state.gov', '2026-09-29'),
  ('Ngân sách $30.000 - $40.000/năm có đủ để học Thạc sĩ Khoa học máy tính tại Mỹ không?', 'faq_tu_van', 'draft', 'Mức ngân sách từ $30.000 đến $40.000/năm là hoàn toàn khả thi đối với chương trình Thạc sĩ Khoa học máy tính tại nhiều trường đại học công lập tại Mỹ (đặc biệt là ở các bang khu vực Midwest hoặc South có mức sinh hoạt phí phải chăng như Texas, Ohio, Utah, Missouri). Với mức ngân sách này, học phí khoảng $18.000 - $24.000/năm và chi phí ăn ở, bảo hiểm khoảng $12.000 - $16.000/năm. Ngoài ra, sinh viên có thể tìm kiếm các vị trí trợ giảng (TA), trợ lý nghiên cứu (RA) sau học kỳ đầu tiên để được miễn giảm một phần học phí. (Nguồn kiểm chứng: EducationUSA Graduate Finance & NCES College Navigator).', 'https://educationusa.state.gov', '2026-09-29'),
  ('Số lượng trường Thạc sĩ nên nộp cùng lúc là bao nhiêu để đảm bảo an toàn?', 'faq_tu_van', 'draft', 'Chiến lược nộp hồ sơ Thạc sĩ chuẩn mực của EducationUSA khuyến nghị nộp từ 5 đến 8 trường, được phân bổ theo mô hình kim tự tháp an toàn: (1) Nhóm Trường Vươn tới (Reach Schools - 2 trường): Các trường có thứ hạng cao hơn năng lực hiện tại, tỷ lệ cạnh tranh cao; (2) Nhóm Trường Vừa sức (Target Schools - 3 đến 4 trường): Các trường có tiêu chí tuyển sinh và điểm trung bình GPA/GRE hoàn toàn tương thích với hồ sơ của bạn; (3) Nhóm Trường An toàn (Safety Schools - 1 đến 2 trường): Các trường bạn tự tin chắc chắn đáp ứng vượt chuẩn để đảm bảo luôn có thư mời nhập học. (Nguồn kiểm chứng: EducationUSA - Define Your Priorities).', 'https://educationusa.state.gov', '2026-09-29'),
  ('Điểm GPA đại học 8.0/10 tại Việt Nam quy đổi sang hệ 4 của Mỹ tương đương bao nhiêu?', 'faq_tu_van', 'draft', 'Khi quy đổi điểm đại học từ thang điểm 10 của Việt Nam sang thang điểm 4.0 của Mỹ, điểm 8.0/10 thường được các tổ chức thẩm định học thuật quốc tế (như WES - World Education Services hoặc ECE) quy đổi tương đương trong khoảng 3.0 đến 3.3/4.0 (loại Khá - tương ứng điểm B/B+). Mức điểm này đáp ứng yêu cầu đầu vào của đa số các chương trình Thạc sĩ tại Mỹ (thường yêu cầu minimum GPA từ 3.0/4.0). Trừ khi trường có yêu cầu bắt buộc nộp chứng thư thẩm định WES/ECE, sinh viên nên giữ nguyên bảng điểm gốc kèm thang điểm chuẩn của trường đại học Việt Nam. (Nguồn kiểm chứng: WES Grade Conversion Guide & EducationUSA FAQs).', 'https://educationusa.state.gov', '2026-09-29'),
  ('Đề nghị đứng tên chung bài báo nghiên cứu khoa học của tư vấn viên để xin học bổng có được chấp nhận?', 'faq_tu_van', 'draft', 'Hành vi đứng tên chung trên các bài báo khoa học mà bản thân không trực tiếp tham gia nghiên cứu là vi phạm nghiêm trọng quy chuẩn liêm chính học thuật (Academic Integrity) của hệ thống giáo dục Hoa Kỳ. Các hội đồng tuyển sinh sau đại học tại Mỹ thẩm tra rất kỹ năng lực nghiên cứu qua bài luận mục đích (SOP), thư giới thiệu và các buổi phỏng vấn chuyên môn. Nếu bị phát hiện có hành vi gian lận học thuật, ứng viên sẽ bị từ chối hồ sơ ngay lập tức, hủy kết quả học bổng hoặc bị cấm nhập học vĩnh viễn. Thay vì mua bán danh nghĩa bài báo, bạn nên tập trung thể hiện các dự án thực tế, kỹ năng chuyên môn tự phát triển và kinh nghiệm làm việc thực chất của mình. (Nguồn kiểm chứng: U.S. Office of Research Integrity - ORI & University Academic Conduct Codes).', 'https://educationusa.state.gov', '2026-09-29'),
  ('Nếu muốn học bằng MBA sau khi tốt nghiệp ngành kỹ thuật thì lộ trình nào thuận lợi cho visa?', 'faq_tu_van', 'draft', 'Nếu bạn mới tốt nghiệp ngành kỹ thuật và chưa có nhiều năm kinh nghiệm làm việc thực tế, việc nộp thẳng vào chương trình MBA tại Mỹ có thể gặp bất lợi vì các trường MBA uy tín yêu cầu tối thiểu 2 đến 5 năm kinh nghiệm quản lý, đồng thời khi phỏng vấn visa viên chức có thể nghi ngờ về sự chuyển hướng đột ngột. Lộ trình tối ưu hơn là: (1) Nộp Thạc sĩ Khoa học (MS in Computer Science/Data Analytics) trước để đảm bảo tính nhất quán học thuật và tận dụng chính sách 3 năm STEM OPT để đi làm; (2) Sau 2-3 năm đi làm có kinh nghiệm thực tế, bạn có thể học tiếp bằng MBA để chuyển tiếp lên vị trí quản lý. (Nguồn kiểm chứng: Graduate Management Admission Council - GMAC & 9 FAM 402.5).', 'https://educationusa.state.gov', '2026-09-29'),
  ('Điểm GPA cấp 3 cạnh tranh để nộp vào ngành Khoa học máy tính tại các trường Đại học Top Mỹ là bao nhiêu?', 'faq_tu_van', 'draft', 'Ngành Khoa học máy tính (Computer Science) tại các trường Đại học Top 30 - 50 của Mỹ là một trong những ngành có tỷ lệ cạnh tranh cao nhất. Để hồ sơ có sức cạnh tranh học thuật mạnh, mức GPA trung bình cấp 3 thường cần đạt từ 3.8/4.0 trở lên (tương đương khoảng 9.0+/10 tại Việt Nam) kết hợp với điểm SAT từ 1450 - 1550+. Nếu GPA của bạn đang ở mức 8.2 - 8.5/10, bạn vẫn có thể nộp vào nhóm trường Top 50 - 100 hoặc cải thiện cơ hội bằng các dự án lập trình thực tế, giải thưởng tin học và bài luận chuyên sâu về đam mê công nghệ. (Nguồn kiểm chứng: U.S. News Best Undergraduate Computer Science Programs & EducationUSA).', 'https://educationusa.state.gov', '2026-09-29'),
  ('Sự khác biệt cốt lõi giữa các vòng nộp hồ sơ ED1, EA và Regular Decision tại đại học Mỹ là gì?', 'faq_tu_van', 'draft', 'Sự khác biệt giữa các vòng nộp đơn đại học Mỹ: (1) Early Decision (ED): Là cam kết ràng buộc pháp lý (Binding). Bạn chỉ được nộp duy nhất 1 trường theo diện ED. Nếu trường chấp nhận, bạn bắt buộc phải nhập học và phải rút đơn ở tất cả các trường khác; (2) Early Action (EA): Nộp sớm, nhận kết quả sớm (thường vào tháng 12) nhưng không có tính ràng buộc; bạn có quyền so sánh học bổng và quyết định nhập học đến ngày 01/05; (3) Regular Decision (RD): Vòng nộp đơn tiêu chuẩn (hạn nộp vào tháng 1-2, kết quả vào tháng 3-4), không có tính ràng buộc. (Nguồn kiểm chứng: Common App Early Decision & Early Action Regulations).', 'https://educationusa.state.gov', '2026-09-29'),
  ('Hạn chót (Deadline) của vòng nộp sớm (Early) và vòng nộp thông thường (Regular) thường rơi vào ngày nào?', 'faq_tu_van', 'draft', 'Lịch trình các đợt nộp đơn đại học Mỹ tiêu chuẩn: (1) Vòng sớm Early Decision 1 / Early Action (ED1/EA): Hạn chót phổ biến nhất là ngày 01/11 hoặc 15/11 hàng năm, công bố kết quả vào giữa tháng 12; (2) Vòng sớm đợt 2 Early Decision 2 (ED2): Thường chốt hồ sơ vào ngày 01/01 hoặc 15/01 (dành cho thí sinh trượt vòng ED1 muốn nộp ràng buộc vào một trường khác); (3) Vòng tiêu chuẩn Regular Decision (RD): Hạn chót từ ngày 01/01 đến 01/02, công bố kết quả vào cuối tháng 3. (Nguồn kiểm chứng: Common App Timelines & College Board).', 'https://educationusa.state.gov', '2026-09-29'),
  ('Tiêu chí xây dựng bộ hoạt động ngoại khóa cạnh tranh cho hồ sơ du học Mỹ gồm những gì?', 'faq_tu_van', 'draft', 'Để bộ hoạt động ngoại khóa có tính cạnh tranh cao trong hồ sơ du học Mỹ, bạn nên xây dựng theo mô hình chữ T (T-shaped): (1) Chiều ngang: Nền tảng tham gia các hoạt động cộng đồng, tình nguyện, câu lạc bộ văn hóa thể thao thể hiện sự hòa đồng và trách nhiệm xã hội; (2) Chiều dọc (mũi nhọn): Tập trung chuyên sâu vào các hoạt động gắn liền trực tiếp với chuyên ngành dự kiến theo học (ví dụ nghiên cứu, dự án mã nguồn mở, câu lạc bộ lập trình nếu học CS), thể hiện vai trò người khởi xướng (Founder/Leader) và các số liệu tác động thực tế có thể đo lường được. (Nguồn kiểm chứng: NACAC Guide to Holistic College Admissions).', 'https://educationusa.state.gov', '2026-09-29'),
  ('Phí dịch vụ gói tư vấn toàn diện của Summit Education là bao nhiêu?', 'faq_tu_van', 'draft', 'Mức phí $24.000 cho gói hồ sơ 8 trường là biểu phí thương mại riêng của đơn vị tư vấn Summit Education dành cho học sinh mục tiêu trường top có lộ trình cố vấn chuyên sâu 1-1. Hệ thống AI Decision Support hoạt động độc lập nhằm cung cấp công cụ phân tích dữ liệu, gợi ý danh sách trường học và quy trình visa miễn phí cho cộng đồng. Người dùng có toàn quyền lựa chọn tự hoàn thiện hồ sơ (tự apply) hoặc tìm kiếm sự trợ giúp từ các trung tâm tư vấn chuyên nghiệp tùy thuộc vào điều kiện tài chính của gia đình. (Nguồn kiểm chứng: USAS System Core Policy).', 'https://educationusa.state.gov', '2026-09-29'),
  ('Trung tâm tư vấn có được phép cam kết chắc chắn 100% đậu visa du học Mỹ trong hợp đồng không?', 'faq_tu_van', 'draft', 'Tuyệt đối không có bất kỳ tổ chức hay trung tâm tư vấn nào được phép cam kết 100% đậu visa du học Mỹ. Theo luật Di trú và Quốc tịch Hoa Kỳ (INA), thẩm quyền quyết định cấp hoặc từ chối thị thực thuộc về duy nhất Viên chức Lãnh sự tại thời điểm phỏng vấn. Các trung tâm tư vấn uy tín chỉ cam kết hỗ trợ tối đa về mặt chuẩn bị hồ sơ học thuật, hướng dẫn giải trình tài chính và luyện kỹ năng trả lời phỏng vấn. Đại sứ quán Hoa Kỳ luôn khuyến cáo người dân cảnh giác với các lời hứa bao đỗ visa hoặc các hành vi làm giả giấy tờ. (Nguồn kiểm chứng: U.S. Embassy Vietnam - Visa Fraud Warning & INA Section 104).', 'https://educationusa.state.gov', '2026-09-29'),
  ('Tiêu chí chọn trường Thạc sĩ tại Mỹ nên dựa trên yếu tố nào theo tư vấn của New Ocean?', 'faq_tu_van', 'draft', 'Khi lựa chọn trường Thạc sĩ tại Mỹ, người học nên cân nhắc dựa trên bài toán tài chính thực tế và mục tiêu đầu ra nghề nghiệp: Tổng chi phí học tập và sinh hoạt phải nằm trong khả năng đảm bảo của gia đình suốt toàn bộ thời gian học (thường từ 1.5 đến 2 năm), tránh trường hợp chọn trường danh tiếng học phí quá cao dẫn tới đứt gánh tài chính giữa chừng. Ngoài ra, cần đánh giá cơ hội việc làm tại địa phương nơi trường tọa lạc và chính sách tuyển dụng sinh viên sau tốt nghiệp. (Nguồn kiểm chứng: EducationUSA - Choosing the Right Master''s Program).', 'https://educationusa.state.gov', '2026-09-29'),
  ('Bài thi chuẩn hóa nào thường được yêu cầu đối với các chương trình Thạc sĩ tại Mỹ?', 'faq_tu_van', 'draft', 'Bên cạnh bảng điểm đại học và chứng chỉ tiếng Anh (IELTS/TOEFL/Duolingo), các chương trình sau đại học tại Mỹ thường yêu cầu một trong hai bài thi chuẩn hóa: (1) GRE (Graduate Record Examinations): Phổ biến cho các ngành Khoa học tự nhiên, Kỹ thuật, Công nghệ thông tin và Khoa học xã hội; (2) GMAT (Graduate Management Admission Test): Chuyên dùng cho các trường kinh doanh và chương trình Thạc sĩ Quản trị kinh doanh (MBA). Tuy nhiên, hiện nay nhiều khoa sau đại học đã áp dụng chính sách miễn thi GRE/GMAT (Waiver) đối với ứng viên có GPA đại học xuất sắc hoặc có kinh nghiệm làm việc chuyên môn nhiều năm. (Nguồn kiểm chứng: ETS GRE Guidelines & GMAC GMAT Testing Policies).', 'https://educationusa.state.gov', '2026-09-29'),
  ('Khi chuẩn bị hồ sơ visa F-1 thì phần giải trình thu nhập của bố mẹ cần trình bày những gì?', 'faq_tu_van', 'draft', 'Khi giải trình thu nhập của người bảo trợ (bố mẹ) trong hồ sơ visa du học Mỹ, bạn cần chứng minh được nguồn thu nhập ổn định hàng tháng và nguồn gốc hình thành số dư tài sản: (1) Nếu là cán bộ/công nhân viên: Nộp Hợp đồng lao động, Quyết định bổ nhiệm, Sao kê tài khoản nhận lương 6 tháng gần nhất và Bảo hiểm xã hội; (2) Nếu là chủ doanh nghiệp/hộ kinh doanh: Nộp Giấy chứng nhận đăng ký kinh doanh, Biên lai nộp thuế môn bài/thuế thu nhập doanh nghiệp 6 tháng gần nhất; (3) Nguồn thu từ cho thuê tài sản: Nộp Hợp đồng thuê nhà/đất và sổ đỏ đối ứng. Hồ sơ phải thể hiện gia đình có tích lũy thặng dư ổn định sau khi trừ đi chi phí sinh hoạt tại Việt Nam. (Nguồn kiểm chứng: U.S. Embassy Vietnam - Nonimmigrant Visa Financial Documentation).', 'https://educationusa.state.gov', '2026-09-29'),
  ('Khi luyện phỏng vấn visa du học Mỹ, người nộp đơn cần chuẩn bị những khía cạnh nào?', 'faq_tu_van', 'draft', 'Khi chuẩn bị cho buổi phỏng vấn visa F-1, ứng viên cần rèn luyện toàn diện cả về nội dung và tác phong: (1) Tác phong: Ăn mặc lịch sự, chỉn chu, giữ thái độ bình tĩnh, tự tin và duy trì giao tiếp bằng mắt (eye contact) với viên chức qua ô kính; (2) Kỹ năng trả lời: Trả lời thẳng thắn, trực diện vào câu hỏi trong 1-2 câu đầu tiên, nói rõ ràng, không vòng vo hay học thuộc lòng; (3) Nắm vững hồ sơ: Hiểu rõ từng chi tiết trên đơn DS-160, mẫu I-20, kế hoạch học tập và năng lực tài chính của gia đình để khi được hỏi có thể xuất trình giấy tờ ngay lập tức mà không lúng túng. (Nguồn kiểm chứng: EducationUSA - Visa Interview Preparation Tips).', 'https://educationusa.state.gov', '2026-09-29'),
  ('Phụ huynh muốn sang Mỹ thăm con đang du học thì có được hỗ trợ làm visa không?', 'faq_tu_van', 'draft', 'Phụ huynh có con đang du học tại Mỹ hoàn toàn có thể nộp đơn xin thị thực du lịch/thăm thân diện B-1/B-2 để sang thăm con hoặc tham dự lễ tốt nghiệp. Hồ sơ cần chuẩn bị gồm: (1) Phía học sinh tại Mỹ: Bản sao visa F-1, mẫu I-20 hợp lệ, bảng điểm gần nhất và Giấy xác nhận tình trạng sinh viên (Enrollment Verification) do trường cấp kèm thư mời của trường; (2) Phía phụ huynh tại Việt Nam: Điền đơn DS-160, đóng phí phỏng vấn $185 và chuẩn bị đầy đủ hồ sơ chứng minh công việc ổn định, tài sản sở hữu và các ràng buộc gia đình vững chắc tại Việt Nam để khẳng định sẽ quay về sau chuyến thăm. (Nguồn kiểm chứng: travel.state.gov - Visitor Visa B1/B2).', 'https://educationusa.state.gov', '2026-09-29'),
  ('Điều kiện đầu vào học thuật và tiếng Anh cơ bản để du học THPT tại Mỹ là gì?', 'faq_tu_van', 'draft', 'Điều kiện đầu vào thông thường để du học bậc THPT tại Mỹ: (1) Học thuật: Điểm trung bình GPA 2 năm gần nhất từ 6.5 - 7.0/10 trở lên; (2) Trình độ tiếng Anh: Đạt điểm bài thi tiếng Anh dành cho học sinh phổ thông như ELTiS (từ 215 đến 225 điểm), TOEFL Junior, Duolingo hoặc bài thi đánh giá nội bộ của trường; (3) Phỏng vấn trường: Học sinh tham gia một buổi phỏng vấn trực tuyến ngắn (15-20 phút) qua Zoom với đại diện tuyển sinh của trường để kiểm tra khả năng phản xạ giao tiếp và sự tự lập; (4) Hồ sơ tài chính gia đình đảm bảo chi trả học phí và sinh hoạt phí. (Nguồn kiểm chứng: The Association of Boarding Schools - TABS & CSIET Standards).', 'https://educationusa.state.gov', '2026-10-08'),
  ('Quy định về việc du học sinh diện visa F-1 học tại trường THPT công lập ở Mỹ (Public High School)?', 'faq_tu_van', 'draft', 'Theo điều luật 214(m) Đạo luật Di trú và Quốc tịch Hoa Kỳ (8 U.S.C. 1184(m)), học sinh quốc tế diện visa F-1 học tại các trường THPT công lập (lớp 9 đến 12) chịu các ràng buộc pháp lý bắt buộc: (1) Thời gian theo học tối đa không được vượt quá 12 tháng (1 năm học) cộng dồn trên toàn nước Mỹ; (2) Phải chi trả toàn bộ chi phí bình quân đầu học sinh không được chính phủ trợ cấp (Full unsubsidized per capita cost) cho học khu trước khi được cấp visa; (3) Hết thời hạn 12 tháng, học sinh bắt buộc phải chuyển sang một trường THPT tư thục được SEVP chứng nhận hoặc trở về nước, không được phép chuyển sang trường công lập khác. Học sinh từ lớp mẫu giáo đến lớp 8 hoàn toàn không được cấp visa F-1 học trường công. (Nguồn kiểm chứng: 8 U.S.C. Section 1184(m) & SEVP Grade 9 to 12 Public Schools Guidance).', 'https://educationusa.state.gov', '2026-10-08'),
  ('Học sinh F-1 học trường THPT tư thục (Private High School) có bị giới hạn thời gian 12 tháng không?', 'faq_tu_van', 'draft', 'Học sinh diện visa F-1 theo học tại các trường THPT tư thục được SEVP chứng nhận hoàn toàn không bị giới hạn thời gian 12 tháng. Học sinh được phép theo học liên tục từ lớp 9 đến lớp 12 cho đến khi hoàn thành chương trình và nhận bằng tốt nghiệp THPT (High School Diploma) của Mỹ. Các trường tư thục có quy mô lớp học nhỏ, dịch vụ chăm sóc học sinh quốc tế tận tình và phần lớn đều cung cấp các lớp bổ trợ tiếng Anh (ESL) tích hợp cho học sinh chưa thành thạo ngôn ngữ. (Nguồn kiểm chứng: Study in the States - Kindergarten to Grade 12 Private Schools & 8 CFR 214.2(f)).', 'https://educationusa.state.gov', '2026-10-08'),
  ('Sự khác biệt giữa hình thức trường nội trú (Boarding School) và trường bán trú ở homestay (Day School)?', 'faq_tu_van', 'draft', 'Sự khác biệt giữa 2 mô hình THPT tại Mỹ: (1) Trường nội trú (Boarding School): Học sinh sinh hoạt và học tập hoàn toàn trong khuôn viên ký túc xá của trường, có sự quản lý và giám sát 24/7 của đội ngũ quản nhiệm, cơ sở vật chất thể thao và phòng thí nghiệm hiện đại, rất phù hợp cho học sinh chưa có người thân tại Mỹ nhưng chi phí cao hơn; (2) Trường bán trú ở cùng gia đình bản xứ (Day School + Homestay): Học sinh học tại trường vào ban ngày và về sinh hoạt cùng gia đình bản xứ người Mỹ (hoặc người thân hợp pháp), giúp rèn luyện khả năng giao tiếp đời thường và hòa nhập văn hóa gia đình với mức chi phí tiết kiệm hơn từ 30% đến 40%. (Nguồn kiểm chứng: The Association of Boarding Schools - TABS & CSIET Standards).', 'https://educationusa.state.gov', '2026-10-08'),
  ('Khung chi phí dự trù cho các loại hình trường THPT tại Mỹ (đã gồm học phí và ăn ở)?', 'faq_tu_van', 'draft', 'Khung chi phí tổng thể (đã bao gồm học phí, nhà ở, ăn uống và bảo hiểm) cho bậc THPT tại Mỹ ước tính theo từng loại hình: (1) Trường công lập diện F-1 (tối đa 1 năm): Tổng chi phí khoảng $18.000 - $26.000/năm (gồm học phí hoàn trả học khu khoảng $9.000 - $14.000 và chi phí homestay); (2) Trường tư thục bán trú kèm homestay (Day School): Tổng chi phí dao động từ $25.000 - $42.000/năm tùy khu vực; (3) Trường tư thục nội trú (Boarding School): Tổng chi phí dao động từ $45.000 đến $75.000/năm; các trường nội trú danh tiếng hàng đầu (như Phillips Andover, Choate) có thể lên đến $75.000 - $90.000/năm. (Nguồn kiểm chứng: TABS Boarding School Tuition Survey & CSIET).', 'https://educationusa.state.gov', '2026-10-08'),
  ('Học sinh mới học lớp 9 hỏi lộ trình lên Thạc sĩ thì định hướng tư vấn như thế nào?', 'faq_tu_van', 'draft', 'Đối với học sinh đang học lớp 9, việc định hướng chi tiết cho bậc Thạc sĩ là quá sớm và không thực tế vì sở thích học thuật và xu hướng thị trường việc làm sẽ thay đổi nhiều trong 7-8 năm tới. Lộ trình tư vấn chuẩn mực cần tập trung vào các mục tiêu thiết thực trước mắt: (1) Lựa chọn mô hình trường THPT phù hợp với năng lực và khả năng tài chính của gia đình; (2) Xây dựng nền tảng tiếng Anh vững chắc và duy trì điểm GPA tốt; (3) Khám phá các môn học thế mạnh và tham gia hoạt động ngoại khóa để định hình ngành học bậc Cử nhân; (4) Kế hoạch bậc Thạc sĩ sẽ được xem xét và quyết định sau khi sinh viên đã hoàn thành tối thiểu 2 năm học tại đại học. (Nguồn kiểm chứng: American School Counselor Association - ASCA Mindsets & Behaviors).', 'https://educationusa.state.gov', '2026-10-08')
) AS v(title, doc_type, status, content, source_url, retrieved_at)
WHERE NOT EXISTS (
    SELECT 1 FROM app.knowledge_documents kd WHERE kd.title = v.title
);

